Object.assign(window.TEM8_DICTIONARY, {"cleverly":{"oxford":{"phon":"ˈklevəli","pos":"adverb","senses":[{"en":"in a way that shows intelligence or skill, for example in the design of an object, in an idea or somebody's actions","cn":"精巧的；精明的","ex":{"en":"The bar’s layout has been cleverly designed to give a feeling of space without losing a certain cosiness.","cn":"酒吧的布局设计巧妙，给人一种空间感，同时又不失一定的舒适感。"}}]},"media":{"uk":"media/uk/cleverly__gb_1.mp3","us":"media/us/cleverly__us_1.mp3"},"examples":[{"en":"Lucy is quite clever and does well at school.","cn":""},{"en":"Bill’s very clever with his hands.","cn":""}]},"clean":{"media":{"uk":"media/uk/clean__gb_1.mp3","us":"media/us/clean__us_1.mp3"},"oxford":{"phon":"kliːn","pos":"adjective","senses":[{"en":"not dirty","cn":"清洁","lab":"British English","sc":"not dirty","ex":{"en":"Are your hands clean?","cn":"你的手干净吗？"}},{"en":"having a clean appearance and living in clean conditions","cn":"爱干净的；爱整洁的","sc":"not dirty","ex":{"en":"Cats are very clean animals.","cn":"猫是很爱干净的动物。"}},{"en":"free from harmful or unpleasant substances","cn":"无有害物的；无污染的","sc":"not harmful","ex":{"en":"clean water/air","cn":"清洁的水／空气"}},{"en":"with nothing written on it","cn":"空白的；未写过字的","g":"[usually before noun]","sc":"paper","ex":{"en":"a clean sheet of paper","cn":"一张空白纸"}},{"en":"not offensive or referring to sex; not doing anything that is considered bad or wrong","cn":"文明的；无色情的；正派的","sc":"not offensive","ex":{"en":"The entertainment was good clean fun for the whole family.","cn":"这种娱乐文明有趣，对全家老少都适合。"}},{"en":"not showing or having any record of doing something that is against the law","cn":"无犯罪记录的；守法的；清白的","sc":"not illegal","ex":{"en":"a clean driving licence/driver’s license","cn":"无违章记录的驾驶执照"}},{"en":"not owning or carrying anything illegal such as drugs or weapons","cn":"没有私藏（或携带）违禁品（如毒品、武器等）的","g":"[not usually before noun]","lab":"informal","sc":"not illegal","ex":{"en":"The police searched her but she was clean.","cn":"警察搜了她的身，但未发现她携带任何违禁品。"}},{"en":"not having taken drugs or alcohol","cn":"不吸毒；不酗酒","g":"[not usually before noun]","lab":"informal","sc":"not illegal","ex":{"en":"He's been clean for three weeks.","cn":"他已经戒瘾三个星期了。"}},{"en":"played or done in a fair way and within the rules","cn":"公平的；守规则的；不违例的","sc":"fair","ex":{"en":"It was a tough but clean game.","cn":"这是一场打得艰苦但规规矩矩的比赛。"}},{"en":"having a smooth edge, surface or shape; simple and regular","cn":"边缘平整的；表面平滑的；简洁规则的","sc":"smooth/simple","ex":{"en":"A sharp knife makes a clean cut.","cn":"快刀切得整齐。"}},{"en":"done with skill and in an accurate way","cn":"动作熟练而准确的；干净利落的","sc":"accurate","ex":{"en":"The plane made a clean take-off.","cn":"飞机起飞得干净利落。"}},{"en":"with no changes or mistakes in it","cn":"誊清的；校订好的","sc":"document/software","ex":{"en":"I do my utmost to produce clean copy, but occasionally a mistake slips in.","cn":"我尽力抄出清稿，但偶尔也会出错。"}},{"en":"tasting, smelling or looking pleasant and fresh","cn":"清醇的；清新的","sc":"taste/smell","ex":{"en":"The wine has a clean taste and a lovely golden colour.","cn":"这葡萄酒味道清醇，色泽金黄。"}},{"en":"to remove the dirt or dust from something","cn":"除去…的灰尘；使…干净；打扫","g":"[transitive, intransitive]","ex":{"en":"I spent all day cooking and cleaning.","cn":"我一整天都忙着做饭和打扫卫生。"},"pos":"verb"},{"en":"to become clean","cn":"变干净","g":"[intransitive]","ex":{"en":"This oven cleans easily (= is easy to clean).","cn":"这烤箱容易擦洗。"},"pos":"verb"},{"en":"to clean clothes using chemicals instead of water","cn":"指干洗","g":"[transitive]","ex":{"en":"This coat is filthy. I'll have it cleaned.","cn":"这件大衣脏了，我得送去干洗。"},"pos":"verb"},{"en":"to remove the inside parts of a fish, chicken, etc. before you cook it","cn":"（烹调前给鱼、鸡等）清除内脏","g":"[transitive]","ex":{"en":"Clean the fish and remove the backbone.","cn":"将鱼清洗干净，去掉鱼骨。"},"pos":"verb"},{"en":"used to emphasize that an action takes place completely","cn":"（行动）彻底地，完全地","ex":{"en":"The thief got clean away.","cn":"那小偷已逃之夭夭。"},"pos":"adverb"},{"en":"the act or process of cleaning something","cn":"打扫；清扫","ex":{"en":"The house needed a good clean.","cn":"这房子需要彻底打扫。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"干净的;洁净的;无污迹的","en":"Something that is clean is free from dirt or unwanted marks.","ex":{"en":"He wore his cleanest slacks, a clean shirt and a navy blazer","cn":"他穿着他最干净的便裤，洁净的衬衫和藏青色上装。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人或动物)讲卫生的，爱干净的","en":"You say that people or animals are clean when they keep themselves or their surroundings clean."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(燃料或化学作用)无害的，无污染的，清洁的","en":"A clean fuel or chemical process does not create many harmful or polluting substances.","ex":{"en":"Fans of electric cars say they are clean, quiet and economical.","cn":"电动汽车迷们说，电动车清洁、无噪音而且经济。"}},{"pos":"V-ERG 及物/不及物动词","cn":"清洗;清除;擦拭;擦洗","en":"If you clean something or clean dirt off it, you make it free from dirt and unwanted marks, for example by washing or wiping it. If something cleans easily, it is easy to clean.","ex":{"en":"Her father cleaned his glasses with a paper napkin","cn":"她父亲用纸巾把眼镜擦干净。"}},{"pos":"VERB 动词","cn":"打扫，清扫(房间、房屋)","en":"If you clean a room or house, you make the inside of it and the furniture in it free from dirt and dust.","ex":{"en":"With them also lived Mary Burinda, who cooked and cleaned","cn":"和他们同住的还有玛丽·伯琳达，她负责做饭和打扫卫生。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(书籍、笑话、生活方式)文明的，不淫秽的，不下流的","en":"If you describe something such as a book, joke, or lifestyle as clean, you think that they are not sexually immoral or offensive.","ex":{"en":"They're trying to show clean, wholesome, decent movies","cn":"他们尽量播放文明、健康、正派的电影。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(名声、履历)无污点的，清白的","en":"If someone has a clean reputation or record, they have never done anything illegal or wrong.","ex":{"en":"Accusations of tax evasion have tarnished his clean image","cn":"避税的指控使他的清白形象蒙污。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(比赛或打斗)无舞弊行为的，公平的，不违规的","en":"A clean game or fight is carried out fairly, according to the rules.","ex":{"en":"He called for a clean fight in the election and an end to 'negative campaigning'","cn":"他呼吁选举中进行公平竞争，结束“负面竞选”。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(口味、气味或色彩)淡雅的，清新的，明快的","en":"If you describe a flavour, smell, or colour as clean, you like it because it is light and fresh.","ex":{"en":"...the fresh, clean smell of the sea","cn":"大海清新舒爽的气味"}},{"pos":"ADJ 形容词","cn":"(纸张)空白的，无字迹的","en":"A clean sheet of paper has no writing or drawing on it.","ex":{"en":"Take a clean sheet of paper and down the left-hand side make a list.","cn":"拿张白纸，在左下方列个单子。"}},{"pos":"ADJ 形容词","cn":"(结束、开始)完全的，干脆的","en":"If you make a clean break or start, you end a situation completely and start again in a different way.","ex":{"en":"She wanted to make a clean break from her mother and father.","cn":"她想和父母一刀两断。"}},{"pos":"ADV 副词","cn":"(用于加强语气)完全，彻底","en":"Clean is used to emphasize that something was done completely.","ex":{"en":"It burned clean through the seat of my overalls","cn":"它把我工装裤屁股那块烧透了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(形状)规则的，简洁的，边缘平滑的","en":"A clean shape is simple and regular, with definite, smooth edges.","ex":{"en":"He admires the clean lines of Shaker furniture","cn":"他欣赏夏克家具流畅的线条。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(动作)干脆利落的，快速无误的","en":"You can describe an action as clean to indicate that it is carried out simply and quickly without mistakes.","ex":{"en":"They were more concerned about the dogs' welfare than a clean getaway","cn":"他们更加关心那些狗的安危，而非自己如何干净利落地脱身。"}},{"pos":"PHRASE 短语","cn":"坦白承认;和盘托出","en":"If you come clean about something that you have been keeping secret, you admit it or tell people about it.","ex":{"en":"It would be better if you come clean about it and let her know what kind of man she is seeing.","cn":"你最好一五一十地告诉她，让她知道她正在交往的那个男人是个什么货色。"}},{"pos":"","cn":"","en":"to clean up your act→see: ; a clean bill of health→see: ; to make a clean breast of it→see: ; to keep your nose clean→see: ; a clean slate→see: ; to wipe the slate clean→see: ; a clean sweep→see: ; clean as a whistle→see: ;"},{"pos":"","cn":"","en":"相关词组：clean out clean up clean up after"}]},"examples":[{"en":"The police searched her but she was clean.","cn":"警察搜了她的身，但未发现她携带任何违禁品。"},{"en":"Isn't it time the government came clean about their plans for education?","cn":"这难道不是政府彻底说明教育计划的时候了吗？"}]},"clip":{"media":{"uk":"media/uk/clip__gb_1.mp3","us":"media/us/clip__us_1.mp3"},"oxford":{"phon":"klɪp","pos":"noun","senses":[{"en":"a short part of a film that is shown separately","cn":"电影片段","g":"[countable]","ex":{"en":"Here is a clip from her latest movie.","cn":"这是她最新电影的片段。"}},{"en":"a small metal or plastic object used for holding things together or in place","cn":"（金属或塑料的）夹子，回形针","g":"[countable]","ex":{"en":"a hair clip","cn":"发夹"}},{"en":"a piece of jewellery that fastens to your clothes","cn":"首饰别针","g":"[countable]","ex":{"en":"a diamond clip","cn":"钻石别针"}},{"en":"the act of cutting something to make it shorter","cn":"剪短；修剪","g":"[singular]","ex":{"en":"He gave the hedge a clip.","cn":"他把树篱修剪了一下。"}},{"en":"a quick hit with your hand","cn":"（用手）猛击，抽打","g":"[countable]","lab":"British English, informal，，","ex":{"en":"She gave him a clip round the ear for being cheeky.","cn":"她因他放肆给了他一记耳光。"}},{"en":"a set of bullets in a metal container that is placed in or attached to a gun for firing","cn":"子弹夹；弹匣","g":"[countable]"},{"en":"to fasten something to something else with a clip; to be fastened with a clip","cn":"夹住；别住；被夹住","g":"[transitive, intransitive]","ex":{"en":"He clipped the microphone (on) to his collar.","cn":"他把麦克风别在衣领上。"},"pos":"verb"},{"en":"to cut something with scissors or shears, in order to make it shorter or neater; to remove something from somewhere by cutting it off","cn":"剪（掉）；修剪","g":"[transitive]","ex":{"en":"to clip a hedge","cn":"修剪树篱"},"pos":"verb"},{"en":"to hit the edge or side of something","cn":"碰撞（某物的边缘或侧面）","g":"[transitive]","ex":{"en":"The car clipped the kerb as it turned.","cn":"汽车转弯时撞上了马路牙子。"},"pos":"verb"},{"en":"to cut something out of something else using scissors","cn":"从…剪下","g":"[transitive]","ex":{"en":"to clip a coupon (out of the paper)","cn":"（从报纸上）剪下赠券"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(金属或塑料的)回形针，夹子","en":"A clip is a small device, usually made of metal or plastic, that is specially shaped for holding things together.","ex":{"en":"She took the clip out of her hair.","cn":"她把发夹取了下来。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(用夹子)夹住，夹在一起","en":"When you clip things together or when things clip together, you fasten them together using a clip or clips.","ex":{"en":"He clipped his safety belt to a fitting on the deck","cn":"他把安全带夹在甲板的一个固定装置上。"}},{"pos":"N-COUNT 可数名词","cn":"(电影、广播或电视节目的)剪辑，片段","en":"A clip from a film or a radio or television programme is a short piece of it that is broadcast separately.","ex":{"en":"...an historical film clip of Lenin speaking.","cn":"一段列宁在讲话的历史电影片段"}},{"pos":"VERB 动词","cn":"(尤指为使某物成形而)修剪，剪","en":"If you clip something, you cut small pieces from it, especially in order to shape it.","ex":{"en":"I saw an old man out clipping his hedge","cn":"我看见一位老人在外面修剪树篱。"}},{"pos":"VERB 动词","cn":"(从报纸或杂志上)剪下","en":"If you clip something out of a newspaper or magazine, you cut it out.","ex":{"en":"Kids in his neighborhood clipped his picture from the newspaper and carried it around.","cn":"附近的孩子们从报纸上剪下他的照片，到哪儿都带着。"}},{"pos":"VERB 动词","cn":"(意外地)斜撞，侧击","en":"If something clips something else, it hits it accidentally at an angle before moving off in a different direction.","ex":{"en":"The lorry clipped the rear of a tanker and then crashed into a second truck.","cn":"大货车斜撞上一辆油罐车的尾部，接着又撞上了另一辆货车。"}},{"pos":"N-COUNT 可数名词","cn":"(通常指作为惩罚的)耳光，抽打","en":"If you give someone a clip round the ear, you hit their head fairly lightly with the palm of your hand, usually as a punishment.","ex":{"en":"The boy was later given a clip round the ear by his father.","cn":"后来男孩被父亲打了一耳光。"}},{"pos":"VERB 动词","cn":"削减，缩短（时间）","en":"If you clip a small amount off the time taken to do something, you reduce it by that amount.","ex":{"en":"Boardman finished in 1hr 43mins, clipping 49 seconds from his own course record.","cn":"博德曼完成全程用时1小时43分，把自己的赛道纪录缩短了49秒。"}},{"pos":"N-COUNT 可数名词","cn":"弹夹;弹匣;弹仓","en":"An ammunition clip is a metal container on an automatic weapon which holds ammunition."},{"pos":"PHRASE 短语","cn":"快速地；飞速地","en":"If something moves or happens at a fast clip, it moves or happens quickly.","ex":{"en":"They moved out from the airport at a brisk clip","cn":"他们迅速撤离机场。"}},{"pos":"","cn":"","en":"to clip someone's wings→see: ;"}]},"examples":[{"en":"She clipped two seconds off her previous best time.","cn":"她把自己之前的最佳纪录缩短了两秒。"},{"en":"Here is a clip from her latest movie.","cn":"这是她最近一部电影的片段。"}]},"climbing":{"media":{"uk":"media/uk/climbing__gb_1.mp3","us":"media/us/climbing__us_1.mp3"},"oxford":{"phon":"ˈklaɪmɪŋ","pos":"noun","senses":[{"en":"the sport or activity of climbing rocks or mountains","cn":"登山运动；攀岩活动","ex":{"en":"to go climbing","cn":"去登山"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"登山运动;攀岩运动","en":"Climbing is the activity of climbing rocks or mountains."}]},"examples":[{"en":"a climbing accident","cn":"登山事故"},{"en":"to go climbing","cn":"去登山"}]},"cleaner":{"media":{"uk":"media/uk/cleaner__gb_1.mp3","us":"media/us/cleaner__us_1.mp3"},"oxford":{"phon":"ˈkliːnə(r)","pos":"noun","senses":[{"en":"a person whose job is to clean other people’s houses or offices, etc.","cn":"清洁工","ex":{"en":"an office cleaner","cn":"办公室清洁工"}},{"en":"a machine or substance that is used for cleaning","cn":"吸尘器；清洁剂；去污剂","ex":{"en":"a vacuum cleaner","cn":"真空吸尘器"}},{"en":"a shop where clothes, curtains, etc. are cleaned, especially with chemicals","cn":"干洗店","ex":{"en":"Can you pick up my suit from the cleaner's?","cn":"你能帮我从干洗店取回我的套装吗？"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（大楼的）保洁员，清洁工","en":"A cleaner is someone who is employed to clean the rooms and furniture inside a building."},{"pos":"N-COUNT 可数名词","cn":"(专业的)清洁工","en":"A cleaner is someone whose job is to clean a particular type of thing.","ex":{"en":"He was a window cleaner.","cn":"他是个洗窗工。"}},{"pos":"N-MASS 物质名词","cn":"清洗剂;去污剂","en":"A cleaner is a substance used for cleaning things.","ex":{"en":"...oven cleaner.","cn":"烤箱清洁剂"}},{"pos":"N-COUNT 可数名词","cn":"清洁器;吸尘器","en":"A cleaner is a device used for cleaning things.","ex":{"en":"...an air cleaner.","cn":"空气净化器"}},{"pos":"N-COUNT 可数名词","cn":"干洗店","en":"A cleaner or a cleaner's is a shop where things such as clothes are dry-cleaned."},{"pos":"PHRASE 短语","cn":"骗走，骗光(钱财)","en":"If someone takes you to the cleaners, they unfairly take most of your money, for example in a business deal or in gambling."}]},"examples":[{"en":"Can you pick up my suit from the cleaner's?","cn":"你能帮我从干洗店取回我的西服吗？"},{"en":"Our team got taken to the cleaners.","cn":"我们队被打得一败涂地。"}]},"cloud":{"media":{"uk":"media/uk/cloud__gb_1.mp3","us":"media/us/cloud__us_1.mp3","img":["media/ldoce/img/clouds.jpg"]},"oxford":{"phon":"klaʊd","pos":"noun","senses":[{"en":"a grey or white mass that floats in the sky, made of very small drops of water","cn":"云；云彩；云朵","g":"[countable, uncountable]","lab":"North American English","ex":{"en":"Dark clouds were gathering in the west.","cn":"乌云在西边聚集。"}},{"en":"a large mass of something in the air, for example dust or smoke, or a number of insects flying all together","cn":"一团，一大片（尘雾、烟雾或一群飞行的昆虫等）","g":"[countable]","ex":{"en":"a dust cloud","cn":"一团烟尘"}},{"en":"something that makes you feel sad or anxious","cn":"阴影；忧郁；焦虑；令人忧虑的事","g":"[countable]","ex":{"en":"Her father's illness cast a cloud over her wedding day.","cn":"她父亲的病给她的结婚喜庆日蒙上了一层阴影。"}},{"en":"a network of servers (= computers that control or supply information to other computers) on which data and software can be stored or managed and to which users have access over the internet","cn":"云（可存储或管理数据和软件的服务器网络，用户通过互联网访问）","g":"[singular]","ex":{"en":"Key company documents are now stored in the cloud, so you no longer need to save them to your computer’s hard drive.","cn":"公司最重要的文档现在存储在云端，因此不必再将它们保存到计算机硬盘。"}},{"en":"if something clouds your judgement, memory, etc., it makes it difficult for you to understand or remember something clearly","cn":"使难以理解；使记不清楚；使模糊","g":"[transitive]","ex":{"en":"Doubts were beginning to cloud my mind.","cn":"诸多疑问开始使我的思路变模糊了。"},"pos":"verb"},{"en":"to show that you feel sad, afraid, angry, etc.; to make somebody look sad, afraid, angry, etc.","cn":"显得阴沉（或恐惧、愤怒等）；看起来忧愁（或害怕、愤怒等）","g":"[intransitive, transitive]","lab":"formal","ex":{"en":"Her face clouded over with anger.","cn":"她满面怒容。"},"pos":"verb"},{"en":"to make something you are discussing or considering less clear, especially by introducing subjects that are not connected with it","cn":"（尤指用无关的话题来）混淆，搅混（问题）","g":"[transitive]","ex":{"en":"Cost factors should not be allowed to cloud the issue.","cn":"不应该用成本因素来混淆这个问题。"},"pos":"verb"},{"en":"to fill with clouds","cn":"布满云","g":"[intransitive]","ex":{"en":"It was beginning to cloud over.","cn":"天空开始阴云密布。"},"pos":"verb"},{"en":"to make something less pleasant","cn":"使减少乐趣；使不快","g":"[transitive]","ex":{"en":"His last years were clouded by financial worries.","cn":"由于经济窘困，他的晚年生活过得闷闷不乐。"},"pos":"verb"},{"en":"if glass, water, etc. clouds, or if something clouds it, it becomes less easy to see through","cn":"（使）不透明；（使）模糊","g":"[intransitive, transitive]","ex":{"en":"Her eyes clouded with tears.","cn":"泪水模糊了她的眼睛。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"云;云团","en":"A cloud is a mass of water vapour that floats in the sky. Clouds are usually white or grey in colour.","ex":{"en":"...the varied shapes of the clouds","cn":"云朵各种各样的形状"}},{"pos":"N-COUNT 可数名词","cn":"(烟雾、尘土等的)一团","en":"A cloud of something such as smoke or dust is a mass of it floating in the air.","ex":{"en":"The hens darted away on all sides, raising a cloud of dust.","cn":"一群母鸡四处乱窜，搅起一团尘土。"}},{"pos":"VERB 动词","cn":"把…搞糊涂;使难以理解；使无法正确判断","en":"If you say that something clouds your view of a situation, you mean that it makes you unable to understand the situation or judge it properly.","ex":{"en":"Perhaps anger had clouded his vision, perhaps his judgment had been faulty","cn":"可能是愤怒蒙蔽了他的眼睛，也可能是他判断有误。"}},{"pos":"VERB 动词","cn":"破坏;给…蒙上阴影","en":"If you say that something clouds a situation, you mean that it makes it unpleasant.","ex":{"en":"The atmosphere has already been clouded by the BJP's anger at the media.","cn":"印度人民党怒斥媒体，已经破坏了气氛。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(眼神或脸色)阴沉，忧郁；使看起来阴沉（或忧郁）","en":"If your eyes or face cloud or if sadness or anger clouds them, your eyes or your face suddenly show sadness or anger.","ex":{"en":"Trish's face clouded with disappointment","cn":"翠茜一脸失望。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(镜子)模糊不清;(使)起雾","en":"If glass clouds or if moisture clouds it, tiny drops of water cover the glass, making it difficult to see through.","ex":{"en":"The mirror clouded beside her cheek","cn":"她面颊边的镜子变得模糊不清。"}},{"pos":"PHRASE 短语","cn":"心不在焉;耽于空想","en":"If you say that someone has their head in the clouds, you are criticizing them because they are ignoring or are unaware of the problems associated with a situation."},{"pos":"PHRASE 短语","cn":"极为快乐;乐不可支","en":"If you say that someone is on cloud nine, you are emphasizing that they are very happy.","ex":{"en":"When Michael was born I was on cloud nine.","cn":"迈克尔出生的时候，我都乐得找不着北了。"}},{"pos":"PHRASE 短语","cn":"遭嫌弃；被贬低","en":"If someone is under a cloud, people have a poor opinion of them because of something they have done.","ex":{"en":"The military are under a cloud for killing civilians while breaking up a demonstration.","cn":"军方因在平息示威活动时杀死了无辜平民而备受指责。"}},{"pos":"","cn":"","en":"every cloud has a silver lining→see: ;"},{"pos":"","cn":"","en":"相关词组：cloud over"}]},"examples":[{"en":"Her father's illness cast a cloud over her wedding day.","cn":"她父亲的病给她的结婚喜庆日蒙上了一层阴影。"},{"en":"His last years were clouded by financial worries.","cn":"由于经济窘困，他的晚年生活过得闷闷不乐。"}]},"clutch":{"media":{"uk":"media/uk/clutch__gb_1.mp3","us":"media/us/clutch__us_1.mp3"},"oxford":{"phon":"klʌtʃ","pos":"verb","senses":[{"en":"to hold somebody/something tightly","cn":"紧握；抱紧；抓紧","g":"[transitive, intransitive]","ex":{"en":"He clutched the child to him.","cn":"他紧紧地抱住小孩。"}},{"en":"to take hold of something suddenly, because you are afraid or in pain","cn":"（因害怕或痛苦）突然抓住","g":"[transitive, intransitive]","lab":"figurative","ex":{"en":"He gasped and clutched his stomach.","cn":"他喘着气突然按住自己的胃部。"}},{"en":"the pedal in a car or other vehicle that you press with your foot so that you can change gear","cn":"（汽车等换挡用的）离合器踏板","g":"[countable]","lab":"British English","ex":{"en":"Put your foot on the clutch.","cn":"把你的脚放在离合器踏板上。"},"pos":"noun"},{"en":"a device in a machine that connects and disconnects working parts, especially the engine and the gears","cn":"（尤指发动机和排挡的）离合器","g":"[countable]","ex":{"en":"The car needs a new clutch.","cn":"这辆车需要换一个新的离合器了。"},"pos":"noun"},{"en":"a group of people, animals or things","cn":"一群（人或动物）；一批（物品）","g":"[singular]","ex":{"en":"He's won a whole clutch of awards.","cn":"他获了一大堆奖。"},"pos":"noun"},{"en":"power or control","cn":"势力范围；控制；掌管","g":"[plural]","lab":"informal","ex":{"en":"He managed to escape from their clutches.","cn":"他设法摆脱了他们的控制。"},"pos":"noun"},{"en":"a tight hold on somebody/something","cn":"攫住；紧紧抓住","g":"[countable, usually singular]","lab":"figurative","ex":{"en":"She felt the sudden clutch of fear.","cn":"她突然感到一阵恐惧。"},"pos":"noun"},{"en":"a group of eggs that a bird lays at one time; the young birds that come out of a group of eggs at the same time","cn":"（一次下的）一窝蛋；（同时孵出的）一窝小鸟","g":"[countable]","ex":{"en":"The female lays a clutch of about seven eggs, laying one egg each day.","cn":"雌性产下一窝大约七个蛋，每天产一个蛋。"},"pos":"noun"},{"en":"a small, flat bag that women carry in their hands, especially on formal occasions","cn":"（尤指出席正式场合时用的）女士手拿包","g":"[countable]","pos":"noun"},{"en":"referring to or performing at an important moment that will decide the result of a game or competition","cn":"势力范围；控制；掌管","ex":{"en":"Miami succeeds in clutch situations better than any other team.","cn":"迈阿密在关键时刻比任何其他球队都更成功。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(通常因害怕或担心)紧握，紧抓","en":"If you clutch at something or clutch something, you hold it tightly, usually because you are afraid or anxious.","ex":{"en":"I staggered and had to clutch at a chair for support","cn":"我踉踉跄跄地，不得不抓住一把椅子稳住自己。"}},{"pos":"N-PLURAL 复数名词","cn":"控制;掌握;势力范围","en":"If someone is in another person's clutches, that person has captured them or has power over them.","ex":{"en":"Tony fell into the clutches of an attractive American who introduced him to drugs","cn":"托尼落入了一个英俊的美国人的控制中，这个人引他走上了吸毒之路。"}},{"pos":"N-COUNT 可数名词","cn":"(车辆的)离合器踏板","en":"In a vehicle, the clutch is the pedal that you press before you change gear.","ex":{"en":"Laura let out the clutch and pulled slowly away down the drive.","cn":"劳拉松开离合器踏板，沿车道慢慢驶离。"}},{"pos":"N-COUNT 可数名词","cn":"一窝(蛋)","en":"A clutch of eggs is a number of eggs laid by a bird at one time.","ex":{"en":"...the second clutch of eggs.","cn":"第二窝蛋"}},{"pos":"N-COUNT 可数名词","cn":"一小群;一小簇","en":"A clutch of people or things is a small group of them.","ex":{"en":"The party has attracted a clutch of young southern liberals.","cn":"聚会吸引了一群南部的年轻开明人士。"}},{"pos":"","cn":"","en":"to clutch at straws→see: ;"}]},"examples":[{"en":"Now that she had him in her clutches , she wasn't going to let go.","cn":"她既然已经把他控制在自己手里，就不打算让他脱身。"},{"en":"She stood there, the flowers still clutched in her hand.","cn":"她站在那里，手里仍然紧握着花束。"}]},"classical":{"oxford":{"phon":"ˈklæsɪkl","pos":"adjective","senses":[{"en":"relating to classical music","cn":"古典音乐的","lab":"British English","ex":{"en":"a classical composer/musician/pianist","cn":"古典音乐作曲家／音乐家／钢琴家"}},{"en":"widely accepted and used for a long time; traditional in style or idea","cn":"古典的；经典的；传统的","ex":{"en":"the classical economics of Smith and Ricardo","cn":"斯密与李嘉图的古典经济学"}},{"en":"connected with or influenced by the culture of ancient Greece and Rome","cn":"和古希腊与古罗马文化相关的；受古希腊与古罗马文化影响的","ex":{"en":"classical studies","cn":"古希腊与古罗马的文化研究"}},{"en":"with all the features you would expect to find; very typical","cn":"有代表性的；典型的","lab":"more frequent","ex":{"en":"These are classical examples of food allergy.","cn":"这些是食物过敏的典型病例。"}},{"en":"ancient in its form and no longer used in a spoken form","cn":"古文的；文言的","ex":{"en":"classical Arabic","cn":"古阿拉伯语"}},{"en":"simple and attractive","cn":"简洁优美的；朴实美观的","ex":{"en":"the classical elegance of the design","cn":"设计简洁典雅"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(形式、风格或内容)传统的，正统的，古典的","en":"You use classical to describe something that is traditional in form, style, or content.","ex":{"en":"Fokine did not change the steps of classical ballet; instead he found new ways of using them.","cn":"福金没有改变传统芭蕾舞的舞步，而是另辟蹊径对这些舞步加以运用。"}},{"pos":"ADJ 形容词","cn":"(音乐)古典的，严肃的","en":"Classical music is music that is considered to be serious and of lasting value."},{"pos":"ADJ 形容词","cn":"古典文化的;古希腊(或古罗马)文明的","en":"Classical is used to describe things which relate to the ancient Greek or Roman civilizations.","ex":{"en":"...the healers of ancient Egypt and classical Greece","cn":"古埃及和古希腊的治疗术士"}},{"pos":"ADJ 形容词","cn":"古文的;文言的","en":"A classical language is a form of a language that was used in ancient times and is now no longer used, or only used in formal writing.","ex":{"en":"...a line of classical Arabic poetry.","cn":"古阿拉伯语诗歌的一行诗句"}}]},"media":{"uk":"media/uk/classical__gb_1.mp3","us":"media/us/classical__us_1.mp3"},"examples":[{"en":"He plays classical music, as well as pop and jazz.","cn":"他既演奏古典音乐，也演奏流行音乐和爵士乐。"},{"en":"the classical economics of Smith and Ricardo","cn":"亚当 · 斯密与李嘉图的古典经济学"}]},"cleaning":{"oxford":{"phon":"ˈkliːnɪŋ","pos":"noun","senses":[{"en":"the work of making the inside of a house, etc. clean","cn":"打扫；扫除；清洁","ex":{"en":"They pay someone to do the cleaning.","cn":"他们花钱雇人打扫。"}}]},"media":{"img":["media/pic/cleaning_comp.jpg","media/thumb/dustpan.jpg"],"uk":"media/uk/cleaning__gb_1.mp3","us":"media/us/cleaning__us_1.mp3"},"examples":[{"en":"They pay someone to do the cleaning.","cn":"他们花钱雇人打扫。"},{"en":"Liz comes on Thursdays to do the cleaning .","cn":"利兹每周四来打扫。"}]},"clearly":{"media":{"uk":"media/uk/clearly__gb_1.mp3","us":"media/us/clearly__us_1.mp3"},"oxford":{"phon":"ˈklɪəli","pos":"adverb","senses":[{"en":"in a way that is easy to see or hear","cn":"清楚地；清晰地","ex":{"en":"Please speak clearly after the tone.","cn":"请听到信号后清楚地讲话。"}},{"en":"in a way that is sensible and easy to understand","cn":"明白地；易懂地","ex":{"en":"She explained everything very clearly.","cn":"她把一切都解释得很明白。"}},{"en":"used to emphasize that what you are saying is obvious and true","cn":"明显地；显然地","ex":{"en":"Clearly, this will cost a lot more than we realized.","cn":"显而易见，这将比我们以前了解到的花费要多得多。"}}]},"examples":[{"en":"Clearly, this will cost a lot more than we realized.","cn":"显而易见，这将比我们所以为的花费要多得多。"},{"en":"Please speak clearly after the tone.","cn":"请听到信号后清楚地讲话。"}]},"clarity":{"media":{"uk":"media/uk/clarity__gb_1.mp3","us":"media/us/clarity__us_1.mp3"},"oxford":{"phon":"ˈklærəti","pos":"noun","senses":[{"en":"the quality of being expressed clearly","cn":"清晰；清楚；明确","ex":{"en":"a lack of clarity in the law","cn":"法律上不明确"}},{"en":"the ability to think about or understand something clearly","cn":"清晰的思维（或理解）能力","ex":{"en":"clarity of thought/purpose/vision","cn":"思路清楚；目的明确；视野清晰"}},{"en":"if a picture, substance or sound has clarity, you can see or hear it very clearly, or see through it easily","cn":"（画面、物质或声音的）清晰，清楚，清澈","ex":{"en":"the clarity of the sound on the recording","cn":"录音的清晰音质"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(书、论点等的)清楚，清晰易懂，明晰","en":"The clarity of something such as a book or argument is its quality of being well explained and easy to understand.","ex":{"en":"...the ease and clarity with which the author explains difficult technical and scientific subjects.","cn":"作者解释复杂的科技主题时的游刃有余、清晰透彻"}},{"pos":"N-UNCOUNT 不可数名词","cn":"思路清晰;有条理","en":"Clarity is the ability to think clearly.","ex":{"en":"In business circles he is noted for his flair and clarity of vision.","cn":"在商界，他的天赋和远见卓识是出了名的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(轮廓、声音的)清楚，清晰","en":"Clarity is the quality of being clear in outline or sound.","ex":{"en":"This remarkable technology provides far greater clarity than conventional x-rays.","cn":"这项卓越技术的清晰度比常规的X光高得多。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(液体、玻璃或空气的)清澈度，透明度","en":"The clarity of a liquid, of glass, or of the air is the degree to which it is clear.","ex":{"en":"The first thing to strike me was the amazing clarity of the water.","cn":"首先吸引我的是水的无比清澈。"}}]},"examples":[{"en":"the clarity of sound on a CD","cn":"激光唱片的清晰音质"},{"en":"a lack of clarity in the law","cn":"法律上不明确"}]},"cloth":{"media":{"uk":"media/uk/cloth__gb_1.mp3","us":"media/us/cloth__us_1.mp3"},"oxford":{"phon":"klɒθ","pos":"noun","senses":[{"en":"material made by weaving or knitting cotton, wool, silk, etc.","cn":"织物；布料","g":"[uncountable]","ex":{"en":"woollen/cotton/linen cloth","cn":"毛料；棉布料；亚麻布料"}},{"en":"a piece of cloth, often used for a special purpose, especially cleaning things or covering a table","cn":"（一块）布；（尤指一块）抹布，桌布","g":"[countable]","ex":{"en":"Wipe the surface with a damp cloth.","cn":"用湿布擦表面。"}},{"en":"used to refer to Christian priests as a group","cn":"（统称）牧师，神父","g":"[singular]","lab":"literary","ex":{"en":"a man of the cloth","cn":"一位牧师"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"(尤用于制衣的)布，织物，布料","en":"Cloth is fabric which is made by weaving or knitting a substance such as cotton, wool, silk, or nylon. Cloth is used especially for making clothes. →see usage note at:","ex":{"en":"She began cleaning the wound with a piece of cloth.","cn":"她开始用一块布清洗伤口。"}},{"pos":"N-COUNT 可数名词","cn":"(用于特定用途的)布","en":"A cloth is a piece of cloth which you use for a particular purpose, such as cleaning something or covering something.","ex":{"en":"Clean the surface with a damp cloth.","cn":"用湿布清洁表面。"}},{"pos":"N-SING 单数名词","cn":"(统称)牧师，神父","en":"The cloth is sometimes used to refer to Christian priests and ministers.","ex":{"en":"I've got as much respect for the cloth as the next man.","cn":"我和任何人一样都对神父充满敬意。"}}]},"examples":[{"en":"Wipe the surface with a damp cloth.","cn":"用湿布擦拭表面。"},{"en":"bandages made from strips of cloth","cn":"用布条做的绷带"}]},"climb":{"media":{"uk":"media/uk/climb__gb_1.mp3","us":"media/us/climb__us_1.mp3"},"oxford":{"phon":"klaɪm","pos":"verb","senses":[{"en":"to go up something towards the top","cn":"攀登；爬","g":"[transitive, intransitive]","sc":"go up","ex":{"en":"to climb a mountain/tree","cn":"爬山；爬树"}},{"en":"to go up mountains or climb rocks as a hobby or sport","cn":"登山，攀岩（作为业余爱好或运动）","sc":"go up","ex":{"en":"He likes to go climbing most weekends.","cn":"在多数周末他都喜欢去登山。"}},{"en":"to move somewhere, especially with difficulty or effort, using hands as well as feet","cn":"（尤指手足并用吃力地向某处）爬","g":"[intransitive]","sc":"go through/down/over","ex":{"en":"I climbed through the window.","cn":"我从窗口爬过去。"}},{"en":"to increase in value or amount","cn":"上升；增值；升值","g":"[intransitive]","sc":"increase","ex":{"en":"The paper's circulation continues to climb.","cn":"这份报纸的发行量持续增长。"}},{"en":"to move to a higher position in a chart, table, society or organization","cn":"（在排行榜、社会或组织中）上升，爬升，晋升","g":"[intransitive, transitive]","lab":"figurative","sc":"improve position/status","ex":{"en":"The team has now climbed to fourth in the league.","cn":"这支队现已上升到联赛的第四名。"}},{"en":"to go higher in the sky","cn":"爬升；上升","g":"[intransitive]","sc":"aircraft/sun, etc.","ex":{"en":"The plane climbed to 33 000 feet.","cn":"飞机爬升到 33 000 英尺。"}},{"en":"to slope upwards","cn":"倾斜上升","g":"[intransitive]","sc":"slope up","ex":{"en":"From here the path climbs steeply to the summit.","cn":"这条小路从这里突然变陡，直上山顶。"}},{"en":"to grow up a wall or frame","cn":"（沿墙或架子）攀缘生长","g":"[intransitive]","sc":"of plants","ex":{"en":"a climbing rose","cn":"攀缘生长的玫瑰"}},{"en":"an act of climbing up a mountain, rock or large number of steps; a period of time spent climbing","cn":"攀登；攀缘；爬阶梯；攀登用的时间","sc":"mountain/steps","ex":{"en":"an exhausting climb","cn":"令人精疲力竭的攀登"},"pos":"noun"},{"en":"a mountain or rock which people climb up for sport","cn":"（登山或攀岩运动的）山，岩","sc":"mountain/steps","ex":{"en":"Titan's Wall is the mountain's hardest rock climb.","cn":"“巨人墙”是这座山最难攀登的一段山岩。"},"pos":"noun"},{"en":"an increase in value or amount","cn":"增值；升值；增加","g":"[usually singular]","sc":"increase","ex":{"en":"the dollar’s climb against the euro","cn":"美元对欧元的升值"},"pos":"noun"},{"en":"progress to a higher status, standard or position","cn":"（地位、标准、身份的）跃升，提高，晋升","g":"[usually singular]","sc":"to a higher position or status","ex":{"en":"a rapid climb to stardom","cn":"一跃而成为明星"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"爬","en":"If you climb something such as a tree, mountain, or ladder, or climb up it, you move towards the top of it. If you climb down it, you move towards the bottom of it.","ex":{"en":"Climbing the first hill took half an hour","cn":"爬第一座小山花了半个钟头。"}},{"pos":"VERB 动词","cn":"小心翼翼地爬动","en":"If you climb somewhere, you move there carefully, for example because you are moving into a small space or trying to avoid falling.","ex":{"en":"The girls hurried outside, climbed into the car, and drove off","cn":"姑娘们匆忙跑了出来，爬进汽车，然后开车走了。"}},{"pos":"VERB 动词","cn":"(飞机等)爬升，升高;(太阳)升高，上升","en":"When something such as an aeroplane climbs, it moves upwards to a higher position. When the sun climbs, it moves higher in the sky.","ex":{"en":"The plane took off for LA, lost an engine as it climbed, and crashed just off the runway.","cn":"飞机起飞前往洛杉矶，在爬升过程中一台发动机熄火，刚飞离跑道就坠毁了。"}},{"pos":"VERB 动词","cn":"增值;(数量)上涨，增加","en":"When something climbs, it increases in value or amount.","ex":{"en":"The nation's unemployment rate has been climbing steadily since last June","cn":"自去年6月以来，该国的失业率一直在不断上升。"}},{"pos":"See also:","cn":"","en":"a mountain to climb→see: ;"},{"pos":"","cn":"","en":"相关词组：climb down"}]},"examples":[{"en":"Titan's Wall is the mountain's hardest rock climb. “","cn":"巨人墙”是这座山最难攀登的一段山岩。"},{"en":"As they climbed higher, the air became cooler.","cn":"他们攀登得越高，空气就变得越凉爽。"}]},"client":{"media":{"uk":"media/uk/client__gb_1.mp3","us":"media/us/client__us_1.mp3"},"oxford":{"phon":"ˈklaɪənt","pos":"noun","senses":[{"en":"a person who uses the services or advice of a professional person or organization","cn":"委托人；当事人；客户","ex":{"en":"She's a well-known lawyer with many famous clients.","cn":"她是一个知名律师，有许多著名的委托人。"}},{"en":"a computer that is linked to a server","cn":"（连接在服务器上的）客户机","lab":"computing"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"客户;顾客；委托人","en":"A client of a professional person or organization is a person or company that receives a service from them in return for payment.","ex":{"en":"...a solicitor and his client","cn":"律师和他的委托人"}}]},"examples":[{"en":"Social workers must always consider the best interests of their clients.","cn":"社会工作者必须时刻考虑其当事人的最佳利益。"},{"en":"a lawyer with many famous clients","cn":"接受许多名人委托的律师"}]},"closeness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"almost the same","cn":""},{"en":"similar to something or someone else","cn":""}]},"examples":[{"en":"If you need to buy bread or milk, the closest shop is about a mile away.","cn":"","src":"ld"},{"en":"Susan sat on a chair close to the window.","cn":"","src":"ld"}],"media":{"uk":"media/uk/closeness__gb_1.mp3","us":"media/us/closeness__us_1.mp3"},"oxford":{"phon":"ˈkləʊsnəs","pos":"noun","senses":[{"en":"the fact of being near to somebody/something in space or time","cn":"亲密：在空间或时间上接近某人/某物","g":"[uncountable]","ex":{"en":"Maltese cuisine is influenced by Malta’s physical closeness to Italy.","cn":"马耳他美食受到马耳他毗邻意大利的影响。"}},{"en":"the fact of knowing somebody/something very well and liking them very much","cn":"亲密的；密切的","g":"[uncountable, singular]","ex":{"en":"She suffered from a lack of emotional closeness.","cn":"她缺乏情感上的亲密感。"}},{"en":"the fact of being very involved in the work or activities of somebody else, usually seeing and talking to them regularly","cn":"（与某人的工作或活动）紧密相关的，密切的","g":"[uncountable]","ex":{"en":"The closeness of these working relationships may result in difficult situations for nurses.","cn":"这些工作关系的密切可能会给护士带来困难。"}},{"en":"the fact of being won or likely to be won by only a small amount or distance","cn":"实力相差无几的；仅以些微之差获胜的","g":"[uncountable]","ex":{"en":"All the emphasis on the closeness of the election may encourage more people to vote.","cn":"所有对选举接近性的强调可能会鼓励更多人投票。"}}]}},"claims":{"oxford":{"phon":"kleɪm","pos":"verb","senses":[{"en":"to say that sth is true although it has not been proved and other people may not believe it","cn":"宣称；声称；断言"},{"en":"to demand or ask for sth because you believe it is your legal right to own or to have it","cn":"要求（拥有）；索取；认领"}]},"media":{"uk":"media/uk/claim__gb_1.mp3","us":"media/us/claim__us_1.mp3"}},"clear":{"media":{"uk":"media/uk/clear__gb_1.mp3","us":"media/us/clear__us_1.mp3"},"oxford":{"phon":"klɪə(r)","pos":"adjective","senses":[{"en":"easy to understand and not confusing","cn":"清晰易懂的；明白清楚的；不含混的","sc":"easy to understand","ex":{"en":"She gave me clear and precise directions.","cn":"她给了我清晰而准确的指示。"}},{"en":"obvious and leaving no doubt at all","cn":"明显的；显然的；明确的","sc":"without doubt","ex":{"en":"This is a clear case of fraud.","cn":"这无疑是一桩诈骗案。"}},{"en":"not confused; having no doubt","cn":"了解清楚的；没有疑问的","sc":"without doubt","ex":{"en":"Are you clear about the arrangements for tomorrow?","cn":"你清楚明天的安排吗？"}},{"en":"thinking in a sensible and logical way, especially in a difficult situation","cn":"（尤指在困境中）思维敏锐而有逻辑的，头脑清醒的","sc":"mind","ex":{"en":"a clear thinker","cn":"思路清晰的人"}},{"en":"easy to see or hear","cn":"容易看见的；听得清的","sc":"easy to see/hear","ex":{"en":"The photo wasn't very clear.","cn":"这张照片不太清晰。"}},{"en":"that you can see through; transparent","cn":"透明的；清澈的","sc":"easy to see through","ex":{"en":"The water was so clear we could see the bottom of the lake.","cn":"湖水清澈见底。"}},{"en":"without cloud or mist","cn":"无云（或雾）的；晴朗的","sc":"sky/weather","ex":{"en":"a clear blue sky","cn":"晴朗的碧空"}},{"en":"without spots or marks","cn":"无斑（或疤痕）的","sc":"skin","ex":{"en":"clear skin","cn":"没有丝毫斑点的皮肤"}},{"en":"bright and lively","cn":"明亮有神的","sc":"eyes","ex":{"en":"Her clear blue eyes sparkled.","cn":"她清澈的蓝眼睛闪闪发亮。"}},{"en":"free from things that are blocking the way or covering the surface of something","cn":"畅通无阻的；无障碍的；（表面）收拾干净的","sc":"not blocked","ex":{"en":"The road was clear and I ran over.","cn":"路上没有东西挡着，我就跑了过来。"}},{"en":"if you have a clear conscience or your conscience is clear, you do not feel guilty","cn":"无罪的；清白的；问心无愧的","sc":"conscience"},{"en":"free from something that is unpleasant","cn":"摆脱掉（不愉快事物）的","sc":"free from something bad","ex":{"en":"They were still not clear of all suspicion.","cn":"他们仍未解除所有的嫌疑。"}},{"en":"not touching something; a distance away from something","cn":"不接触；远离","g":"[not before noun]","sc":"not touching/near","ex":{"en":"The plane climbed until it was clear of the clouds.","cn":"飞机爬升直至穿出了云层。"}},{"en":"whole or complete","cn":"全部的；整体的；完整的","g":"[only before noun]","sc":"period of time","ex":{"en":"Allow three clear days for the letter to arrive.","cn":"信要整整三天才能寄到。"}},{"en":"that remains when taxes, costs, etc. have been taken away","cn":"（扣除税项、成本等后）净的，纯的","g":"[only before noun]","sc":"sum of money","ex":{"en":"They had made a clear profit of £2 000.","cn":"他们已赚得 2 000 英镑的净利。"}},{"en":"produced with the central part of the tongue close to the top of the mouth. In many accents of (= ways of pronouncing) English, clear /l/ is used before a vowel, as in leave.","cn":"清晰的","sc":"phonetics"},{"en":"to remove things that are not wanted or needed from something","cn":"移走，搬走，清除（不需要的东西）","g":"[transitive]","sc":"remove something/somebody","ex":{"en":"The settlers cleared the land and planted crops.","cn":"拓荒者开垦土地，种植庄稼。"},"pos":"verb"},{"en":"to make people leave a place","cn":"使人离开","g":"[transitive]","sc":"remove something/somebody","ex":{"en":"Security officials tried to clear the area, fearing more bomb attacks.","cn":"由于担心再次发生炸弹袭击，安全官员试图清场。"},"pos":"verb"},{"en":"to move freely again; to no longer be blocked","cn":"恢复畅通；不再受阻","g":"[intransitive]","sc":"not be blocked","ex":{"en":"The traffic took a long time to clear after the accident.","cn":"事故后很久交通才恢复畅通。"},"pos":"verb"},{"en":"when smoke, fog, etc. clears, it disappears so that it is easier to see things","cn":"（烟、雾等）消散，散去，消失","g":"[intransitive]","sc":"of smoke, etc.","ex":{"en":"The mist will clear by mid-morning.","cn":"雾将在上午十时左右消散。"},"pos":"verb"},{"en":"when the sky or the weather clears, it becomes brighter and free of cloud or rain","cn":"变明朗；转晴；放晴","g":"[intransitive]","sc":"of sky/weather","ex":{"en":"The next day the weather cleared.","cn":"第二天天气放晴了。"},"pos":"verb"},{"en":"when a liquid clears, it becomes transparent and you can see through it","cn":"变透明；变清澈","g":"[intransitive]","sc":"of liquid","ex":{"en":"The muddy water slowly cleared.","cn":"浑浊的水慢慢变得清澈起来。"},"pos":"verb"},{"en":"if your head or mind clears, or you clear it, you become free of thoughts that worry or confuse you or the effects of alcohol, a hit on the head, etc. and you are able to think clearly","cn":"（使）变清醒，变清晰","g":"[intransitive, transitive]","sc":"your head/mind","ex":{"en":"As her mind cleared, she remembered what had happened.","cn":"头脑清醒之后，她想起了所发生的一切。"},"pos":"verb"},{"en":"if your face or expression clears, you stop looking angry or worried","cn":"变平静；变开朗","g":"[intransitive]","sc":"of face/expression","ex":{"en":"His face suddenly cleared as understanding dawned.","cn":"他逐渐明白过来，脸上霎时明朗起来。"},"pos":"verb"},{"en":"to prove that somebody is innocent","cn":"证明无罪（或无辜）","g":"[transitive]","sc":"prove somebody innocent","ex":{"en":"She was cleared of all charges against her.","cn":"对她的所有指控均已撤销。"},"pos":"verb"},{"en":"to give or get official approval for something to be done","cn":"批准；准许；得到许可","g":"[transitive]","sc":"give official permission","ex":{"en":"His appointment had been cleared by the board.","cn":"他的任命已由董事会批准。"},"pos":"verb"},{"en":"to give official permission for a person, a ship, a plane or goods to leave or enter a place","cn":"批准（人、船只、飞机或货物）离境（或入境）；使通过（海关）","g":"[transitive]","sc":"give official permission","ex":{"en":"The plane had been cleared for take-off.","cn":"飞机已获准起飞。"},"pos":"verb"},{"en":"to decide officially, after finding out information about somebody, that they can be given special work or allowed to see secret papers","cn":"（经审查后）正式批准（某人）做机密工作（或阅读机密文件）","g":"[transitive]","sc":"give official permission","ex":{"en":"She hasn't been cleared by security.","cn":"她未获保安部门批准做机要工作。"},"pos":"verb"},{"en":"if a payment that is made into your bank account clears, or a bank clears it, the money is available for you to use","cn":"（付款）到账；（银行）将（付款）划入账户","g":"[intransitive, transitive]","sc":"money","ex":{"en":"Cheques usually take three working days to clear.","cn":"兑现支票通常需要三个工作日。"},"pos":"verb"},{"en":"to gain or earn a sum of money as profit","cn":"获利；净赚","g":"[transitive]","sc":"money","ex":{"en":"She cleared £1 000 on the deal.","cn":"她在那笔交易中净赚 1 000 英镑。"},"pos":"verb"},{"en":"if you clear a debt or a loan, you pay all the money back","cn":"偿清，还清（债务或贷款）","g":"[transitive]","sc":"money","ex":{"en":"They sold $25 million in holdings in order to clear colossal bank debts.","cn":"他们出售了 2500 万美元的股份，以偿还巨额银行债务。"},"pos":"verb"},{"en":"to jump over or get past something without touching it","cn":"（无接触地）跃过，越过，通过","g":"[transitive]","sc":"get over/past","ex":{"en":"The horse cleared the fence easily.","cn":"那匹马轻松地跃过了栅栏。"},"pos":"verb"},{"en":"if you clear a ball, or a ball clears, it is kicked or hit away from the area near your own goal","cn":"将（球）击离己方球门区；（球）滚离己方球门区","g":"[transitive, intransitive]","sc":"in sport","pos":"verb"},{"en":"away from something/somebody; not near or touching something/somebody","cn":"离开；不靠近；不接触","sc":"not near/touching","ex":{"en":"Stand clear of the train doors.","cn":"不要靠近列车门站立。"},"pos":"adverb"},{"en":"all the way to something that is far away","cn":"一直（到远处）","lab":"especially North American English","sc":"all the way","ex":{"en":"She could see clear down the highway into the town.","cn":"她顺着公路一直望去，能看到远处的那座城镇。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易懂的;明白的;清楚的","en":"Something that is clear is easy to understand, see, or hear.","ex":{"en":"The book is clear, readable and adequately illustrated","cn":"这本书明白易懂，可读性强，插图丰富。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"明显的;显然的;明白无误的","en":"Something that is clear is obvious and impossible to be mistaken about.","ex":{"en":"It was a clear case of homicide","cn":"这显然是一宗杀人案。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"完全了解的;明白的;清楚的","en":"If you are clear about something, you understand it completely.","ex":{"en":"It is important to be clear about what Chomsky is doing here","cn":"很有必要搞清乔姆斯基在这儿干什么。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(头脑或思路)清楚的，清晰的，清醒的，不糊涂的","en":"If your mind or your way of thinking is clear, you are able to think sensibly and reasonably, and you are not affected by confusion or by a drug such as alcohol.","ex":{"en":"She needed a clear head to carry out her instructions.","cn":"她需要一个头脑清醒的人来执行自己的指令。"}},{"pos":"VERB 动词","cn":"理清(思路);使(头脑)清醒","en":"To clear your mind or your head means to free it from confused thoughts or from the effects of a drug such as alcohol.","ex":{"en":"He walked up Fifth Avenue to clear his head","cn":"他沿着第五大道走了走，好让大脑清醒清醒。"}},{"pos":"ADJ 形容词","cn":"透明的;清澈的","en":"A clear substance is one which you can see through and which has no colour, like clean water.","ex":{"en":"...a clear glass panel","cn":"透明的玻璃板"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(颜色)明艳的，鲜亮的","en":"A clear colour is bright and strong.","ex":{"en":"He has clear blue eyes and a dazzling smile.","cn":"他有一双明亮的蓝眼睛和一脸灿烂的微笑。"}},{"pos":"ADJ 形容词","cn":"(表面)收拾干净的;(地方)畅通的;(视野)无阻碍的","en":"If a surface, place, or view is clear, it is free of unwanted objects or obstacles.","ex":{"en":"The runway is clear — go ahead and land","cn":"跑道畅通无阻，开始着陆吧。"}},{"pos":"VERB 动词","cn":"清除;清理","en":"When you clear an area or place or clear something from it, you remove things from it that you do not want to be there.","ex":{"en":"To clear the land and harvest the bananas they decided they needed a male workforce","cn":"为了清理那片地和收割香蕉，他们决定雇请男劳力。"}},{"pos":"VERB 动词","cn":"(为…)清理道路;(为…)扫清障碍","en":"If something or someone clears the way or the path for something to happen, they make it possible.","ex":{"en":"The Prime Minister resigned today, clearing the way for the formation of a new government","cn":"首相今天的辞职为新政府的组建扫清了道路。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(天气或天空)晴朗的","en":"If it is a clear day or if the sky is clear, there is no mist, rain, or cloud.","ex":{"en":"On a clear day you can see the French coast","cn":"天气晴朗时可以望见法国海岸。"}},{"pos":"VERB 动词","cn":"(雾霭)消散，退去","en":"When fog or mist clears, it gradually disappears.","ex":{"en":"The early morning mist had cleared.","cn":"晨雾散去了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(眼睛)清澈的，有神的，明亮的","en":"Clear eyes look healthy, attractive, and shining.","ex":{"en":"...clear blue eyes","cn":"清澈的蓝眼睛"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(皮肤)光洁的，无斑点的","en":"If your skin is clear, it is healthy and free from spots."},{"pos":"ADJ 形容词","cn":"(良心)无愧的，不内疚的","en":"If you say that your conscience is clear, you mean you do not think you have done anything wrong.","ex":{"en":"Mr Garcia said his conscience was clear over the jail incidents","cn":"加西亚先生说他对监狱中发生的事件问心无愧。"}},{"pos":"ADJ 形容词","cn":"不接触的;远离的;在安全距离以外的","en":"If something or someone is clear of something else, it is not touching it or is a safe distance away from it.","ex":{"en":"As soon as he was clear of the terminal building he looked round","cn":"他一离开机场大楼，就环顾了一下四周。"}},{"pos":"ADV 副词","cn":"(尤指开车到远处)一直，径直","en":"If you drive clear to a place, especially a place that is far away, you go all the way there without delays.","ex":{"en":"After that they drove clear over to St Paul.","cn":"之后，他们一口气开到圣保罗。"}},{"pos":"VERB 动词","cn":"跳过;越过","en":"If an animal or person clears an object or clears a certain height, they jump over the object, or over something that height, without touching it.","ex":{"en":"Sotomayor, the Cuban holder of the world high jump record, cleared 2.36 metres.","cn":"古巴的世界跳高纪录保持者索托马约尔跳过了2.36米。"}},{"pos":"V-ERG 及物/不及物动词","cn":"兑现(支票)；（支票）结算","en":"When a bank clears a cheque or when a cheque clears, the bank agrees to pay the sum of money mentioned on it.","ex":{"en":"Polish banks can still take two or three weeks to clear a cheque","cn":"在波兰，银行兑现支票可能还需要两三个星期。"}},{"pos":"VERB 动词","cn":"批准，准许(行动)","en":"If a course of action is cleared, people in authority give permission for it to happen.","ex":{"en":"Linda Gradstein has this report from Jerusalem, which was cleared by an Israeli censor","cn":"琳达·格拉德斯坦的这份报道来自耶路撒冷，它已经通过了以色列方面的审查。"}},{"pos":"VERB 动词","cn":"证明无罪；证实无过错","en":"If someone is cleared, they are proved to be not guilty of a crime or mistake.","ex":{"en":"She was cleared of murder and jailed for just five years for manslaughter","cn":"她被判谋杀罪名不成立，仅以过失杀人罪判处5年监禁。"}},{"pos":"CONVENTION 惯用语","cn":"(用于确定自己的话被理解以及强调权威性)听懂了吗？我说明白了吗？","en":"You can say 'Is that clear?' or 'Do I make myself clear?' after you have told someone your wishes or instructions, to make sure that they have understood you, and to emphasize your authority.","ex":{"en":"We're only going for half an hour, and you're not going to buy anything. Is that clear?","cn":"我们只去半个小时，而且你什么都不能买。听清楚了没有？"}},{"pos":"PHRASE 短语","cn":"没有危险的;不受责备的;不受怀疑的","en":"If someone is in the clear, they are not in danger, or are not blamed or suspected of anything.","ex":{"en":"The Audit Commission said that the ministry was in the clear.","cn":"审计署称该政府部门没有问题。"}},{"pos":"PHRASE 短语","cn":"把…表达清楚;把…说明白","en":"If you make something clear, you say something in a way that makes it impossible for there to be any doubt about your meaning, wishes, or intentions.","ex":{"en":"Mr O'Friel made it clear that further insults of this kind would not be tolerated","cn":"奥弗里尔先生明确表示，绝不容忍这样的侮辱行为再次发生。"}},{"pos":"PREP-PHRASE 短语介词","cn":"高出，超出，多出（竞争对手）","en":"If something or someone is a certain amount clear of a competitor, they are that amount ahead of them in a competition or race.","ex":{"en":"Keegan's team are now seven points clear of West Ham","cn":"基冈率领的球队现在领先西汉姆联队7分。"}},{"pos":"PHRASE 短语","cn":"避开;绕开","en":"If you steer clear or stay clear of someone or something, you avoid them.","ex":{"en":"The rabbis try to steer clear of political questions.","cn":"拉比们努力避开政治问题。"}},{"pos":"","cn":"","en":"to clear the air→see: ; the coast is clear→see: ; to clear the decks→see: ; loud and clear→see: ; to clear your throat→see: ;"},{"pos":"","cn":"","en":"相关词组：clear away clear off clear out clear up"}]},"examples":[{"en":"She was in Australia but I could hear her voice as clear as a bell.","cn":"她虽然在澳大利亚，但我却能非常清楚地听到她的声音。"},{"en":"I hope I made it clear to him that he was no longer welcome here.","cn":"我希望我已经给他讲清楚他在这里不再受欢迎。"}]},"close":{"media":{"uk":"media/uk/close__gb_1.mp3","us":"media/us/close__us_1.mp3"},"oxford":{"phon":"kləʊz","pos":"verb","senses":[{"en":"to put something into a position so that it covers an opening; to get into this position","cn":"关；关闭；闭上","g":"[transitive, intransitive]","sc":"window/door, etc.","ex":{"en":"He closed the door firmly.","cn":"他把门关严。"}},{"en":"to move the parts of something together so that it is no longer open","cn":"合上；合拢","g":"[transitive]","sc":"book/umbrella, etc.","ex":{"en":"to close a book/an umbrella","cn":"合上书；收起伞"}},{"en":"to make the work of a shop, etc. stop for a period of time; to not be open for people to use","cn":"（使）关门，关闭（一段时间）；不开放","g":"[transitive, often passive, intransitive]","sc":"shop/store/business, etc.","ex":{"en":"The school was closed because of the heavy snow.","cn":"学校因大雪而关闭。"}},{"en":"if a company, shop, etc. closes, or if you close it, it stops operating as a business","cn":"停业；关闭；歇业；倒闭","g":"[transitive, intransitive]","sc":"shop/store/business, etc.","ex":{"en":"The hospital closed at the end of last year.","cn":"这所医院去年年底关闭。"}},{"en":"to end or make something end","cn":"（使）结束，终止","g":"[intransitive, transitive]","lab":"North American English","sc":"end","ex":{"en":"The meeting will close at 10.00 p.m.","cn":"会议将在晚上 10 点结束。"}},{"en":"to arrange and settle a business deal","cn":"完成（交易）；达成（协议）","g":"[transitive]","sc":"end","ex":{"en":"Right now we are trying to close the deal with our sponsors.","cn":"现在我们正试图与赞助商达成协议。"}},{"en":"to put an end to a mistake in something that causes a security risk or gives somebody an unfair advantage","cn":"堵上（漏洞）","g":"[transitive]","sc":"end","ex":{"en":"The company acted quickly to close a security hole in its online systems.","cn":"该公司迅速采取行动，堵住了其在线系统中的安全漏洞。"}},{"en":"to stop using a computer program or file and put it away","cn":"关闭（程序或文件）","g":"[transitive]","lab":"computing","sc":"computers","ex":{"en":"Once I got a few apps closed, it started working again.","cn":"我一关闭几个应用程序，它就又开始运转了。"}},{"en":"to be worth a particular amount at the end of the day’s business","cn":"收盘","g":"[intransitive]","sc":"finance","ex":{"en":"Shares in the company closed at 265p.","cn":"这家公司的股票收盘价为 265 便士。"}},{"en":"to make the distance or difference between two people or things smaller; to become smaller or narrower","cn":"（使）缩小，接近；变小；变窄","g":"[transitive, intransitive]","sc":"distance/difference","ex":{"en":"These measures are aimed at closing the gap between rich and poor.","cn":"这些措施旨在缩小贫富差距。"}},{"en":"to cover somebody/something and hold them/it, or to make something do this","cn":"抓住；握住；抱紧","g":"[transitive, intransitive]","sc":"cover and hold","ex":{"en":"She closed her hand over his.","cn":"她牢牢抓住他的手不放。"}},{"en":"to make an electrical circuit continuous","cn":"电路闭合","g":"[transitive]","sc":"electrical circuit","ex":{"en":"When a finger touches the panel, it closes the circuit.","cn":"当手指触摸面板时，电路就会闭合。"}},{"en":"the end of a period of time or an activity","cn":"（一段时间或活动的）结束，终结，终了","ex":{"en":"at the close of the seventeenth century","cn":"在 17 世纪末"},"pos":"noun"},{"en":"the fact of something shutting, especially a door","cn":"（尤指门）关上，闭合","ex":{"en":"The door swung to a close.","cn":"门关上了。"},"pos":"noun"},{"en":"near in space or time","cn":"（在空间、时间上）接近","g":"[not usually before noun]","sc":"near","ex":{"en":"I had no idea the beach was so close.","cn":"我不知道海滩会这么近。"},"pos":"adjective"},{"en":"knowing somebody very well and liking them very much","cn":"亲密的；密切的","sc":"relationship","ex":{"en":"Jo is a very close friend.","cn":"乔是一个很亲密的朋友。"},"pos":"adjective"},{"en":"near in family relationship","cn":"（家庭关系）亲近的","sc":"relationship","ex":{"en":"close relatives, such as your mother and father, and brothers and sisters","cn":"近亲，如父母和兄弟姊妹"},"pos":"adjective"},{"en":"very involved in the work or activities of somebody else, usually seeing and talking to them regularly","cn":"（与某人的工作或活动）紧密相关的，密切的","sc":"relationship","ex":{"en":"She has kept in close contact with the victims' families.","cn":"她与受害者的家人一直保持着密切的联系。"},"pos":"adjective"},{"en":"careful and complete","cn":"细致的；严密的；周密的","g":"[only before noun]","sc":"careful","ex":{"en":"Take a close look at this photograph.","cn":"仔细看看这张照片。"},"pos":"adjective"},{"en":"almost in a particular state; likely to do something soon","cn":"几乎（处于某种状态）；可能（快要做某事）","g":"[not before noun]","sc":"almost/likely","ex":{"en":"The airline is close to collapse.","cn":"这家航空公司濒临倒闭。"},"pos":"adjective"},{"en":"very similar to something else or to an amount","cn":"酷似的；几乎相等的","sc":"similar","ex":{"en":"There's a close resemblance between them (= they look very similar).","cn":"两者外表酷似。"},"pos":"adjective"},{"en":"won by only a small amount or distance","cn":"实力相差无几的；仅以些微之差获胜的","sc":"competition/election, etc.","ex":{"en":"a close match/contest/election","cn":"旗鼓相当的比赛／竞赛／选举"},"pos":"adjective"},{"en":"used to describe something, usually a dangerous or unpleasant situation, that nearly happens","cn":"（通常指危险或不愉快的情况几乎发生）差一点儿，险些","sc":"almost bad result","ex":{"en":"Phew! That was close—that car nearly hit us.","cn":"啊！好险！那辆车差点儿撞上我们。"},"pos":"adjective"},{"en":"with little or no space in between","cn":"空隙极小的；无空隙的；密集的；紧凑的","sc":"without space","ex":{"en":"over 1 000 pages of close print","cn":"1 000 多页字体密集的印刷品"},"pos":"adjective"},{"en":"cut very short, near to the skin","cn":"剪到齐根的；剪得很短的","sc":"cut short","ex":{"en":"a close haircut/shave","cn":"剪到齐根的头发；刮剃干净"},"pos":"adjective"},{"en":"carefully guarded","cn":"严加戒备的；守卫严密的","g":"[only before noun]","sc":"guarded","ex":{"en":"The donor's identity is a close secret.","cn":"捐赠人的身份是保密的。"},"pos":"adjective"},{"en":"warm in an uncomfortable way because there does not seem to be enough fresh air","cn":"闷热的；不通风的","sc":"weather/room","ex":{"en":"It’s very close today—I think there’s going to be a storm.","cn":"今天已经很近了——我想将会有一场暴风雨。"},"pos":"adjective"},{"en":"not willing to give personal information about yourself","cn":"（对自己的个人信息）守口如瓶","g":"[not before noun]","sc":"private","ex":{"en":"He was close about his past.","cn":"他对他的过去守口如瓶。"},"pos":"adjective"},{"en":"not liking to spend money","cn":"吝啬；小气","g":"[not before noun]","lab":"British English","sc":"mean","ex":{"en":"She's always been very close with her money.","cn":"她用钱总是很吝啬。"},"pos":"adjective"},{"en":"produced with part of the tongue in the highest possible position without limiting the flow of air","cn":"闭的；舌位高的","sc":"phonetics","pos":"adjective"},{"en":"near; not far away","cn":"接近；靠近；紧挨着；不远地","ex":{"en":"They sat close together.","cn":"他们紧挨着坐在一起。"},"pos":"adverb"},{"en":"a street that is closed at one end","cn":"一端不通的街道；死胡同；死巷道","lab":"British English","ex":{"en":"Brookside Close","cn":"布鲁克赛德巷"},"pos":"noun"},{"en":"the grounds and buildings that surround and belong to a cathedral","cn":"大教堂所属的周围场地及建筑物","pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)关闭；（使）合上","en":"When you close something such as a door or lid or when it closes, it moves so that a hole, gap, or opening is covered.","ex":{"en":"If you are cold, close the window","cn":"要是冷就把窗户关上。"}},{"pos":"VERB 动词","cn":"合上，合拢(书、伞等)","en":"When you close something such as an open book or umbrella, you move the different parts of it together.","ex":{"en":"Slowly he closed the book.","cn":"他慢慢合上书。"}},{"pos":"VERB 动词","cn":"关闭(计算机文档、窗口等)","en":"If you close something such as a computer file or window, you give the computer an instruction to remove it from the screen.","ex":{"en":"To close your document, press CTRL+W on your keyboard.","cn":"关闭文件时要同时按键盘上的CTRL键和W键。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(眼睛)闭上；合上（眼睛）","en":"When you close your eyes or your eyes close, your eyelids move downwards, so that you can no longer see.","ex":{"en":"Bess closed her eyes and fell asleep","cn":"贝丝合上眼睛睡着了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)暂时性关闭，（使）暂停营业；关门","en":"When a place closes or is closed, work or activity stops there for a short period.","ex":{"en":"Shops close only on Christmas Day and New Year's Day","cn":"商店只在圣诞日和元旦停业。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(工厂、商店、学校等)永久性关闭；(使)停业;(使)倒闭","en":"If a place such as a factory, shop, or school closes, or if it is closed, all work or activity stops there permanently.","ex":{"en":"Many enterprises will be forced to close","cn":"很多家企业将被迫倒闭。"}},{"pos":"VERB 动词","cn":"封闭,封锁(街道、边界)","en":"To close a road or border means to block it in order to prevent people from using it.","ex":{"en":"They were cut off from the West in 1948 when their government closed that border crossing.","cn":"1948年政府关闭那个边境关口之后，他们便与西方国家隔绝开了。"}},{"pos":"VERB 动词","cn":"结束，终止(谈话、事件等)","en":"To close a conversation, event, or matter means to bring it to an end or to complete it.","ex":{"en":"Judge Isabel Oliva said last night: 'I have closed the case. There was no foul play.'","cn":"昨晚伊莎贝尔·奥利娃法官说：“此案我已审结，并无谋杀嫌疑。”"}},{"pos":"VERB 动词","cn":"结清撤销，注销(银行账户)","en":"If you close a bank account, you take all your money out of it and inform the bank that you will no longer be using the account.","ex":{"en":"He had closed his account with the bank five years earlier.","cn":"早在5年前他就在这家银行销户了。"}},{"pos":"VERB 动词","cn":"(股票等)收盘","en":"On the stock market or the currency markets, if a share price or a currency closes at a particular value, that is its value at the end of the day's business.","ex":{"en":"Dawson shares closed at 219p, up 5p","cn":"道森股票以219便士收盘，上涨了5便士。"}},{"pos":"N-SING 单数名词","cn":"结束;终止","en":"The close of a period of time or an activity is the end of it. To bring or draw something to a close means to end it.","ex":{"en":"By the close of business last night, most of the big firms were hailing yesterday's actions as a success","cn":"昨晚交易结束的时候，多数大公司都称赞当天的活动取得了成功。"}},{"pos":"See also:","cn":"","en":"→see: ; to close your eyes to something→see: ; to close ranks→see: ;"},{"pos":"","cn":"","en":"相关词组：close down close off close up"},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"近的;接近的","en":"If one thing or person is close to another, there is only a very small distance between them.","ex":{"en":"Her lips were close to his head and her breath tickled his ear","cn":"她的嘴唇贴近他的头，她的呼吸让他耳朵发痒。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"亲近的;亲密的","en":"You say that people are close to each other when they like each other very much and know each other very well.","ex":{"en":"She and Linda became very close","cn":"她和琳达变得非常亲密。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(血缘关系)近的;近亲的","en":"Your close relatives are the members of your family who are most directly related to you, for example your parents and your brothers or sisters.","ex":{"en":"...large changes such as the birth of a child or death of a close relative.","cn":"像孩子出生或近亲去世这样的大变故"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（盟友、伙伴）交往密切的，亲密的","en":"A close ally or partner of someone knows them well and is very involved in their work.","ex":{"en":"He was once regarded as one of Mr Brown's closest political advisers","cn":"他曾一度被视作布朗先生最为亲信的政治顾问之一。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(联系或合作)密切的","en":"Close contact or co-operation involves seeing or communicating with someone often.","ex":{"en":"Both nations are seeking closer links with the West","cn":"两国都在寻求与西方国家建立更为紧密的联系。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(联系)紧密的;酷似的","en":"If there is a close connection or resemblance between two things, they are strongly connected or are very similar.","ex":{"en":"There is a close connection between pain and tension","cn":"疼痛和紧张之间有着紧密的联系。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(检查或观察)仔细的，彻底的","en":"Close inspection or observation of something is careful and thorough.","ex":{"en":"He discovered, on closer inspection, that the rocks contained gold","cn":"经过更为仔细的探察，他发现这些岩石含金。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(竞争或选举)势均力敌的，难分高下的","en":"A close competition or election is won or seems likely to be won by only a small amount.","ex":{"en":"It is still a close contest between two leading opposition parties","cn":"这仍然是两大主要反对党之间一场势均力敌的较量。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"接近的;快要…的;即将…的","en":"If you are close to something or if it is close, it is likely to happen or come soon. If you are close to doing something, you are likely to do it soon.","ex":{"en":"She sounded close to tears","cn":"她听上去要哭了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"近乎于…的;差点…的","en":"If something is close or comes close to something else, it almost is, does, or experiences that thing.","ex":{"en":"There is a simplicity about the interior which comes close to blandness","cn":"室内布置得很简单，几乎有点平淡无奇。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"闷热的;不通风的","en":"If the atmosphere somewhere is close, it is unpleasantly warm with not enough air."},{"pos":"PHRASE 短语","cn":"在附近;在近旁","en":"Something that is close by or close at hand is near to you.","ex":{"en":"Did a new hairdressing shop open close by?","cn":"附近是不是新开了一家理发店？"}},{"pos":"PHRASE 短语","cn":"勉强脱险;幸免于难","en":"If you describe an event as a close shave, a close thing, or a close call, you mean that an accident or a disaster very nearly happened.","ex":{"en":"You had a close shave, but you knew when you accepted this job that there would be risks.","cn":"你这次侥幸脱险，不过在接受这项工作的时候，你就知道会有一些危险。"}},{"pos":"PHRASE 短语","cn":"仔细观察;严密注视","en":"If you keep a close eye on someone or something or keep a close watch on them, you observe them carefully to make sure they are progressing as you want them to.","ex":{"en":"The President's foreign policy team are keeping a close eye on events.","cn":"总统的外交政策团队正密切关注事态发展。"}},{"pos":"PREP-PHRASE 短语介词","cn":"接近于(某数量或距离)","en":"Close to a particular amount or distance means slightly less than that amount or distance. In British English, you can also say close on a particular amount or distance.","ex":{"en":"Sisulu spent close to 30 years in prison","cn":"西苏卢在监狱里度过了将近30年的时光。"}},{"pos":"PHRASE 短语","cn":"在近处;凑近地","en":"If you look at something close up or close to, you look at it when you are very near to it.","ex":{"en":"They always look smaller close up.","cn":"凑近看时，它们总是显得小一些。"}},{"pos":"PHRASE 短语","cn":"(比赛、选举等)势均力敌","en":"If something such as a competition or an election is too close to call, it is not possible to predict who will win because it seems likely to be won by only a very small margin.","ex":{"en":"In the Senate, the count is too close to call at this point.","cn":"参议院现在的票数还难分上下。"}},{"pos":"","cn":"","en":"at close quarters→see: ; at close range→see: ;"},{"pos":"VERB 动词","cn":"靠近;接近","en":"If you are closing on someone or something that you are following, you are getting nearer and nearer to them.","ex":{"en":"I was within 15 seconds of the guy in second place and closing on him.","cn":"我和处在第二名的男子相差不到15秒，而且正在逐渐赶上他。"}},{"pos":"","cn":"","en":"相关词组：close in"},{"pos":"N-IN-NAMES 名称名词","cn":"(用于英国的一些街名中)巷，小街","en":"Close is used in the names of some streets in Britain.","ex":{"en":"...116 Dendridge Close.","cn":"登德里奇巷116号"}}]},"examples":[{"en":"All the steelworks around here were closed down in the 1980s.","cn":"这一带的所有钢铁厂都在 20 世纪 80 年代倒闭了。"},{"en":"We caught the bus in the end but it was close (= we nearly missed it).","cn":"虽然我们最后总算赶上了那趟公共汽车，但也是够悬的。"}]},"closing":{"media":{"uk":"media/uk/closing__gb_1.mp3","us":"media/us/closing__us_1.mp3"},"oxford":{"phon":"ˈkləʊzɪŋ","pos":"adjective","senses":[{"en":"coming at the end of a speech, a period of time or an activity","cn":"（讲话、时段或活动）接近尾声的，结尾的，结束的","ex":{"en":"his closing remarks","cn":"他的结束语"}},{"en":"the act of shutting something such as a factory, hospital, school, etc. permanently","cn":"（永久的）停业，关闭；倒闭","ex":{"en":"the closing of the local school","cn":"当地学校的关闭"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"结束的;结尾的","en":"The closing part of an activity or period of time is the final part of it.","ex":{"en":"He entered RAF service in the closing stages of the war","cn":"战争快要结束的时候，他加入了英国皇家空军。"}}]},"examples":[{"en":"the closing of the local school","cn":"当地学校的关闭"},{"en":"the closing stages of the game","cn":"比赛的尾段"}]},"clothes":{"media":{"img":["media/pic/clothes_suit_comp.jpg","media/thumb/skirt.jpg"],"uk":"media/uk/clothes__gb_1.mp3","us":"media/us/clothes__us_1.mp3"},"oxford":{"phon":"kləʊðz","pos":"noun","senses":[{"en":"the things that you wear, such as trousers, dresses and jackets","cn":"衣服；服装","lab":"North American English also","ex":{"en":"I bought some new clothes for the trip.","cn":"我为这次旅行买了一些新衣服。"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"衣服;服装","en":"Clothes are the things that people wear, such as shirts, coats, trousers, and dresses.","ex":{"en":"Moira walked upstairs to change her clothes","cn":"莫伊拉上楼去换衣服。"}}]},"examples":[{"en":"I bought some new clothes for the trip.","cn":"我为这次旅行买了一些新衣服。"},{"en":"He was wearing a strange shapeless garment.","cn":"他穿着一件不成形的奇怪衣服。"}]},"clicks":{"oxford":{"phon":"klɪk","pos":"verb","senses":[{"en":"to make or cause sth to make a short sharp sound （","cn":"使）发出咔哒声，咔哒（或咔嚓）响"},{"en":"to choose a particular function or item on a computer screen, etc., by pressing one of the buttons on a mouse or touch pad （","cn":"用鼠标或在触控板上）点击，单击"}]}},"cleans":{"oxford":{"phon":"kliːn","pos":"adjective","senses":[{"en":"not dirty","cn":"洁净的；干净的"},{"en":"having a clean appearance and clean surroundings","cn":"爱干净的；爱整洁的"}]},"media":{"uk":"media/uk/clean__gb_1.mp3","us":"media/us/clean__us_1.mp3"}},"clad":{"media":{"uk":"media/uk/clad__gb_1.mp3","us":"media/us/clad__us_1.mp3"},"oxford":{"phon":"klæd","pos":"adjective","senses":[{"en":"wearing a particular type of clothing","cn":"穿…衣服的","ex":{"en":"She was clad in blue velvet.","cn":"她身着蓝色的天鹅绒服装。"}},{"en":"covered in a particular thing","cn":"…覆盖的","ex":{"en":"snow-clad hills","cn":"白雪覆盖的山峦"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"穿…衣服的","en":"If you are clad in particular clothes, you are wearing them.","ex":{"en":"...the figure of a woman, clad in black","cn":"一个身穿黑衣的女人的身影"}},{"pos":"ADJ 形容词","cn":"被…覆盖的;被…笼罩的","en":"A building, part of a building, or mountain that is clad with something is covered by that thing.","ex":{"en":"The walls and floors are clad with ceramic tiles.","cn":"墙面和地板上都贴着瓷砖。"}}]},"examples":[{"en":"She was clad in blue velvet.","cn":"她身着蓝色的天鹅绒服装。"},{"en":"leather-clad motorcyclists","cn":"穿皮外套的摩托车手"}]},"cloak":{"media":{"uk":"media/uk/cloak__gb_1.mp3","us":"media/us/cloak__us_1.mp3"},"oxford":{"phon":"kləʊk","pos":"noun","senses":[{"en":"a type of coat that has no arms, fastens at the neck and hangs loosely from the shoulders, worn especially in the past","cn":"（尤指旧时的）披风，斗篷","g":"[countable]","ex":{"en":"She stormed off, her cloak flying behind her.","cn":"她气呼呼地冲了出去，斗篷在身后飞扬。"}},{"en":"a thing that hides or covers somebody/something","cn":"遮盖物","g":"[singular]","lab":"literary","ex":{"en":"They left under the cloak of darkness.","cn":"他们在黑暗的掩护下离开了。"}},{"en":"to cover or hide something","cn":"遮盖；掩盖","ex":{"en":"The hills were cloaked in thick mist.","cn":"大雾笼罩着群山。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"斗篷;披风","en":"A cloak is a long, loose, sleeveless piece of clothing which people used to wear over their other clothes when they went out."},{"pos":"N-SING 单数名词","cn":"覆盖物;遮盖物","en":"A cloak of something such as mist or snow completely covers and hides something.","ex":{"en":"Today most of England will be under a cloak of thick mist.","cn":"今天，英格兰大部分地区将被浓雾笼罩。"}},{"pos":"N-SING 单数名词","cn":"掩盖;伪装;幌子","en":"If you refer to something as a cloak, you mean that it is intended to hide the truth about something.","ex":{"en":"Preparations for the wedding were made under a cloak of secrecy","cn":"婚礼的准备工作是秘密进行的。"}},{"pos":"VERB 动词","cn":"笼罩;覆盖;遮掩","en":"To cloak something means to cover it or hide it.","ex":{"en":"...the decision to cloak major tourist attractions in unsightly hoardings","cn":"在主要景点外挂满刺眼的大幅广告牌的决定"}}]},"examples":[{"en":"They left under the cloak of darkness.","cn":"他们在黑暗的掩护下离开了。"},{"en":"a tall cloaked figure (= a person wearing a cloak )","cn":"一个穿着披风、身材很高的人"}]},"clothing":{"media":{"uk":"media/uk/clothing__gb_1.mp3","us":"media/us/clothing__us_1.mp3"},"oxford":{"phon":"ˈkləʊðɪŋ","pos":"noun","senses":[{"en":"clothes, especially a particular type of clothes","cn":"衣服；（尤指某种）服装","ex":{"en":"Workers at the factory wear protective clothing.","cn":"工厂里的工人穿着防护服。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"衣服;服装","en":"Clothing is the things that people wear. →see usage note at:","ex":{"en":"Some locals offered food and clothing to the refugees","cn":"一些当地人为难民们提供食品和衣服。"}}]},"examples":[{"en":"the high cost of food and clothing","cn":"衣食的昂贵费用"},{"en":"an item/article of clothing","cn":"一件衣服"}]},"climate":{"media":{"uk":"media/uk/climate__gb_1.mp3","us":"media/us/climate__us_1.mp3"},"oxford":{"phon":"ˈklaɪmət","pos":"noun","senses":[{"en":"the regular pattern of weather conditions of a particular place","cn":"气候","g":"[countable, uncountable]","ex":{"en":"a tropical/warm/mild/temperate/cold climate","cn":"热带／温暖／温和／温带／寒冷气候"}},{"en":"an area with particular weather conditions","cn":"气候区","g":"[countable]","ex":{"en":"They wanted to move to a warmer climate.","cn":"他们想迁移到气候较温暖的地区。"}},{"en":"a general attitude or feeling; an atmosphere or a situation that exists in a particular place","cn":"倾向；思潮；风气；环境气氛","g":"[countable]","ex":{"en":"the present political/economic climate","cn":"当前的政治／经济气候"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"气候","en":"The climate of a place is the general weather conditions that are typical of it.","ex":{"en":"...the hot and humid climate of Cyprus.","cn":"塞浦路斯炎热潮湿的气候"}},{"pos":"N-COUNT 可数名词","cn":"氛围；形势;局势;状况","en":"You can use climate to refer to the general atmosphere or situation somewhere.","ex":{"en":"The economic climate remains uncertain.","cn":"经济形势依然不确定。"}}]},"examples":[{"en":"We need to create a climate in which business can prosper.","cn":"我们需要创造一个有利于商业繁荣的环境。"},{"en":"They wanted to move to a warmer climate.","cn":"他们想迁移到气候较温暖的地区。"}]},"clench":{"media":{"uk":"media/uk/clench__gb_1.mp3","us":"media/us/clench__us_1.mp3"},"oxford":{"phon":"klentʃ","pos":"verb","senses":[{"en":"when you clench your hands, teeth, etc., or when they clench, you press them together tightly, usually showing that you are angry, determined or upset","cn":"（通常表示愤怒、决心或不安时）捏紧，攥紧（拳头等），咬紧（牙齿等）","g":"[transitive, intransitive]","ex":{"en":"He clenched his fists in anger.","cn":"他愤怒地攥紧了拳头。"}},{"en":"to hold something tightly","cn":"抓紧某物","g":"[transitive, often passive]","ex":{"en":"Her pen was clenched between her teeth.","cn":"她咬着笔。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"攥紧(拳头)；(拳头)紧握","en":"When you clench your fist or your fist clenches, you curl your fingers up tightly, usually because you are very angry.","ex":{"en":"Alex clenched her fists and gritted her teeth","cn":"亚历克丝攥紧拳头，牙咬得咯咯响。"}},{"pos":"VERB 动词","cn":"(通常指生气、不安时)咬紧(牙齿)，咬牙切齿","en":"When you clench your teeth or they clench, you squeeze your teeth together firmly, usually because you are angry or upset.","ex":{"en":"Patsy had to clench her jaw to suppress her anger","cn":"帕奇只得咬紧牙关压住怒气。"}},{"pos":"VERB 动词","cn":"抓紧;握紧;咬紧","en":"If you clench something in your hand or in your teeth, you hold it tightly with your hand or your teeth.","ex":{"en":"I clenched the arms of my chair.","cn":"我死死抓住椅子扶手。"}}]},"examples":[{"en":"His fists clenched slowly until his knuckles were white.","cn":"他的拳头慢慢地捏紧，直捏得指关节都发白了。"},{"en":"Through clenched teeth she told him to leave.","cn":"她咬牙切齿地叫他离开。"}]},"clerk":{"media":{"uk":"media/uk/clerk__gb_1.mp3","us":"media/us/clerk__us_1.mp3"},"oxford":{"phon":"klɑːk","pos":"noun","senses":[{"en":"a person whose job is to serve customers in a shop","cn":"店员；售货员","lab":"both North American English","ex":{"en":"The clerk at the counter gave me too little change.","cn":"柜台的售货员给我少找了零钱。"}},{"en":"a person whose job is dealing with people arriving at or leaving a hotel","cn":"旅馆服务台接待员","lab":"both North American English","ex":{"en":"The hotel clerk greeted us warmly.","cn":"酒店接待员热情地欢迎我们。"}},{"en":"a person whose job is to keep the records or accounts and do other routine duties in an office, shop, etc.","cn":"职员；簿记员；文书","lab":"especially British English","ex":{"en":"an office clerk","cn":"办公室职员"}},{"en":"an official in charge of the records of a council, court, etc.","cn":"（议会、法院等的）书记员","ex":{"en":"the Town Clerk","cn":"市政府书记员"}},{"en":"to work as a clerk","cn":"当职员（或文书、书记员）","ex":{"en":"a clerking job","cn":"职员工作"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"文书;书记员;办事员","en":"A clerk is a person who works in an office, bank, or law court and whose job is to look after the records or accounts.","ex":{"en":"She was offered a job as an accounts clerk with a travel firm.","cn":"她得到一份在旅行社当记账员的工作。"}},{"pos":"N-COUNT 可数名词","cn":"(宾馆、办公室、医院的)接待员","en":"In a hotel, office, or hospital, a clerk is the person whose job is to answer the telephone and deal with people when they arrive.","ex":{"en":"...a hotel clerk.","cn":"宾馆接待员"}},{"pos":"N-COUNT 可数名词","cn":"店员","en":"A clerk is someone who works in a store."},{"pos":"VERB 动词","cn":"做文书工作;当接待员(或店员等)","en":"To clerk means to work as a clerk.","ex":{"en":"Gene clerked at the auction","cn":"吉恩在拍卖会上作文书工作。"}}]},"examples":[{"en":"The clerk at the counter gave me too little change.","cn":"柜台的售货员给我少找了零钱。"},{"en":"the Town Clerk","cn":"市政府书记员"}]},"cloudless":{"media":{"uk":"media/uk/cloudless__gb_1.mp3","us":"media/us/cloudless__us_1.mp3"},"oxford":{"phon":"ˈklaʊdləs","pos":"adjective","senses":[{"en":"clear; with no clouds","cn":"晴朗的；无云的","ex":{"en":"a cloudless sky","cn":"无云的天空"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无云的;晴朗的","en":"If the sky is cloudless, there are no clouds in it."}]},"examples":[{"en":"a cloudless sky","cn":"晴朗的天空"}]},"clamour":{"media":{"uk":"media/uk/clamour__gb_1.mp3","us":"media/us/clamour__us_1.mp3"},"oxford":{"phon":"ˈklæmə(r)","pos":"verb","senses":[{"en":"to demand something loudly","cn":"大声（或吵闹）地要求","g":"[intransitive, transitive]","lab":"formal","ex":{"en":"People began to clamour for his resignation.","cn":"人们开始大声疾呼要求他辞职。"}},{"en":"to shout loudly, especially in a confused way","cn":"（尤指乱哄哄地）大声地喊叫，呼叫","g":"[intransitive]","ex":{"en":"A crowd of reporters clamoured around the car.","cn":"一群记者围着车吵闹。"}},{"en":"a loud noise, especially one that is made by a lot of people or animals","cn":"喧闹声；嘈杂声；吵闹","g":"[singular]","ex":{"en":"the clamour of the market","cn":"市场上鼎沸的人声"},"pos":"noun"},{"en":"a demand for something made by a lot of people","cn":"民众的要求","g":"[uncountable, countable]","ex":{"en":"The clamour for her resignation grew louder.","cn":"民众要求她辞职的呼声越来越高。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"大声要求;愤怒疾呼","en":"If people are clamouring for something, they are demanding it in a noisy or angry way.","ex":{"en":"...competing parties clamouring for the attention of the voter","cn":"互相竞争的政党吵闹着争取选民的注意"}},{"pos":"N-SING 单数名词","cn":"嘈杂声;吵闹声","en":"Clamour is used to describe the loud noise of a large group of people talking or shouting together.","ex":{"en":"Kathryn's quiet voice stilled the clamour","cn":"凯瑟琳平静的声音使得嘈杂声平息了下来。"}}]},"examples":[{"en":"‘Play with us!’ the children clamoured. “","cn":"跟我们一起玩吧！”孩子们吵吵嚷嚷地要求道。"},{"en":"Everyone was clamouring to know how much they would get.","cn":"大家都吵闹着想知道他们能得到多少。"}]},"climber":{"media":{"uk":"media/uk/climber__gb_1.mp3","us":"media/us/climber__us_1.mp3"},"oxford":{"phon":"ˈklaɪmə(r)","pos":"noun","senses":[{"en":"a person who climbs (especially mountains) or an animal that climbs","cn":"攀登者；登山者；攀爬的动物","ex":{"en":"climbers and hill walkers","cn":"登山者和山地徒步旅行者"}},{"en":"a climbing plant","cn":"攀缘植物"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"登山运动员;登山爱好者","en":"A climber is someone who climbs rocks or mountains as a sport or a hobby."},{"pos":"N-COUNT 可数名词","cn":"攀缘植物","en":"A climber is a plant that grows upwards by attaching itself to other plants or objects."}]},"examples":[{"en":"Monkeys are efficient climbers.","cn":"猴子的攀缘能力很强。"},{"en":"climbers and hill walkers","cn":"登山者和山地徒步旅行者"}]},"clipped":{"media":{"uk":"media/uk/clipped__gb_1.mp3","us":"media/us/clipped__us_1.mp3"},"oxford":{"phon":"klɪpt","pos":"adjective","senses":[{"en":"clear and fast but not very friendly","cn":"清脆快速但不太友好的","ex":{"en":"his clipped military tones","cn":"他那短促的军人语调"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"修剪整齐的","en":"Clipped means neatly cut.","ex":{"en":"...a quiet street of clipped hedges and flowering gardens.","cn":"两边是修剪整齐的树篱和开满鲜花的花园的宁静街道"}},{"pos":"ADJ 形容词","cn":"(通常指说话像上流人士那样)快速的，短促的，简洁的","en":"If you say that someone has a clipped way of speaking, you mean they speak with quick, short sounds, and usually that they sound upper-class.","ex":{"en":"The Chief Constable's clipped tones crackled over the telephone line.","cn":"电话线那头噼里啪啦地传来警察局长短促的声音。"}}]},"examples":[{"en":"his clipped military tones","cn":"他那短促的军人语调"},{"en":"a neatly clipped hedge","cn":"修剪整齐的树篱"}]},"clay":{"media":{"uk":"media/uk/clay__gb_1.mp3","us":"media/us/clay__us_1.mp3"},"oxford":{"phon":"kleɪ","pos":"noun","senses":[{"en":"a type of heavy, sticky earth that becomes hard when it is baked and is used to make things such as pots and bricks","cn":"黏土；陶土","lab":"especially North American English","ex":{"en":"Not much can grow in the wet clay here.","cn":"在这里的湿黏土里种庄稼收成不多。"}}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"黏土;陶土","en":"Clay is a kind of earth that is soft when it is wet and hard when it is dry. Clay is shaped and baked to make things such as pots and bricks.","ex":{"en":"...the heavy clay soils of Cambridgeshire","cn":"剑桥郡的重黏土质土壤"}},{"pos":"N-UNCOUNT 不可数名词","cn":"红土网球场;沙地网球场","en":"In tennis, matches played on clay are played on courts whose surface is covered with finely crushed stones or brick.","ex":{"en":"Most tennis is played on hard courts, but a substantial amount is played on clay","cn":"多数网球比赛在硬地球场上举行，不过也有相当数量的比赛在红土球场上进行。"}},{"pos":"PHRASE 短语","cn":"（受人崇仰的人的）不为人知的严重缺点(或缺陷)","en":"If you say that a person who is respected or admired has feet of clay or has clay feet, you mean that they have serious faults which you or other people did not know about before.","ex":{"en":"When those idols are found to have feet of clay, the pain of disenchantment can be profound.","cn":"当人们发现那些偶像有严重的缺陷时，会产生无比痛苦的失落感。"}}]}},"clash":{"oxford":{"phon":"klæʃ","pos":"noun","senses":[{"en":"a short fight between two groups of people","cn":"（两群人之间的）打斗，打架，冲突","sc":"fight","ex":{"en":"Clashes broke out between police and demonstrators.","cn":"警方与示威者发生了冲突。"}},{"en":"an argument between two people or groups of people who have different beliefs and ideas","cn":"争论；辩论；争执","sc":"argument","ex":{"en":"There has been a head-on clash between the two candidates over education policy.","cn":"两位候选人一直在教育政策上针锋相对。"}},{"en":"the difference that exists between two things that are opposed to each other","cn":"差别；差异；分歧","sc":"difference","ex":{"en":"a clash of interests/opinions/cultures","cn":"利益冲突；意见分歧；文化差异"}},{"en":"a situation in which two events happen at the same time so that you cannot go to or see them both","cn":"（时间上的）冲突，矛盾","sc":"of two events","ex":{"en":"a clash in the timetable/schedule","cn":"时间安排有冲突"}},{"en":"a loud noise made by two metal objects being hit together","cn":"（金属的）撞击声","g":"[usually singular]","sc":"loud noise","ex":{"en":"a clash of cymbals/swords","cn":"铙钹的敲击声；剑的撞击声"}},{"en":"an occasion when two teams or players compete against each other","cn":"交锋；交战；比赛","sc":"in sport","ex":{"en":"Bayern’s clash with Roma in the Champions League","cn":"拜仁队在欧洲冠军联赛中与罗马队的交锋"}},{"en":"the situation when two colours, designs, etc. look ugly when they are put together","cn":"不协调；不和谐；搭配不当","sc":"of colours"},{"en":"to come together and fight or compete in a contest","cn":"打斗；冲突；比赛","g":"[intransitive]","sc":"fight/compete","ex":{"en":"The two sets of supporters clashed outside the stadium.","cn":"双方的支持者在体育场外打了起来。"},"pos":"verb"},{"en":"to argue or disagree seriously with somebody about something, and to show this in public","cn":"（公开地）争论，辩论，争辩","g":"[intransitive]","sc":"argue","ex":{"en":"The leaders and members clashed on the issue.","cn":"领袖和下属的成员在这个问题上产生了分歧。"},"pos":"verb"},{"en":"to be very different and opposed to each other","cn":"迥然不同；不相容；抵触","g":"[intransitive]","sc":"be different","ex":{"en":"His left-wing views clashed with his father's politics.","cn":"他的左翼观点与他父亲的政见分歧很大。"},"pos":"verb"},{"en":"to happen at the same time so that you cannot go to or see them both","cn":"（时间上）相冲突，相矛盾","g":"[intransitive]","sc":"of two events","ex":{"en":"Unfortunately your party clashes with a wedding I'm going to.","cn":"不巧得很，你的聚会和我要参加的婚礼在时间上有冲突。"},"pos":"verb"},{"en":"to look ugly when put together","cn":"不协调；不和谐；搭配不当","g":"[intransitive]","sc":"of colours","ex":{"en":"The wallpaper clashes with the carpet.","cn":"墙纸与地毯的色彩不协调。"},"pos":"verb"},{"en":"to hit together and make a loud ringing noise; to make two metal objects do this","cn":"（使）撞击出巨大的响声；（使）当啷作响","g":"[intransitive, transitive]","sc":"make loud noise","ex":{"en":"The long blades clashed together.","cn":"长刀相击铿然作响。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"发生冲突;打斗;争论;意见不合","en":"When people clash, they fight, argue, or disagree with each other.","ex":{"en":"A group of 400 demonstrators clashed with police","cn":"400名示威者与警察发生了冲突。"}},{"pos":"V-RECIP 相互动词","cn":"(信仰、观点、特性)相互冲突，相互抵触，不相容","en":"Beliefs, ideas, or qualities that clash with each other are very different from each other and therefore are opposed.","ex":{"en":"Don't make any policy decisions which clash with official company thinking","cn":"所作的任何决策都不要和公司官方理念相冲突。"}},{"pos":"VERB 动词","cn":"(两件事)时间上冲突，撞期","en":"If one event clashes with another, the two events happen at the same time so that you cannot attend both of them.","ex":{"en":"The detective changed his holiday dates when his flight was brought forward and it now clashed with the trial.","cn":"由于航班提前，侦探更改了度假日期，但是这样一来就和审判冲突了。"}},{"pos":"V-RECIP 相互动词","cn":"(色彩或风格)不协调，不搭配","en":"If one colour or style clashes with another, the colours or styles look ugly together. You can also say that two colours or styles clash .","ex":{"en":"The red door clashed with the soft, natural tones of the stone walls","cn":"红门和石墙柔和的自然色调不协调。"}},{"pos":"V-RECIP 相互动词","cn":"(体育用语中尤用来指热情高涨的比赛双方)交锋，交手，厮杀","en":"Sports journalists sometimes say that two individuals or teams who compete against each other clash, especially when a lot of feeling is involved.","ex":{"en":"Lewis has recently recovered his fitness and will clash with Christie in the 4x100m relay","cn":"刘易斯近来恢复了状态，将在4×100米接力赛中和克里斯蒂一决雌雄。"}},{"pos":"VERB 动词","cn":"(金属相互碰撞)发出当啷当啷声，发出撞击声","en":"When metal objects clash, they make a lot of noise by being hit together.","ex":{"en":"The golden bangles on her arms clashed and jingled.","cn":"她手臂上的金手镯丁零当啷地响。"}}]},"media":{"uk":"media/uk/clash__gb_1.mp3","us":"media/us/clash__us_1.mp3"},"examples":[{"en":"Unfortunately your party clashes with a wedding I'm going to.","cn":"不巧得很，你的聚会和我要参加的婚礼在时间上有冲突。"},{"en":"The leaders clashed with party members on the issue.","cn":"政党领袖与该党党员在这个问题上产生了分歧。"}]},"clauses":{"oxford":{"phon":"klɔːz","pos":"noun","senses":[{"en":"( grammar","cn":"语法 ) a group of words that includes a subject and a verb, and forms a sentence or part of a sentence 从句；分句；子句"},{"en":"an item in a legal document that says that a particular thing must or must not be done （","cn":"法律文件的）条款"}]}},"clause":{"oxford":{"phon":"klɔːz","pos":"noun","senses":[{"en":"a group of words that includes a subject and a verb, and forms a sentence or part of a sentence","cn":"从句；子句；分句","lab":"grammar","ex":{"en":"There are languages that require the subject to come before the object in a clause.","cn":"有些语言要求分句的主语出现在宾语之前。"}},{"en":"an item in a legal document that says that a particular thing must or must not be done","cn":"（法律文件的）条款","ex":{"en":"a confidentiality clause","cn":"保密条款"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(法律文书的)条款","en":"A clause is a section of a legal document.","ex":{"en":"He has a clause in his contract which entitles him to a percentage of the profits.","cn":"他的合同中有一项条款，使他有权分得一定比例的利润。"}},{"pos":"N-COUNT 可数名词","cn":"(语法)分句，从句，子句","en":"In grammar, a clause is a group of words containing a verb. Sentences contain one or more clauses. There are finite clauses and non-finite clauses."}]},"media":{"uk":"media/uk/clause__gb_1.mp3","us":"media/us/clause__us_1.mp3"},"examples":[{"en":"In the sentence ‘They often go to Italy because they love the food’, ‘They often go to Italy’ is the main clause and ‘because they love the food’ is a subordinate clause.","cn":"在 They often go to Italy because they love the food 这个句子里，They often go to Italy 是主句，because they love the food 是从句。"},{"en":"A confidentiality clause was added to the contract.","cn":"合同中加上了一项保密条款。"}]},"clarify":{"oxford":{"phon":"ˈklærəfaɪ","pos":"verb","senses":[{"en":"to make something clearer or easier to understand","cn":"使更清晰易懂；阐明；澄清","lab":"formal","ex":{"en":"to clarify a situation/problem/issue","cn":"澄清情况／问题"}},{"en":"to make something, especially butter, pure by heating it","cn":"（通过加热）纯净，净化（尤指黄油）","ex":{"en":"clarified butter","cn":"已净化的黄油"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"阐明;阐释;说明","en":"To clarify something means to make it easier to understand, usually by explaining it in more detail.","ex":{"en":"Thank you for writing and allowing me to clarify the present position","cn":"谢谢你的来信，并允许我阐明目前的立场。"}}]},"media":{"uk":"media/uk/clarify__gb_1.mp3","us":"media/us/clarify__us_1.mp3"},"examples":[{"en":"She asked him to clarify what he meant.","cn":"她要他说清楚他是什么意思。"},{"en":"I am seeking clarification of the regulations.","cn":"我正在努力弄清楚这些规则。"}]},"clapping":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to hit your hands together loudly and quickly to show that you approve of and are pleased with a play, someone's performance, someone's actions etc","cn":""},{"en":"if people applaud , they clap excitedly, and often for a long time, in order to show how much they liked something or to show their support for someone","cn":""}]},"examples":[{"en":"One man began to clap, and others joined in.","cn":"","src":"ld"},{"en":"The couple were cheered and clapped on their arrival.","cn":"","src":"ld"}],"media":{"uk":"media/uk/clapping__gb_1.mp3","us":"media/us/clapping__us_1.mp3"},"oxford":{"phon":"ˈklæpɪŋ","pos":"noun","senses":[{"en":"the act or the sound of people hitting their open hands together, especially several times to show that they approve of or have enjoyed something","cn":"鼓掌，拍手（表示赞许或欣赏）","ex":{"en":"I could hear the sound of clapping from the other room.","cn":"我听见另一个房间传来掌声。"}}]}},"classic":{"media":{"uk":"media/uk/classic__gb_1.mp3","us":"media/us/classic__us_1.mp3"},"oxford":{"phon":"ˈklæsɪk","pos":"adjective","senses":[{"en":"accepted or deserving to be accepted as one of the best or most important of its kind","cn":"最优秀的；第一流的","ex":{"en":"a classic film/story/car/game","cn":"经典电影／小说／汽车／游戏"}},{"en":"with all the features you would expect to find; very typical","cn":"有代表性的；典型的","lab":"less frequent","ex":{"en":"a classic example of poor communication","cn":"缺乏有效沟通的典型实例"}},{"en":"attractive, but simple and traditional in style or design; not affected by changes in fashion","cn":"（风格或设计）典雅的，古朴的；传统的","ex":{"en":"a classic grey suit","cn":"一套典雅的灰色服装"}},{"en":"people say That’s classic! when they find something very funny, when they think somebody has been very stupid or when something annoying, but not surprising, happens","cn":"好笑的；愚蠢（或令人讨厌）而又不足为奇的","lab":"informal","ex":{"en":"She's not going to help? Oh, that's classic!","cn":"她不来帮忙？哦，那不足为奇！"}},{"en":"a book, film or song which is well known and considered to be of very high quality, setting standards for other books, etc.","cn":"（书、电影或歌曲的）经典作品，名著，杰作","g":"[countable]","ex":{"en":"The film is now a cult classic.","cn":"这部电影现在成了邪典电影的经典之作。"},"pos":"noun"},{"en":"a thing that is an excellent example of its kind","cn":"优秀的典范","g":"[countable]","ex":{"en":"That match was a classic.","cn":"那场比赛堪称经典。"},"pos":"noun"},{"en":"a piece of clothing, a vehicle or other item that is admired for its beautiful style or design that is not affected by changes in fashion","cn":"（时装、汽车等的）经典款","ex":{"en":"Classics don't lose their style.","cn":"经典款永不过时。"},"pos":"noun"},{"en":"the study of ancient Greek and Roman culture, especially their languages and literature","cn":"古典学（对古希腊与古罗马文化的研究，尤涉语言与文学）","g":"[uncountable]","ex":{"en":"a degree in Classics","cn":"古典学学位"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"典型的","en":"A classic example of a thing or situation has all the features which you expect such a thing or situation to have.","ex":{"en":"The debate in the mainstream press has been a classic example of British hypocrisy","cn":"主流媒体上的辩论是英国式虚伪的典型例子。"}},{"pos":"ADJ 形容词","cn":"(电影、著作、音乐)经典的，典范的，最优秀的","en":"A classic film, piece of writing, or piece of music is of very high quality and has become a standard against which similar things are judged.","ex":{"en":"...the classic children's film Huckleberry Finn.","cn":"经典儿童电影《哈克贝利·费恩历险记》"}},{"pos":"N-COUNT 可数名词","cn":"文学经典;名著;杰作","en":"A classic is a book which is well-known and considered to be of a high literary standard. You can refer to such books generally as the classics .","ex":{"en":"As I grow older, I like to reread the classics regularly.","cn":"随着年龄渐长，我喜欢经常重读经典著作。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(风格)传统的，古雅的，古朴的","en":"Classic style is simple and traditional and is not affected by changes in fashion.","ex":{"en":"Wear classic clothes which feel good and look good","cn":"穿些舒适而又好看的传统服装。"}},{"pos":"ADJ 形容词","cn":"(轿车)经典的，(尤指)老式的","en":"A classic car is a model of car that is greatly admired because of its style, and is considered to be one of the best of its kind; used especially to talk about cars which are no longer being produced."},{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指对古希腊、古罗马的语言、文学、哲学的)古典文化研究","en":"Classics is the study of the ancient Greek and Roman civilizations, especially their languages, literature, and philosophy.","ex":{"en":"...a Classics degree.","cn":"古典文化研究学位"}}]},"examples":[{"en":"I made the classic mistake of clapping in a pause in the music!","cn":"我在乐曲演奏暂停的间歇鼓起掌来，真是大错特错！"},{"en":"English classics such as ‘Alice in Wonderland’","cn":"英语经典作品如《艾丽丝漫游奇境记》"}]},"closely":{"oxford":{"phon":"ˈkləʊsli","pos":"adverb","senses":[{"en":"near in space or time","cn":"（空间或时间上）接近地，靠近地","ex":{"en":"He walked into the room, closely followed by the rest of the family.","cn":"他走进房间，后面紧跟着他的家人。"}},{"en":"near in family relationship","cn":"（家庭关系）亲近地","ex":{"en":"The two species are closely related.","cn":"这两个物种关系很近。"}},{"en":"having a strong connection","cn":"紧密相关地；密切关联地","ex":{"en":"to be closely linked/associated/related","cn":"密切相关"}},{"en":"in a way that shows you are very involved in the work or activities of somebody else, usually seeing and talking to them regularly","cn":"（工作或活动上）深度参与地，紧密合作地","ex":{"en":"The organization works closely with customers in nearly 100 countries.","cn":"该组织与近 100 个国家的消费者紧密合作。"}},{"en":"carefully","cn":"细致地","ex":{"en":"I sat and watched everyone very closely.","cn":"我坐下来密切注视着每一个人。"}},{"en":"in a way that is very similar to somebody/something else","cn":"酷似地","ex":{"en":"She closely resembled her mother at the same age.","cn":"她酷似她母亲当年的样子。"}},{"en":"won or likely to be won by only a small amount or distance","cn":"势均力敌地；旗鼓相当地","ex":{"en":"a closely contested election","cn":"实力相当的竞选"}},{"en":"with little or no space in between","cn":"空隙极小地；无空隙地；密集地；紧凑地","ex":{"en":"over 1 000 closely printed pages","cn":"排得密密麻麻的 1 000 多页"}},{"en":"cut very short, near to the skin","cn":"剪到齐根地；剪得很短地","ex":{"en":"He had a closely shaved head and a small, neat beard.","cn":"他头发剃得很短，留了一撮整齐的小胡子。"}}]},"media":{"uk":"media/uk/closely__gb_1.mp3","us":"media/us/closely__us_1.mp3"},"examples":[{"en":"She closely resembled her mother at the same age.","cn":"她与她母亲在相同的年龄时长相酷似。"},{"en":"He walked into the room, closely followed by the rest of the family.","cn":"他走进房间，后面紧跟着他的家人。"}]},"cliff":{"media":{"uk":"media/uk/cliff__gb_1.mp3","us":"media/us/cliff__us_1.mp3"},"oxford":{"phon":"klɪf","pos":"noun","senses":[{"en":"a high area of rock with a very steep side, often at the edge of the sea or ocean","cn":"（常指海洋边的）悬崖，峭壁","ex":{"en":"the cliff edge/top","cn":"悬崖边缘／顶端"}},{"en":"a first name for boys, short for Clifford","cn":"克里夫（男子名，Clifford缩写）","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指靠海的)悬崖，峭壁","en":"A cliff is a high area of land with a very steep side, especially one next to the sea.","ex":{"en":"The car rolled over the edge of a cliff.","cn":"汽车从悬崖边上滚下去了。"}}]},"examples":[{"en":"a castle perched high on the cliffs above the river","cn":"高高耸立在临河峭壁上的城堡"},{"en":"the chalk cliffs of southern England","cn":"英格兰南部的白垩质峭壁"}]},"clarification":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of making something clearer or easier to understand, or an explanation that makes something clearer","cn":"澄清﹐阐明"}]},"examples":[{"en":"There have been a number of official changes and clarifications.","cn":"官方有过数次修改和说明。","src":"ld"},{"en":"Email us if you require further clarification on how to order.","cn":"如需进一步了解如何订货﹐请给我们发电子邮件。","src":"ld"}],"media":{"uk":"media/uk/clarification__gb_1.mp3","us":"media/us/clarification__us_1.mp3"},"oxford":{"phon":"ˌklærəfɪˈkeɪʃn","pos":"noun","senses":[{"en":"the act or process of making something clearer or easier to understand","cn":"使更清晰易懂；阐明；澄清","ex":{"en":"I am seeking clarification of the regulations.","cn":"我正在努力弄清楚这些规则。"}}]}},"closed":{"media":{"uk":"media/uk/closed__gb_1.mp3","us":"media/us/closed__us_1.mp3"},"oxford":{"phon":"kləʊzd","pos":"adjective","senses":[{"en":"shut","cn":"关闭；封闭","ex":{"en":"Keep the door closed.","cn":"让门关着吧。"}},{"en":"shut, especially of a shop or public building that is not open for a period of time","cn":"关闭；（尤指一段时间）停止营业，不开放","g":"[not before noun]","ex":{"en":"The museum is closed on Mondays.","cn":"博物馆每逢星期一闭馆。"}},{"en":"not willing to accept outside influences or new ideas","cn":"封闭的；闭关自守的；不愿接受新思想的","ex":{"en":"a closed society","cn":"闭关自守的社会"}},{"en":"limited to a particular group of people; not open to everyone","cn":"只限于某些人的；仅为少数人的；不向公众开放的","g":"[usually before noun]","ex":{"en":"a closed membership","cn":"只限于少数人的成员资格"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"封闭的；不接受新人（或新思想）的","en":"A closed group of people does not welcome new people or ideas from outside.","ex":{"en":"It was to be a closed circle of no more than twelve women","cn":"它本来应该是一个不超过12名女性的封闭的小圈子。"}},{"pos":"See also:","cn":"","en":"a closed book→see: ; behind closed doors→see: ;"}]},"examples":[{"en":"The museum is closed on Mondays.","cn":"博物馆每逢星期一闭馆。"},{"en":"This road is closed to traffic.","cn":"这条道路暂停通行。"}]},"clatter":{"media":{"uk":"media/uk/clatter__gb_1.mp3","us":"media/us/clatter__us_1.mp3"},"oxford":{"phon":"ˈklætə(r)","pos":"verb","senses":[{"en":"if hard objects clatter, they knock together and make a loud noise","cn":"（硬物相碰）发出响亮的撞击声","g":"[intransitive]","ex":{"en":"He dropped the knife and it clattered on the stone floor.","cn":"他一失手，刀子当啷一声掉到石头地面上。"}},{"en":"to move making a loud noise like hard objects knocking together","cn":"哐当作响地移动","g":"[intransitive]","ex":{"en":"The cart clattered over the cobbles.","cn":"马车哐当哐当地行驶在卵石路上。"}},{"en":"the act of making a loud noise like hard objects knocking together","cn":"移动发出（像硬物碰撞）的响声","ex":{"en":"the clatter of horses’ hoofs","cn":"马蹄的嗒嗒声"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(移动时)发出声响","en":"If you say that people or things clatter somewhere, you mean that they move there noisily.","ex":{"en":"He turned and clattered down the stairs.","cn":"他转过身，噔噔噔地下了楼梯。"}},{"pos":"VERB 动词","cn":"(硬物)发出碰撞声","en":"If something hard clatters, it makes repeated short noises as it hits against another hard thing.","ex":{"en":"His hobnail boots clattered on the stone floor","cn":"他那双钉了铁掌的靴子在石地板上嗒嗒响。"}}]},"examples":[{"en":"He dropped the knife and it clattered on the stone floor.","cn":"他一失手，刀子当啷一声掉到石头地面上。"},{"en":"She heard him clattering around downstairs.","cn":"她听到他在楼下咔哒咔哒地走来走去。"}]},"classrooms":{"oxford":{"phon":"ˈklɑːsruːm","pos":"noun","senses":[{"en":"a room where a class of children or students is taught","cn":"教室；课堂"}]},"media":{"img":["media/pic/classroom_objects_comp.jpg","media/thumb/classroom.jpg"],"uk":"media/uk/classroom__gb_1.mp3","us":"media/us/classroom__us_1.mp3"}},"cling":{"media":{"uk":"media/uk/cling__gb_1.mp3","us":"media/us/cling__us_1.mp3"},"oxford":{"phon":"klɪŋ","pos":"verb","senses":[{"en":"to hold on tightly to somebody/something","cn":"抓紧；紧握；紧抱","g":"[intransitive]","ex":{"en":"survivors clinging to a raft","cn":"紧紧抓住救生筏的幸存者"}},{"en":"to stick to something","cn":"粘住；附着","g":"[intransitive]","ex":{"en":"a dress that clings (= fits closely and shows the shape of your body)","cn":"紧身连衣裙"}},{"en":"to stay close to somebody, especially because you need them emotionally","cn":"（尤指情感上）依恋，依附","g":"[intransitive]","lab":"usually disapproving","ex":{"en":"After her mother's death, Sara clung to her aunt more than ever.","cn":"萨拉在母亲去世后比以往任何时候都更依附于她的姨妈。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"紧紧抓住;抱紧","en":"If you cling to someone or something, you hold onto them tightly.","ex":{"en":"Another man was rescued as he clung to the riverbank","cn":"另外一个人因为紧紧攀住河堤而获救。"}},{"pos":"VERB 动词","cn":"抓住(职位或财产)不放","en":"If someone clings to a position or a possession they have, they do everything they can to keep it even though this may be very difficult.","ex":{"en":"He appears determined to cling to power","cn":"看来他决心要抓住权力不放。"}},{"pos":"VERB 动词","cn":"(衣服)紧附，黏着","en":"Clothes that cling to you stay pressed against your body when you move.","ex":{"en":"His sodden trousers were clinging to his shins.","cn":"湿淋淋的裤子紧紧粘在他小腿上。"}},{"pos":"VERB 动词","cn":"黏附；粘住","en":"Something that is clinging to something else is stuck on it or just attached to it.","ex":{"en":"Her glass had bits of orange clinging to the rim.","cn":"她的杯口上粘有些许橙汁。"}},{"pos":"VERB 动词","cn":"缠住;依附","en":"If someone clings to a person they are fond of, they do not allow that person to be free or independent.","ex":{"en":"I was terrified he would leave me, so I was clinging to him.","cn":"我害怕他会离开我，所以缠着他不放。"}},{"pos":"VERB 动词","cn":"墨守，坚持(观念或行为方式)","en":"If you cling to an idea or way of behaving, you continue to believe in its value or importance, even though it may no longer be valid or useful.","ex":{"en":"They know scholars reject their legend, but they still cling to their belief","cn":"尽管知道学者们不相信他们的传说，他们还是坚持自己的信仰。"}}]},"examples":[{"en":"After her mother's death, Sara clung to her aunt more than ever.","cn":"萨拉在母亲去世后比以往任何时候都更依附于她的姨妈。"},{"en":"Throughout the trial she had clung to the belief that he was innocent.","cn":"在整个审判中，她都坚信他是清白的。"}]},"clog":{"media":{"img":["media/pic/shoes_comp.jpg","media/thumb/clogs.jpg","media/ldoce/img/clogs.jpg"],"uk":"media/uk/clog__gb_1.mp3","us":"media/us/clog__us_1.mp3"},"oxford":{"phon":"klɒɡ","pos":"verb","senses":[{"en":"to block something or to become blocked","cn":"（使）阻塞，堵塞","ex":{"en":"The narrow streets were clogged with traffic.","cn":"狭窄的街道上交通堵塞。"}},{"en":"a shoe that is completely made of wood or one that has a thick wooden sole and a leather top","cn":"木底鞋；木鞋；木屐","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"阻塞;堵塞","en":"When something clogs a hole or place, it blocks it so that nothing can pass through.","ex":{"en":"Dirt clogs the pores, causing spots","cn":"灰尘堵塞毛孔，从而生出粉刺。"}},{"pos":"N-COUNT 可数名词","cn":"厚木底皮鞋;木屐","en":"Clogs are heavy leather or wooden shoes with thick wooden soles."},{"pos":"PHRASE 短语","cn":"翘辫子;一命呜呼","en":"If you say that someone has popped their clogs, you mean that they have died."},{"pos":"","cn":"","en":"相关词组：clog up"}]},"examples":[{"en":"Within a few years the pipes began to clog up.","cn":"没有几年管子就开始堵塞了。"},{"en":"The narrow streets were clogged with traffic.","cn":"狭窄的街道上交通堵塞。"}]},"closure":{"media":{"uk":"media/uk/closure__gb_1.mp3","us":"media/us/closure__us_1.mp3"},"oxford":{"phon":"ˈkləʊʒə(r)","pos":"noun","senses":[{"en":"the situation when a factory, school, hospital, etc. shuts permanently","cn":"（永久的）停业，关闭；倒闭","g":"[countable, uncountable]","ex":{"en":"factory closures","cn":"工厂倒闭"}},{"en":"the temporary closing of a road or bridge","cn":"（路或桥的）暂时封闭","g":"[countable, uncountable]","ex":{"en":"There will be road closures and diversions in the area from 8 p.m.","cn":"从晚上8点开始，该地区将封闭道路并改道。"}},{"en":"the feeling that a difficult or an unpleasant experience has come to an end or been dealt with in an acceptable way","cn":"（因困境结束或事情得到妥善处理等的）宽慰；如释重负","g":"[uncountable]","ex":{"en":"The conviction of their son's murderer helped to give them a sense of closure.","cn":"谋杀儿子的凶手被判罪，让他们得到了一些安慰。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(企业、工厂等的)永久性关闭，停业","en":"The closure of a place such as a business or factory is the permanent ending of the work or activity there.","ex":{"en":"...the closure of the Ravenscraig steelworks","cn":"雷文斯克拉格钢铁厂的关闭"}},{"pos":"N-COUNT 可数名词","cn":"(道路或边界的)封闭，封锁","en":"The closure of a road or border is the blocking of it in order to prevent people from using it."},{"pos":"N-UNCOUNT 不可数名词","cn":"解脱","en":"If someone achieves closure, they succeed in accepting something bad that has happened to them.","ex":{"en":"I asked McKeown if the reunion was meant to achieve closure.","cn":"我问麦基翁重聚是不是为了寻求解脱。"}}]},"examples":[{"en":"The conviction of their son's murderer helped to give them a sense of closure.","cn":"谋杀儿子的凶手被判罪，让他们得到了一些安慰。"},{"en":"The hospital has been threatened with closure.","cn":"这家医院面临着关闭的威胁。"}]},"clung":{"collins":{"senses":[{"pos":"","cn":"","en":"Clung is the past tense and past participle of cling."}]},"media":{"uk":"media/uk/clung__gb_1.mp3","us":"media/us/clung__us_1.mp3"}},"club":{"media":{"uk":"media/uk/club__gb_1.mp3","us":"media/us/club__us_1.mp3"},"oxford":{"phon":"klʌb","pos":"noun","senses":[{"en":"an organization for people who share an interest or do a sport or activity together","cn":"俱乐部；社团；会","g":"[countable + singular or plural verb]","sc":"for activity/sport","ex":{"en":"a golf/tennis/chess/film club","cn":"高尔夫球／网球／国际象棋／电影俱乐部"}},{"en":"the building or rooms that a particular club uses","cn":"（俱乐部使用的）建筑设施，活动室","g":"[countable]","sc":"for activity/sport","ex":{"en":"We had lunch at the golf club.","cn":"我们在高尔夫球俱乐部吃了午饭。"}},{"en":"a professional sports organization that includes the players, managers, owners and members","cn":"职业运动俱乐部","g":"[countable + singular or plural verb]","lab":"British English","sc":"for activity/sport","ex":{"en":"Manchester United Football Club","cn":"曼联职业足球俱乐部"}},{"en":"a place where people, especially young people, go and listen to music, dance, watch comedy, etc.","cn":"（尤指年轻人娱乐的）俱乐部，夜总会","g":"[countable]","sc":"music/dancing","ex":{"en":"a jazz club","cn":"爵士乐夜总会"}},{"en":"(especially in the UK) an organization and a place where people can meet together socially or stay","cn":"俱乐部","g":"[countable + singular or plural verb]","sc":"social","ex":{"en":"He's a member of several London clubs.","cn":"他是伦敦几个俱乐部的会员。"}},{"en":"a business that offers items or services cheaply to its members","cn":"（会员可享优惠的）俱乐部","g":"[countable]","sc":"selling goods/services","ex":{"en":"You could become a member of an investment club.","cn":"您可以成为投资俱乐部的成员。"}},{"en":"a heavy stick with one end thicker than the other, that is used as a weapon","cn":"击棍（一头粗一头细）","g":"[countable]","sc":"weapon"},{"en":"a long metal stick with a piece of metal or wood at one end, used for hitting the ball in golf","cn":"高尔夫球杆","g":"[countable]","sc":"in golf"},{"en":"one of the four suits (= sets) in a pack of cards. The clubs have a black design with shapes like three black leaves on a short stem.","cn":"（扑克牌的）梅花","g":"[plural, uncountable]","sc":"in card games","ex":{"en":"the five/queen/ace of clubs","cn":"梅花五／Q／A"}},{"en":"one card from the suit called clubs","cn":"梅花牌","g":"[countable]","sc":"in card games","ex":{"en":"I played a club.","cn":"我出梅花。"}},{"en":"to hit a person or an animal with a heavy stick or similar object","cn":"用棍棒（或类似棍棒之物）打","g":"[transitive]","ex":{"en":"The victim was clubbed to death with a baseball bat.","cn":"受害者被人用棒球球棒殴打致死。"},"pos":"verb"},{"en":"to spend time dancing and drinking in nightclubs","cn":"泡夜总会","g":"[intransitive]","lab":"informal","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"俱乐部;会;社团","en":"A club is an organization of people interested in a particular activity or subject who usually meet on a regular basis.","ex":{"en":"...the Chorlton Conservative Club.","cn":"升尔顿保守党俱乐部"}},{"pos":"N-COUNT 可数名词","cn":"俱乐部会所；俱乐部活动场所","en":"A club is a place where the members of a club meet.","ex":{"en":"I stopped in at the club for a drink.","cn":"我顺路到俱乐部喝了一杯。"}},{"pos":"N-COUNT 可数名词","cn":"职业运动俱乐部","en":"A club is a team which competes in sporting competitions.","ex":{"en":"...the New York Yankees baseball club.","cn":"纽约扬基职业棒球俱乐部"}},{"pos":"N-COUNT 可数名词","cn":"同 nightclub","en":"A club is the same as a nightclub .","ex":{"en":"It's a big dance hit in the clubs.","cn":"这支舞曲在夜总会很火。"}},{"pos":"N-COUNT 可数名词","cn":"(高尔夫球)球杆","en":"A club is a long, thin, metal stick with a piece of wood or metal at one end that you use to hit the ball in golf.","ex":{"en":"...a six-iron club.","cn":"6号铁杆"}},{"pos":"N-COUNT 可数名词","cn":"大棒;棍棒","en":"A club is a thick heavy stick that can be used as a weapon.","ex":{"en":"Men armed with knives and clubs attacked his home.","cn":"一群手持刀棒的人袭击了他家。"}},{"pos":"VERB 动词","cn":"(用大棒等)狠狠地打,猛击","en":"To club a person or animal means to hit them hard with a thick heavy stick or a similar weapon.","ex":{"en":"Two thugs clubbed him with baseball bats","cn":"两个暴徒用棒球棒猛击他。"}},{"pos":"N-UNCOUNT-COLL 不可数集合名词","cn":"(纸牌中的)梅花","en":"Clubs is one of the four suits in a pack of playing cards. Each card in the suit is marked with one or more black symbols: ♣.","ex":{"en":"...the ace of clubs.","cn":"梅花A"}},{"pos":"","cn":"","en":"相关词组：club together"}]},"examples":[{"en":"We clubbed together to buy them a new television.","cn":"我们凑钱给他们买了一台新电视机。"},{"en":"The club has/have voted to admit new members.","cn":"俱乐部通过投票同意接纳新成员。"}]},"clout":{"media":{"uk":"media/uk/clout__gb_1.mp3","us":"media/us/clout__us_1.mp3"},"oxford":{"phon":"klaʊt","pos":"noun","senses":[{"en":"power and influence","cn":"影响力；势力","g":"[uncountable]","ex":{"en":"political/financial clout","cn":"政治／经济势力"}},{"en":"a hard hit with the hand or a hard object","cn":"（用手或硬物的）击，打","g":"[countable, usually singular]","lab":"especially British English, informal，，","ex":{"en":"You’re not too big for a clout round the ear!","cn":"你还不算大，无法对耳朵施加影响！"}},{"en":"to hit somebody hard, especially with your hand","cn":"（尤指用手）猛击，重打","ex":{"en":"He started to clout me round the head, yelling at the top of his voice.","cn":"他开始用拳头打我的头，大声喊叫。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"打;击","en":"If you clout someone, you hit them.","ex":{"en":"Rachel clouted him","cn":"雷切尔揍了他一下。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"影响力;权势","en":"A person or institution that has clout has influence and power.","ex":{"en":"Mr Sutherland may have the clout needed to push the two trading giants into a deal","cn":"萨瑟兰先生也许有能力促使两大贸易巨头达成协议。"}}]},"examples":[{"en":"I knew his opinion carried a lot of clout with them.","cn":"我知道他的观点对他们很有影响力。"},{"en":"political/financial clout","cn":"政治/经济势力"}]},"classroom":{"media":{"img":["media/pic/classroom_objects_comp.jpg","media/thumb/classroom.jpg"],"uk":"media/uk/classroom__gb_1.mp3","us":"media/us/classroom__us_1.mp3"},"oxford":{"phon":"ˈklɑːsruːm","pos":"noun","senses":[{"en":"a room where a class of children or students is taught","cn":"教室；课堂","ex":{"en":"classroom activities","cn":"课堂活动"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"教室","en":"A classroom is a room in a school where lessons take place."}]},"examples":[{"en":"the use of computers in the classroom","cn":"在课堂使用计算机"},{"en":"classroom activities","cn":"课堂活动"}]},"clue":{"media":{"uk":"media/uk/clue__gb_1.mp3","us":"media/us/clue__us_1.mp3"},"oxford":{"phon":"kluː","pos":"noun","senses":[{"en":"an object, a piece of evidence or some information that helps the police solve a crime","cn":"（帮助警方破案的）线索，迹象","ex":{"en":"The burglar left no clues.","cn":"窃贼没有留下任何线索。"}},{"en":"a fact or a piece of evidence that helps you discover the answer to a problem","cn":"（问题答案的）线索，提示","ex":{"en":"This data may provide clues about the current economic situation.","cn":"这些数据可提供有关当前经济形势的线索。"}},{"en":"some words or a piece of information that helps you find the answers to a crossword, a game or a question","cn":"（纵横填字谜、游戏或问题的）提示词语，解答提示","ex":{"en":"‘You'll never guess who I saw today!’ ‘Give me a clue.’","cn":"“你绝对猜不着我今天见到谁了！”“给我提示一下吧。”"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"线索;提示","en":"A clue to a problem or mystery is something that helps you to find the answer to it.","ex":{"en":"Geneticists in Canada have discovered a clue to the puzzle of why our cells get old and die","cn":"加拿大的遗传学家已经发现了解开细胞衰老、死亡之谜的线索。"}},{"pos":"N-COUNT 可数名词","cn":"(破案)线索","en":"A clue is an object or piece of information that helps someone solve a crime.","ex":{"en":"The vital clue to the killer's identity was his nickname, Peanuts.","cn":"查明杀手身份的重要线索是他的外号叫“花生”。"}},{"pos":"N-COUNT 可数名词","cn":"(纵横填字游戏的)提示语，解答提示","en":"A clue in a crossword or game is information which is given to help you to find the answer to a question."},{"pos":"PHRASE 短语","cn":"不知道;一无所知","en":"If you haven't a clue about something, you do not know anything about it or you have no idea what to do about it.","ex":{"en":"I haven't a clue what I'll give Carl for his birthday next year.","cn":"我不知道明年卡尔过生日我该送什么。"}}]},"examples":[{"en":"The police think the videotape may hold some vital clues to the identity of the killer.","cn":"警方认为那盘录像带可能录有能确认凶手身分的一些重要线索。"},{"en":"‘You'll never guess who I saw today!’ ‘Give me a clue.’ “","cn":"你绝对猜不着我今天见到谁了！” “给我提示一下吧。”"}]},"close-fitting":{"oxford":{"phon":"ˌkləʊs ˈfɪtɪŋ","pos":"adjective","senses":[{"en":"fitting tightly, showing the shape of the body","cn":"紧身的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(衣服)紧身的","en":"Close-fitting clothes fit tightly and show the shape of your body."}]},"media":{"uk":"media/uk/close_fitting_1_gb_1.mp3","us":"media/us/close_fitting_1_us_1.mp3"}},"claim":{"media":{"uk":"media/uk/claim__gb_1.mp3","us":"media/us/claim__us_1.mp3"},"oxford":{"phon":"kleɪm","pos":"verb","senses":[{"en":"to say that something is true although it has not been proved and other people may not believe it","cn":"宣称；声称；断言","g":"[transitive]","sc":"say something is true/you have done something","ex":{"en":"He claims (that) he was not given a fair hearing.","cn":"他声称他未得到公正的申诉机会。"}},{"en":"to state that you have done, gained or achieved something","cn":"声称（完成或取得）","g":"[transitive]","sc":"say something is true/you have done something","ex":{"en":"He claimed victory in the presidential elections before all the results were in.","cn":"没等结果完全出来，他就宣布赢得总统大选。"}},{"en":"to ask for money from the government or a company because you have a right to it","cn":"索要；索取","g":"[transitive, intransitive]","sc":"money","ex":{"en":"He's not entitled to claim housing benefit.","cn":"他没有资格申领住房补贴。"}},{"en":"to demand or ask for something because you believe it is your legal right to own or to have it","cn":"要求（拥有）；索取；认领","g":"[transitive]","sc":"demand legal right","ex":{"en":"A lot of lost property is never claimed.","cn":"许多失物从未被认领。"}},{"en":"to get or take somebody’s attention","cn":"引起注意","g":"[transitive]","sc":"attention/thought","ex":{"en":"A most unwelcome event claimed his attention.","cn":"一件非常讨厌的事情需要他去考虑。"}},{"en":"to gain, win or achieve something","cn":"获得；赢得；取得","g":"[transitive]","sc":"gain/win","ex":{"en":"She has finally claimed a place on the team.","cn":"她终于成了那支队的队员。"}},{"en":"to cause somebody’s death","cn":"夺走，夺去（生命）","g":"[transitive]","sc":"cause death","ex":{"en":"The car crash claimed three lives.","cn":"那次撞车事故导致三人死亡。"}},{"en":"a statement that something is true although it has not been proved and other people may not agree with or believe it","cn":"声称；宣称；断言","g":"[countable]","sc":"saying something is true","ex":{"en":"The company had made false claims about its products.","cn":"这家公司对其产品做了虚假宣传。"},"pos":"noun"},{"en":"a request for a sum of money that you believe you have a right to, especially from a company, the government, etc.","cn":"（尤指向公司、政府等）索款，索赔","g":"[countable]","sc":"for money","ex":{"en":"You can make a claim on your insurance policy.","cn":"你可按保险单索赔。"},"pos":"noun"},{"en":"a right that somebody believes they have to something, especially property, land, etc.","cn":"（尤指对财产、土地等要求拥有的）所有权","g":"[countable, uncountable]","sc":"legal right","ex":{"en":"nineteenth-century land claims","cn":"十九世纪的土地所有权"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"声称;断言","en":"If you say that someone claims that something is true, you mean they say that it is true but you are not sure whether or not they are telling the truth.","ex":{"en":"He claimed that it was all a conspiracy against him","cn":"他声称这一切都是一场针对他的阴谋。"}},{"pos":"N-COUNT 可数名词","cn":"声称;断言","en":"A claim is something which someone says which they cannot prove and which may be false.","ex":{"en":"He repeated his claim that the people of Trinidad and Tobago backed his action","cn":"他再次声称，特立尼达和多巴哥的人民支持他的行动。"}},{"pos":"VERB 动词","cn":"声称(负有责任或享有功劳)","en":"If you say that someone claims responsibility or credit for something, you mean they say that they are responsible for it, but you are not sure whether or not they are telling the truth.","ex":{"en":"An underground organisation has claimed responsibility for the bomb explosion","cn":"一个地下组织已经声称对这起炸弹爆炸事件负责。"}},{"pos":"VERB 动词","cn":"索取，索要(有权拥有的东西)","en":"If you claim something, you try to get it because you think you have a right to it.","ex":{"en":"Now they are returning to claim what was theirs.","cn":"如今他们回来索取本属于他们的东西。"}},{"pos":"N-COUNT 可数名词","cn":"主张;要求","en":"A claim is a demand for something that you think you have a right to.","ex":{"en":"Rival claims to Macedonian territory caused conflict in the Balkans.","cn":"多方主张拥有对马其顿的领土主权，结果在巴尔干地区引发了冲突。"}},{"pos":"VERB 动词","cn":"取得，获得，赢得(纪录、冠军或奖励)","en":"If someone claims a record, title, or prize, they gain or win it.","ex":{"en":"Zhuang claimed the record in 54.64 seconds","cn":"庄创下了54.64秒的纪录。"}},{"pos":"N-COUNT 可数名词","cn":"权利;要求权","en":"If you have a claim on someone or their attention, you have the right to demand things from them or to demand their attention.","ex":{"en":"She'd no claims on him now","cn":"现在他不欠她什么了。"}},{"pos":"VERB 动词","cn":"需要，要求(花时间或精力)","en":"If something or someone claims your attention, they need you to spend your time and effort on them.","ex":{"en":"There is already a long list of people claiming her attention.","cn":"需要她关注的人已经很多了。"}},{"pos":"VERB 动词","cn":"索要，索取，申领(钱)","en":"If you claim money from the government, an insurance company, or another organization, you officially apply to them for it, because you think you are entitled to it according to their rules.","ex":{"en":"Some 25 per cent of the people who are entitled to claim State benefits do not do so","cn":"有权申领政府补贴的人当中，约有25%没有提出申请。"}},{"pos":"VERB 动词","cn":"(向雇主)索要，索取，讨要(钱、福利)","en":"If you claim money or other benefits from your employers, you demand them because you think you deserve or need them.","ex":{"en":"The union claimed a pay rise worth four times the rate of inflation.","cn":"工会要求按照通货膨胀率的4倍提高工资。"}},{"pos":"VERB 动词","cn":"(战争、疾病、事故)夺去(生命)，导致(死亡)","en":"If you say that a war, disease, or accident claims someone's life, you mean that they are killed in it or by it.","ex":{"en":"The civil war claimed the life of a U.N. interpreter yesterday","cn":"昨天，内战夺去了一位联合国译员的生命。"}},{"pos":"PHRASE 短语","cn":"成名之举；成名之作","en":"Someone's claim to fame is something quite important or interesting that they have done or that is connected with them.","ex":{"en":"Barbara Follett's greatest claim to fame is that she taught Labour MPs how to look good on television.","cn":"芭芭拉·福利特最出名的事就是她教工党议员如何在电视上拥有良好形象。"}},{"pos":"PHRASE 短语","cn":"声称拥有","en":"If you lay claim to something you do not have, you say that it belongs to you.","ex":{"en":"Five Asian countries lay claim to the islands.","cn":"5个亚洲国家声称对那些岛屿拥有主权。"}},{"pos":"","cn":"","en":"to stake a claim→see: ;"}]},"examples":[{"en":"The singer has denied the magazine's claim that she is leaving the band.","cn":"这名歌手已否认那家杂志有关她要离开乐队的说法。"},{"en":"You can claim on your insurance for that coat you left on the train.","cn":"你可按你的保险索赔你遗忘在火车上的大衣。"}]},"clumsy":{"media":{"uk":"media/uk/clumsy__gb_1.mp3","us":"media/us/clumsy__us_1.mp3"},"oxford":{"phon":"ˈklʌmzi","pos":"adjective","senses":[{"en":"moving or doing things in a way that is not smooth or steady or careful","cn":"笨拙的；不灵巧的","ex":{"en":"I spilt your coffee. Sorry—that was clumsy of me.","cn":"我弄洒了你的咖啡。对不起，我真是笨手笨脚的。"}},{"en":"done without skill or in a way that offends people","cn":"无技巧的；冒犯人的；不得体的","ex":{"en":"She made a clumsy attempt to apologize.","cn":"她本想道歉，但措辞生硬。"}},{"en":"difficult to move or use easily; not well designed","cn":"难以移动的；难用的；设计欠佳的"},{"en":"too complicated to understand or use easily","cn":"复杂难懂的；使用不便的","ex":{"en":"The complaints procedure is clumsy and time-consuming.","cn":"申诉程序复杂耗时。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"笨拙的;不灵活的","en":"A clumsy person moves or handles things in a careless, awkward way, often so that things are knocked over or broken.","ex":{"en":"I'd never seen a clumsier, less coordinated boxer","cn":"我从没见过更笨拙、动作更不协调的拳击手。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行为或措词)不得体的，拙劣的","en":"A clumsy action or statement is not skilful or is likely to upset people.","ex":{"en":"The action seemed a clumsy attempt to topple the Janata Dal government","cn":"这一试图推翻人民党政府的行动似乎缺乏策略。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(设计或外表)粗糙的，难用的;设计欠佳的","en":"An object that is clumsy is not neat in design or appearance, and is often awkward to use.","ex":{"en":"The keyboard is a large and clumsy instrument as far as portable computers are concerned","cn":"就手提电脑而言，键盘就显得大而笨重了。"}}]},"examples":[{"en":"I spilt your coffee. Sorry — that was clumsy of me.","cn":"我弄洒了你的咖啡。对不起，我真是笨手笨脚的。"},{"en":"His clumsy fingers couldn't untie the knot.","cn":"他的手很笨拙，无法解开这个结。"}]},"class":{"media":{"uk":"media/uk/class__gb_1.mp3","us":"media/us/class__us_1.mp3"},"oxford":{"phon":"klɑːs","pos":"noun","senses":[{"en":"a group of students who are taught together","cn":"班；班级","g":"[countable + singular or plural verb]","sc":"in education","ex":{"en":"We were in the same class at school.","cn":"我们在上学时同过班。"}},{"en":"an occasion when a group of students meets to be taught","cn":"课；上课","g":"[countable, uncountable]","lab":"British English","sc":"in education","ex":{"en":"I have a history class at 9 o'clock.","cn":"我 9 点钟有历史课。"}},{"en":"a series of classes on a particular subject","cn":"（某科目的）系列课程","g":"[countable]","sc":"in education","ex":{"en":"Are you still doing your French evening class?","cn":"你还在夜校学习法语吗？"}},{"en":"a group of students who finish their studies at school, college or university in a particular year","cn":"同届毕业生","g":"[countable + singular or plural verb]","lab":"especially North American English","sc":"in education","ex":{"en":"the class of 2020","cn":"2020 届毕业生"}},{"en":"one of the groups of people in a society that are thought of as being at the same social or economic level","cn":"阶级；阶层","g":"[countable + singular or plural verb]","sc":"in society","ex":{"en":"the working/middle/upper class","cn":"工人／中产／上层阶级"}},{"en":"the way that people are divided into different social and economic groups","cn":"社会等级","g":"[uncountable]","sc":"in society","ex":{"en":"differences of class, race or gender","cn":"社会等级、种族或性别差异"}},{"en":"each of several different levels of comfort that are available to travellers in a plane, etc.","cn":"等级；舱位等级","g":"[countable]","sc":"in train/plane","ex":{"en":"He always travels business class.","cn":"他总是坐公务舱旅行。"}},{"en":"a group of people, animals or things that have similar characteristics or qualities","cn":"种类；类别；等级","g":"[countable]","sc":"group of people/animals","ex":{"en":"It was good accommodation for a hotel of this class.","cn":"就这种档次的旅馆来说，住宿条件算是不错了。"}},{"en":"one of the different groups in a competition","cn":"（比赛的）小组","g":"[countable]","sc":"group of people/animals","ex":{"en":"He came first in his class at every event.","cn":"他每次比赛都是所在小组的第一名。"}},{"en":"an attractive quality or a high level of skill that is impressive","cn":"优雅；典雅；高超","g":"[uncountable]","sc":"skill/style","ex":{"en":"She has class all right—she looks like a model.","cn":"她的确风姿娴雅，看上去像模特儿一样。"}},{"en":"one of the levels of achievement in a British university degree exam","cn":"（英国学位考试的）等级","g":"[countable]","sc":"of university degree","ex":{"en":"a first-/second-/third-class degree","cn":"一级优等／二级优等／第三等学位"}},{"en":"a group into which animals, plants, etc. that have similar characteristics are divided, below a phylum","cn":"（动植物等分类的）纲","g":"[countable]","sc":"biology"},{"en":"to think or decide that somebody/something is a particular type of person or thing","cn":"把…看作（或分类、归类）","ex":{"en":"Immigrant workers were classed as aliens.","cn":"移民来的工人被归入侨民类。"},"pos":"verb"},{"en":"very good","cn":"很好的；优秀的；出色的","ex":{"en":"a class player/performer","cn":"优秀的选手／表演者"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"班级;班","en":"A class is a group of pupils or students who are taught together.","ex":{"en":"He had to spend about six months in a class with younger students","cn":"他不得不和一群比他小的学生在一个班里上了约6个月的课。"}},{"pos":"N-COUNT 可数名词","cn":"课;课程","en":"A class is a course of teaching in a particular subject.","ex":{"en":"He acquired a law degree by taking classes at night","cn":"他通过读夜校获得了法律学位。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"课堂;上课时间","en":"If you do something in class, you do it during a lesson in school.","ex":{"en":"There is lots of reading in class.","cn":"课上要进行大量的阅读。"}},{"pos":"N-SING 单数名词","cn":"(学校的)…届毕业生","en":"The students in a school or university who finish their course in a particular year are often referred to as the class of that year.","ex":{"en":"These two members of Yale's Class of '57 never miss a reunion.","cn":"这两个耶鲁大学57届毕业生每次同学聚会都参加。"}},{"pos":"N-VAR 可变名词","cn":"社会等级;阶级;阶层","en":"Class refers to the division of people in a society into groups according to their social status.","ex":{"en":"...the relationship between social classes","cn":"社会阶级关系"}},{"pos":"N-COUNT 可数名词","cn":"类别;种类;等级","en":"A class of things is a group of them with similar characteristics.","ex":{"en":"Harbour staff noticed that measurements given for the same class of boats often varied.","cn":"港口工作人员注意到，对同一类船舶的测量方法常常不一样。"}},{"pos":"VERB 动词","cn":"把…归类;把…视为","en":"If someone or something is classed as a particular thing, they are regarded as belonging to that group of things.","ex":{"en":"Since the birds interbreed they cannot be classed as different species","cn":"由于这些鸟进行杂交繁殖，不能把它们归为不同的物种。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"优雅;典雅;风度;品位","en":"If you say that someone or something has class, you mean that they are elegant and sophisticated.","ex":{"en":"He's got the same style off the pitch as he has on it — sheer class.","cn":"他场上场下都是一个样——极具风度。"}},{"pos":"ADJ 形容词","cn":"一流的;出类拔萃的","en":"If you describe someone or something as a class person or thing, you mean that they are very good.","ex":{"en":"Kite is undoubtedly a class player.","cn":"凯特绝对是个一流选手。"}},{"pos":"PHRASE 短语","cn":"出类拔萃的人物(指运动员、演奏者等)","en":"If you say that someone such as a sports player or a performer is a class act, you mean that they are very good at what they do."},{"pos":"PHRASE 短语","cn":"独领风骚的;独一无二的;出类拔萃的","en":"If someone is in a class of their own, they have more of a particular skill or quality than anyone else. If something is in a class of its own, it is better than any other similar thing.","ex":{"en":"As a player, he was in a class of his own.","cn":"作为运动员，他是独一无二的。"}}]},"examples":[{"en":"Dickens was in a different class from (= was much better than) most of his contemporaries.","cn":"与大多数的同代作家相比，狄更斯更为出类拔萃。"},{"en":"It was good accommodation for a hotel of this class.","cn":"就这种档次的旅馆来说，住宿条件算是不错了。"}]},"clock":{"media":{"img":["media/pic/clock_comp.jpg","media/thumb/clock.jpg"],"uk":"media/uk/clock__gb_1.mp3","us":"media/us/clock__us_1.mp3"},"oxford":{"phon":"klɒk","pos":"noun","senses":[{"en":"an instrument for measuring and showing time, in a room, on the wall of a building or on a computer screen (not worn or carried like a watch)","cn":"时钟；钟","g":"[countable]","ex":{"en":"The clock struck twelve/midnight.","cn":"时钟已敲响十二点／午夜十二点。"}},{"en":"the milometer in a vehicle (= an instrument that measures the number of miles the vehicle has travelled)","cn":"非法减少（车辆）计程器上的里程数；回拨（车辆）里程表作弊","g":"[singular]","lab":"informal","ex":{"en":"a used car with 20 000 miles on the clock","cn":"一辆计程器上累计行程为 2 万英里的旧汽车"}},{"en":"to reach a particular time or speed","cn":"达到（某时间或速度）","ex":{"en":"He clocked 10.09 seconds in the 100 metres final.","cn":"他 100 米决赛跑出了 10.09 秒的速度。"},"pos":"verb"},{"en":"to measure the speed at which somebody/something is travelling","cn":"测…的速度","ex":{"en":"The police clocked her doing over 100 miles an hour.","cn":"警察测出她的车速每小时超过 100 英里。"},"pos":"verb"},{"en":"to notice or recognize somebody","cn":"注意到；认出","lab":"British English, informal，，","ex":{"en":"I clocked her in the driving mirror.","cn":"我从汽车后视镜里注意到她。"},"pos":"verb"},{"en":"to hit somebody, especially on the head","cn":"击打（某人头部）","lab":"informal","ex":{"en":"He said it again, so I clocked him on the nose!","cn":"他又说了一遍，于是我一拳打中他鼻子！"},"pos":"verb"},{"en":"to illegally reduce the number of miles shown on a vehicle’s milometer (= instrument that measures the number of miles it has travelled) in order to make the vehicle appear to have travelled fewer miles than it really has","cn":"非法减少（车辆）计程器上的里程数；回拨（车辆）里程表作弊","lab":"British English, informal，，","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"钟;时钟","en":"A clock is an instrument, for example in a room or on the outside of a building, that shows what time of day it is.","ex":{"en":"He was conscious of a clock ticking","cn":"他听到了钟的嘀嗒声。"}},{"pos":"N-COUNT 可数名词","cn":"考勤钟;上下班计时钟","en":"A time clock in a factory or office is a device that is used to record the hours that people work. Each worker puts a special card into the device when they arrive and leave, and the times are recorded on the card.","ex":{"en":"Government workers were made to punch time clocks morning, noon and night.","cn":"公务员早、中、晚都要打卡。"}},{"pos":"N-COUNT 可数名词","cn":"(汽车的)车速表，里程表","en":"In a car, the clock is the instrument that shows the speed of the car or the distance it has travelled.","ex":{"en":"The car had 160,000 miles on the clock","cn":"里程表显示此车已行驶了16万英里."}},{"pos":"VERB 动词","cn":"达到(特定的时间或速度)","en":"To clock a particular time or speed in a race means to reach that time or speed.","ex":{"en":"Elliott clocked the fastest time this year for the 800 metres","cn":"埃利奥特跑出了今年800米的最快速度"}},{"pos":"VERB 动词","cn":"为…计时;为…测速","en":"If something or someone is clocked at a particular time or speed, their time or speed is measured at that level.","ex":{"en":"He has been clocked at 11 seconds for 100 metres","cn":"他100米跑了11秒。"}},{"pos":"VERB 动词","cn":"注意到;看到","en":"If you clock something, you notice or see it.","ex":{"en":"If there was any scandal in that company, you can be sure that Bobby will have clocked it.","cn":"那家公司有任何丑闻，博比肯定会知道。"}},{"pos":"PHRASE 短语","cn":"与时间赛跑;争分夺秒","en":"If you are doing something against the clock, you are doing it in a great hurry, because there is very little time.","ex":{"en":"The emergency services were working against the clock as the tide began to rise","cn":"开始涨潮了，紧急救援机构正在争分夺秒地工作。"}},{"pos":"PHRASE 短语","cn":"提前完成任务","en":"If you beat the clock, you finish doing something or succeed in doing something before the time allowed for doing it has ended."},{"pos":"PHRASE 短语","cn":"不分昼夜;日夜不停","en":"If something is done round the clock or around the clock, it is done all day and all night without stopping.","ex":{"en":"Rescue services have been working round the clock to free stranded motorists","cn":"救援部门一直在日夜不停地工作，解救被困司机。"}},{"pos":"PHRASE 短语","cn":"倒退;回到以前","en":"If you want to turn the clock back or put the clock back, you want to return to a situation that used to exist, usually because the present situation is unpleasant.","ex":{"en":"In some ways we wish we could turn the clock back","cn":"在某些方面，我们希望能回到以前。"}},{"pos":"PHRASE 短语","cn":"(通常指因不耐烦而)不断看时间，老是看钟表","en":"If you are watching the clock, you keep looking to see what time it is, usually because you are bored by something and want it to end as soon as possible.","ex":{"en":"I started to watch the clock about halfway through the class.","cn":"课大约上了一半，我就开始不停地看时间。"}},{"pos":"","cn":"","en":"相关词组：clock in clock in at clock off clock on clock out clock up"}]},"examples":[{"en":"He clocked 10.09 seconds in the 100 metres final.","cn":"他 100 米决赛跑出了 10.09 秒的速度。"},{"en":"I wish we could turn the clock back two years and give the marriage another chance.","cn":"我但愿时光能倒退两年，再给我们的婚姻一次机会。"}]},"clips":{"oxford":{"phon":"klɪp","pos":"noun","senses":[{"en":"( often in compounds","cn":"常构成复合词 ) a small metal or plastic object used for holding things together or in place （金属或塑料的）夹子，回形针"},{"en":"a piece of jewellery that fastens to your clothes","cn":"首饰别针"}]},"media":{"uk":"media/uk/clip__gb_1.mp3","us":"media/us/clip__us_1.mp3"}},"closet":{"media":{"uk":"media/uk/closet__gb_1.mp3","us":"media/us/closet__us_1.mp3"},"oxford":{"phon":"ˈklɒzɪt","pos":"noun","senses":[{"en":"a small room or a space in a wall with a door that reaches the floor, used for storing things","cn":"贮藏室；壁橱","ex":{"en":"She has a walk-in closet for all her clothes.","cn":"她有一个步入式衣帽间放她所有的衣服。"}},{"en":"used to describe people who want to keep some fact about themselves secret","cn":"隐藏（身份等）的；不公开（个人信息）的","ex":{"en":"I suspect he's a closet fascist.","cn":"我怀疑他是秘密的法西斯分子。"},"pos":"adjective"},{"en":"to put somebody in a room away from other people, especially so that they can talk privately with somebody, or so that they can be alone","cn":"把…关在房间里（尤指为了私下会谈或避免他人打扰）","ex":{"en":"He was closeted with the president for much of the day.","cn":"他与总统闭门进行了几乎一整天的密谈。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"壁橱","en":"A closet is a piece of furniture with doors at the front and shelves inside, which is used for storing things."},{"pos":"N-COUNT 可数名词","cn":"(尤指不带窗户的)小储藏间","en":"A closet is a very small room for storing things, especially one without windows."},{"pos":"ADJ 形容词","cn":"(信仰、习惯、情感)隐蔽的，不公开的","en":"Closet is used to describe a person who has beliefs, habits, or feelings which they keep secret, often because they are embarrassed about them. Closet is also used of their beliefs, habits, or feelings.","ex":{"en":"He is a closet Fascist.","cn":"他是个秘密的法西斯分子。"}},{"pos":"PHRASE 短语","cn":"公开同性恋身份；出柜","en":"If someone comes out of the closet, they tell people that they are homosexual after having kept this a secret."},{"pos":"PHRASE 短语","cn":"公开（或谈论）以前保密的事;(问题)公开","en":"If someone comes out of the closet, they reveal or discuss something which they have previously kept secret. You can also say that an issue comes out of the closet when it starts to be publicly discussed."},{"pos":"See also:","cn":"","en":"a skeleton in the closet→see: ;"}]},"examples":[{"en":"Homosexuals in public life are now coming out of the closet.","cn":"公众人物中的同性恋者如今逐渐公开自己的性取向。"},{"en":"He was closeted with the President for much of the day.","cn":"他与总统闭门进行了几乎一整天的密谈。"}]},"clever":{"media":{"uk":"media/uk/clever__gb_1.mp3","us":"media/us/clever__us_1.mp3"},"oxford":{"phon":"ˈklevə(r)","pos":"adjective","senses":[{"en":"quick at learning and understanding things","cn":"聪明的；聪颖的","lab":"especially British English","ex":{"en":"a clever child","cn":"聪明伶俐的孩子"}},{"en":"showing skill","cn":"灵巧的；熟练的","lab":"especially British English","ex":{"en":"He's always been clever at crosswords.","cn":"他在填字游戏方面一向很聪明。"}},{"en":"showing intelligence or skill, for example in the design of an object, in an idea or somebody’s actions","cn":"精明的；精巧的","ex":{"en":"a clever trick","cn":"妙计"}},{"en":"quick with words in a way that annoys people or does not show respect","cn":"油腔滑调的","lab":"British English, informal, disapproving，，，，","ex":{"en":"Don't you get clever with me!","cn":"别跟我油嘴滑舌的！"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"聪明的;聪颖的;智商高的","en":"Someone who is clever is intelligent and able to understand things easily or plan things well.","ex":{"en":"He's a very clever man","cn":"他非常聪明。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(观点、书、发明)巧妙的，绝妙的","en":"A clever idea, book, or invention is extremely effective and shows the skill of the people involved.","ex":{"en":"...a clever and gripping novel.","cn":"构思巧妙、扣人心弦的小说"}},{"pos":"PHRASE 短语","cn":"聪明过头的;过分聪明的","en":"If someone is too clever by half, they are very clever and they show their cleverness in a way that annoys other people.","ex":{"en":"His many admirers describe him as clever: his enemies as too clever by half.","cn":"崇拜他的人很多说他聪明;恨他的人则说他聪明过了头。"}}]},"examples":[{"en":"She's clever at getting what she wants.","cn":"她想把什么东西弄到手的时候总是很精的。"},{"en":"How clever of you to work it out!","cn":"你解决了这个问题真是太聪明了！"}]},"click":{"oxford":{"phon":"klɪk","pos":"verb","senses":[{"en":"to choose a particular function or item on a computer screen, etc., by pressing one of the buttons on a mouse or touchpad","cn":"（用鼠标或在触摸板上）点击，单击","g":"[transitive, intransitive]","ex":{"en":"Click here to add your opinion to the survey.","cn":"单击此处添加调查意见。"}},{"en":"to make or cause something to make a short sharp sound","cn":"（使）发出咔哒声，咔哒（或咔嚓）响","g":"[intransitive, transitive]","ex":{"en":"The cameras clicked away.","cn":"照相机咔嚓咔嚓地不停拍照。"}},{"en":"to suddenly become clear or understood","cn":"被突然明白；豁然开朗","g":"[intransitive]","lab":"informal","ex":{"en":"Suddenly it clicked—we'd been talking about different people.","cn":"我们突然领悟到原来我们谈论的不是同一个人。"}},{"en":"to become friends with somebody at once; to become popular with somebody","cn":"（与某人）即刻成为朋友；受（某人）的欢迎","g":"[intransitive]","lab":"informal","ex":{"en":"We met at a party and clicked immediately.","cn":"我们在聚会上相识，一见如故。"}},{"en":"to work well together","cn":"配合默契；运作协调","g":"[intransitive]","lab":"informal","ex":{"en":"The team don't seem to have clicked yet.","cn":"这支队伍好像还没能配合默契。"}},{"en":"the act of pressing the button on a computer mouse or touchpad","cn":"（对计算机鼠标或触摸板的）点击，单击","ex":{"en":"a mouse click","cn":"点击鼠标"},"pos":"noun"},{"en":"a short sharp sound","cn":"短而尖的声音；咔哒（或咔嚓）声","ex":{"en":"The door closed with a click.","cn":"门咔哒一声关上了。"},"pos":"noun"},{"en":"a speech sound made by pressing the tongue against the top of the mouth or the part of the mouth behind the upper front teeth, then releasing it quickly, causing air to be taken in. Clicks are found especially in southern African languages.","cn":"（尤见于非洲南部语言的）吸气音","lab":"phonetics","ex":{"en":"click languages","cn":"有吸气音的语言"},"pos":"noun"},{"en":"a kilometre","cn":"千米；公里","lab":"North American English, informal，，","pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)发出咔嗒声","en":"If something clicks or if you click it, it makes a short, sharp sound.","ex":{"en":"The applause rose to a crescendo and cameras clicked","cn":"掌声越来越响，照相机的咔嗒声不绝于耳。"}},{"pos":"VERB 动词","cn":"(用鼠标)点击","en":"If you click on an area of a computer screen, you point the cursor at that area and press one of the buttons on the mouse in order to make something happen.","ex":{"en":"I clicked on a link and recent reviews of the production came up.","cn":"我点击了一个链接，有关该剧的最新评论弹了出来。"}},{"pos":"VERB 动词","cn":"豁然开朗;突然醒悟","en":"When you suddenly understand something, you can say that it clicks .","ex":{"en":"When I saw the television report, it all clicked","cn":"我看到电视报道时才恍然大悟。"}},{"pos":"V-RECIP 相互动词","cn":"（与…）一见如故;（与…）相见恨晚","en":"If you click with someone, you like each other and become friendly as soon as you meet. You can also say that two people click.","ex":{"en":"They clicked immediately. They loved the same things.","cn":"他们随即一见如故，两人的很多爱好都相同。"}},{"pos":"","cn":"","en":"to click your heels→see: ; to click into place→see: ;"}]},"media":{"uk":"media/uk/click__gb_1.mp3","us":"media/us/click__us_1.mp3","img":["media/ldoce/img/click.jpg"]},"examples":[{"en":"Suddenly it clicked — we'd been talking about different people.","cn":"我们突然领悟到原来我们谈论的不是同一个人。"},{"en":"He's never really clicked with his students.","cn":"他从未真正受到过他的学生的欢迎。"}]},"closes":{"oxford":{"phon":"kləʊz","pos":"verb","senses":[{"en":"to put sth into a position so that it covers an opening; to get into this position","cn":"关；关闭；闭上"},{"en":"to move the parts of sth together so that it is no longer open","cn":"合上；合拢"}]},"media":{"uk":"media/uk/close__gb_1.mp3","us":"media/us/close__us_1.mp3"}},"classics":{"oxford":{"phon":"ˈklæsɪk","pos":"adjective","senses":[{"en":"accepted or deserving to be accepted as one of the best or most important of its kind","cn":"最优秀的；第一流的"},{"en":"with all the features you would expect to find; very typical","cn":"有特点的；有代表性的；典型的"}]}},"clams":{"oxford":{"phon":"klæm","pos":"noun","senses":[{"en":"a shellfish that can be eaten. It has a shell in two parts that can open and close.","cn":"蛤；蛤蜊；蚌"},{"en":"( informal ) to refuse to speak, especially when sb asks you about sth （","cn":"尤指被询问时）拒绝说话，拒不开口，闭口不言"}]},"media":{"img":["media/ldoce/img/clams.jpg"]}},"clerks":{"oxford":{"phon":"klɑːk","pos":"noun","senses":[{"en":"a person whose job is to keep the records or accounts in an office, shop/store, etc.","cn":"职员；簿记员；文书"},{"en":"an official in charge of the records of a council, court, etc. （","cn":"议会、法院等的）书记员"}]}},"classes":{"oxford":{"phon":"klɑːs","pos":"noun","senses":[{"en":"a group of students who are taught together","cn":"班；班级"},{"en":"an occasion when a group of students meet to be taught","cn":"课；上课"}]}},"clusters":{"oxford":{"phon":"ˈklʌstə(r)","pos":"noun","senses":[{"en":"a group of things of the same type that grow or appear close together （","cn":"同类物丛生或聚集的）簇，团，束，串"},{"en":"a group of people, animals or things close together （","cn":"人或动物的）群，团，组；（物品的）堆，批"}]}},"cloaks":{"oxford":{"phon":"kləʊk","pos":"noun","senses":[{"en":"a type of coat that has no sleeves, fastens at the neck and hangs loosely from the shoulders, worn especially in the past （","cn":"尤指旧时的）披风，斗篷"},{"en":"( literary ) a thing that hides or covers sb/sth","cn":"遮盖物"}]}},"clouds":{"oxford":{"phon":"klaʊd","pos":"noun","senses":[{"en":"a grey or white mass made of very small drops of water, that floats in the sky","cn":"云；云朵"},{"en":"a large mass of sth in the air, for example dust or smoke, or a number of insects flying all together","cn":"云状物（如尘雾、烟雾、一群飞行的昆虫）"}]},"media":{"img":["media/ldoce/img/clouds.jpg"]}},"cleaving":{"oxford":{"phon":"kliːv","pos":"verb","senses":[{"en":"( old-fashioned or literary ) to split or cut sth in two using sth sharp and heavy","cn":"劈开；砍开；剁开"},{"en":"( old-fashioned or literary ) to move quickly through sth","cn":"迅速穿过；迅速穿越"}]}},"climates":{"oxford":{"phon":"ˈklaɪmət","pos":"noun","senses":[{"en":"the regular pattern of weather conditions of a particular place","cn":"气候"},{"en":"an area with particular weather conditions","cn":"气候区"}]}},"cleared":{"oxford":{"phon":"klɪə(r)","pos":"adj.","senses":[{"en":"easy to understand and not causing any confusion","cn":"清晰易懂的；明白清楚的；不含混的"},{"en":"obvious and leaving no doubt at all","cn":"明显的；显然的；明确的"}]}},"clients":{"oxford":{"phon":"ˈklaɪənt","pos":"noun","senses":[{"en":"a person who uses the services or advice of a professional person or organization","cn":"委托人；当事人；客户"},{"en":"( computing","cn":"计 ) a computer that is linked to a server （连接在服务器上的）客户机"}]}},"climes":{"oxford":{"phon":"klaɪm","pos":"noun","senses":[{"en":"a country with a particular kind of climate （","cn":"具有某种气候的）地区，地带；气候带"}]}},"claimed":{"oxford":{"phon":"kleɪm","pos":"verb","senses":[{"en":"to say that sth is true although it has not been proved and other people may not believe it","cn":"宣称；声称；断言"},{"en":"to demand or ask for sth because you believe it is your legal right to own or to have it","cn":"要求（拥有）；索取；认领"}]}},"clings":{"oxford":{"phon":"klɪŋ","pos":"verb","senses":[{"en":"to hold on tightly to sb/sth","cn":"抓紧；紧握；紧抱"},{"en":"to stick to sth","cn":"粘住；附着"}]}},"clubs":{"oxford":{"phon":"klʌb","pos":"noun","senses":[{"en":"( especially in compounds","cn":"尤用于构成复合词 ) a group of people who meet together regularly, for a particular activity, sport, etc. 俱乐部；社团；会"},{"en":"the building or rooms that a particular club uses （","cn":"俱乐部使用的）建筑设施，活动室"}]}},"clamor":{"oxford":{"phon":"ˈklæmə(r)","pos":"verb","senses":[{"en":"( formal ) to demand sth loudly","cn":"大声（或吵闹）地要求"},{"en":"to shout loudly, especially in a confused way （","cn":"尤指乱哄哄地）大声地喊叫，呼叫"}]}},"cleaned":{"oxford":{"phon":"kliːn","pos":"adjective","senses":[{"en":"not dirty","cn":"洁净的；干净的"},{"en":"having a clean appearance and clean surroundings","cn":"爱干净的；爱整洁的"}]}},"climbs":{"oxford":{"phon":"klaɪm","pos":"verb","senses":[{"en":"to go up sth towards the top","cn":"攀登；爬"},{"en":"to move somewhere, especially with difficulty or effort （","cn":"尤指吃力地向某处）爬"}]}},"classmates":{"oxford":{"phon":"ˈklɑːsmeɪt","pos":"noun","senses":[{"en":"a person who is or was in the same class as you at school or college","cn":"同班同学"}]}},"climbed":{"oxford":{"phon":"klaɪm","pos":"verb","senses":[{"en":"to go up sth towards the top","cn":"攀登；爬"},{"en":"to move somewhere, especially with difficulty or effort （","cn":"尤指吃力地向某处）爬"}]}},"climbers":{"oxford":{"phon":"ˈklaɪmə(r)","pos":"noun","senses":[{"en":"a person who climbs (especially mountains) or an animal that climbs","cn":"攀登者；登山者；攀爬的动物"},{"en":"a climbing plant","cn":"攀缘植物"}]}},"clues":{"oxford":{"phon":"kluː","pos":"noun","senses":[{"en":"an object, a piece of evidence or some information that helps the police solve a crime （","cn":"帮助警方破案的）线索，迹象"},{"en":"a fact or a piece of evidence that helps you discover the answer to a problem （","cn":"问题答案的）线索，提示"}]}},"claw":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(鸟兽的)爪，脚爪","en":"The claws of a bird or animal are the thin, hard, curved nails at the end of its feet.","ex":{"en":"The cat tried to cling to the edge by its claws.","cn":"猫试图用爪子抓住边缘。"}},{"pos":"N-COUNT 可数名词","cn":"(龙虾、螃蟹、蝎子等的)螯，钳","en":"The claws of a lobster, crab, or scorpion are the two pointed parts at the end of its legs which are used for holding things."},{"pos":"VERB 动词","cn":"（用爪子）抓（破），撕（伤），挠（坏）","en":"If an animal claws at something, it scratches or damages it with its claws.","ex":{"en":"The wolf clawed at the tree and howled the whole night.","cn":"这匹狼用爪子挠着树，嚎叫了整晚。"}},{"pos":"VERB 动词","cn":"使劲抓住;用力抓住","en":"To claw at something mean to try very hard to get hold of it.","ex":{"en":"His fingers clawed at Blake's wrist","cn":"他的手指紧紧抓住布莱克的手腕。"}},{"pos":"VERB 动词","cn":"(抓住东西)费力前进","en":"If you claw your way somewhere, you move there with great difficulty, trying desperately to find things to hold on to.","ex":{"en":"Some did manage to claw their way up iron ladders to the safety of the upper deck.","cn":"的确有人设法抓住铁梯爬上了顶层甲板，脱离了危险。"}},{"pos":"VERB 动词","cn":"不畏艰险地拼搏;坚持不懈地奋斗","en":"If someone claws their way to a successful position, they achieve it with great determination in spite of many difficulties.","ex":{"en":"Gino clawed his way out of underworld obscurity to become a millionaire hotelier.","cn":"吉诺从底层社会的无名小卒一步步奋斗成为拥有百万家财的酒店大亨。"}},{"pos":"N-PLURAL 复数名词","cn":"影响别人的言行；（尤指）尖刻的言行，令人不愉快的言行","en":"If someone gets their claws into another person, they start doing or saying things, especially unpleasant things, which affect that person.","ex":{"en":"She should take her claws out of Tom and let him get on with his life.","cn":"她不该再死死地缠着汤姆，应该让他继续自己的生活。"}},{"pos":"","cn":"","en":"相关词组：claw back"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sharp curved nail on an animal, bird, or some insects 〔","cn":"动物﹑鸟或有些昆虫的〕爪﹐螯"},{"en":"if someone gets their claws into another person, they influence them in a harmful way","cn":"对某人施加坏的影响"},{"en":"to say unpleasant things about someone in order to upset them","cn":"攻击某人﹐中伤某人"}]},"vocab":{"pos":"n v","senses":[{"en":"The word claw is all about grabbing. It could be a lobster claw or even an ambitious worker clawing his way up the corporate ladder."}]},"collocations":{"phrases":["ADJ. sharp a cat with sharp claws | powerful, strong","VERB + CLAW sharpen | dig, sink The tiger dug its claws into his leg. | show The lion growled and showed its claws. | retract","CLAW + NOUN mark","PREP. in sb's ~s The cat held a bird in its claws."]},"media":{"img":["media/ldoce/img/cub.jpg"],"uk":"media/ldoce/hwd/bre/9/claw_n0205.mp3","us":"media/ldoce/hwd/ame/3/claw1.mp3"},"examples":[{"en":"Slowly, he clawed his way out from under the collapsed building.","cn":"他艰难地从倒塌的大楼废墟底下慢慢爬了出来。"},{"en":"She clawed her way to the top of her profession.","cn":"她努力不懈，终于爬到了职业的顶峰。"}],"oxford":{"phon":"klɔː","pos":"noun","senses":[{"en":"one of the sharp curved nails on the end of an animal’s or a bird’s foot","cn":"（动物或禽类的）爪，脚爪，脚趾","ex":{"en":"The cat lashed out with its claws.","cn":"猫用爪子猛击。"}},{"en":"a long, sharp curved part of the body of some types of shellfish, used for catching and holding things","cn":"（水生有壳动物的）螯，钳","ex":{"en":"the claws of a crab","cn":"螃蟹的螯"}},{"en":"part of a tool or machine, like a claw, used for holding, pulling or lifting things","cn":"爪形夹具；（机械的）爪"},{"en":"to scratch or tear somebody/something with claws or with your nails","cn":"（用爪子或手指甲）抓，撕，挠","lab":"figurative","ex":{"en":"The cat was clawing at the leg of the chair.","cn":"那只猫在抓挠椅子腿。"},"pos":"verb"}]}},"clap":{"collins":{"senses":[{"pos":"VERB 动词","cn":"鼓掌;拍手;拍巴掌","en":"When you clap, you hit your hands together to show appreciation or attract attention.","ex":{"en":"The men danced and the women clapped","cn":"男人们跳舞，女人们拍手。"}},{"pos":"VERB 动词","cn":"快速而有力地放置","en":"If you clap your hand or an object onto something, you put it there quickly and firmly.","ex":{"en":"I clapped a hand over her mouth.","cn":"我用一只手迅速地捂住她的嘴。"}},{"pos":"VERB 动词","cn":"轻拍(背或肩膀)","en":"If you clap someone on the back or on the shoulder, you hit their back or shoulder with your hand in a friendly way.","ex":{"en":"While Onassis might clap a friend on the back, Niarchos would extend a businesslike hand.","cn":"奥纳西斯可能会拍拍朋友的后背，可尼亚尔霍斯却会公事公办地伸出手来。"}},{"pos":"N-COUNT 可数名词","cn":"霹雳声;炸雷；响雷","en":"A clap of thunder is a sudden and loud noise of thunder."},{"pos":"","cn":"","en":"to clap eyes on someone→see: ;"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to hit your hands together loudly and quickly to show that you approve of and are pleased with a play, someone's performance, someone's actions etc","cn":""},{"en":"if people applaud , they clap excitedly, and often for a long time, in order to show how much they liked something or to show their support for someone","cn":""},{"en":"to give a loud, happy shout expressing admiration, approval, and often excitement, for example at a sports event or after a speech","cn":""}]},"vocab":{"pos":"1 v n 2 v 3 n","senses":[{"en":"To clap is to strike your hands together. After an awesome play, an audience will clap and maybe even stand up and hoot. A clap is also any loud or sharp noise or collision, like a clap of thunder."}]},"collocations":{"phrases":["ADV. enthusiastically, loudly The audience clapped enthusiastically."]},"media":{"uk":"media/ldoce/hwd/bre/6/clap_v0205.mp3","us":"media/ldoce/hwd/ame/3/clap1.mp3"},"examples":[{"en":"Everyone clapped us when we went up to get our prize.","cn":"我们上前领奖时，大家都为我们鼓掌。"},{"en":"‘Oh dear!’ she cried, clapping a hand over her mouth. “","cn":"哎呀！”她叫道，急急用手捂住了嘴。"}],"oxford":{"phon":"klæp","pos":"verb","senses":[{"en":"to hit your open hands together several times to show that you approve of or have enjoyed something","cn":"鼓掌，拍手（表示赞许或欣赏）","g":"[intransitive, transitive]","ex":{"en":"The audience cheered and clapped.","cn":"观众又是喝彩又是鼓掌。"}},{"en":"to hit your open hands together","cn":"拍手；击掌","g":"[intransitive, transitive]","ex":{"en":"Everyone clapped in time to the music.","cn":"大家合着音乐的节奏拍手。"}},{"en":"to lightly hit somebody with your open hand, usually in a friendly way","cn":"（常指友好地）轻拍某人的背（或肩）","g":"[transitive]","ex":{"en":"‘Cheer up, Tony,’ I said, and clapped him on the shoulder.","cn":"“振奋起来吧，托尼。”我说，轻轻拍了拍他的肩膀。"}},{"en":"to put something/somebody somewhere quickly and suddenly","cn":"急速放置","g":"[transitive]","ex":{"en":"‘Oh dear!’ she cried, clapping a hand over her mouth.","cn":"“哎呀！”她叫道，急急用手捂住了嘴。"}},{"en":"an act of clapping the hands; the sound this makes","cn":"鼓掌；拍手；掌声；拍手声","g":"[singular]","ex":{"en":"Give him a clap! (= to praise somebody at the end of a performance)","cn":"为他鼓掌吧！"},"pos":"noun"},{"en":"a sudden loud noise","cn":"砰然巨响；霹雳声","g":"[countable]","ex":{"en":"a clap of thunder","cn":"一声霹雳"},"pos":"noun"},{"en":"a disease of the sexual organs, caught by having sex with a person who already has the disease","cn":"淋病","g":"[uncountable]","lab":"informal","pos":"noun"}]}},"clump":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(树木等的)丛，簇，群","en":"A clump of things such as trees or plants is a small group of them growing together.","ex":{"en":"...a clump of trees bordering a side road.","cn":"旁路边的树丛"}},{"pos":"N-COUNT 可数名词","cn":"(电线、头发等的)团，堆","en":"A clump of things such as wires or hair is a group of them collected together in one place.","ex":{"en":"I was combing my hair and it was just falling out in clumps.","cn":"我梳头的时候，头发一团一团地往下掉。"}},{"pos":"VERB 动词","cn":"拖着沉重的步子走","en":"If someone clumps somewhere, they walk there with heavy, clumsy steps.","ex":{"en":"They went clumping up the stairs","cn":"他们拖着沉重的脚步走上楼。"}},{"pos":"VERB 动词","cn":"聚集成群;凝集成块","en":"If things clump together, they gather together and form small groups or lumps.","ex":{"en":"Brown rice takes longer to cook but it doesn't clump together as easily as white rice.","cn":"糙米不容易熟，但不会像精米那样容易粘在一起。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of trees, bushes, or other plants growing very close together 〔","cn":"树﹑灌木或其他植物的〕丛﹐簇﹐群"},{"en":"a small mass of something such as earth or mud","cn":"土块"},{"en":"the sound of someone walking with heavy steps","cn":"沉重的脚步声"}]},"vocab":{"pos":"1 n v 2 n 3 n v","senses":[{"en":"A clump is a \"bunch\" or a \"cluster.\" If you're a gardener, the last thing you want to see is a clump of weeds growing in the middle of your newly groomed lawn."}]},"collocations":{"phrases":["ADJ. great, large | little, small | dense These plants quickly form dense clumps. | straggling, tangled","VERB + CLUMP form","PREP. in a/the ~ situated in a clump of trees | ~ of great clumps of rhododendrons"]},"media":{"uk":"media/ldoce/hwd/bre/9/clump_v0205.mp3","us":"media/ldoce/hwd/ame/7/clump1.mp3"},"examples":[{"en":"The children clumped down the stairs.","cn":"孩子们脚步嗵嗵地走下了楼梯。"},{"en":"Galaxies tend to clump together in clusters.","cn":"星系往往聚集形成星团。"}],"oxford":{"phon":"klʌmp","pos":"noun","senses":[{"en":"a small group of things or people very close together, especially trees or plants; a bunch of something such as grass or hair","cn":"（尤指树或植物的）丛，簇，束，串；（人的）群，组；（草的）堆；（毛发的）缕","ex":{"en":"a clump of trees/bushes","cn":"树丛；灌木丛"}},{"en":"the sound made by somebody putting their feet down very heavily","cn":"沉重的脚步声","ex":{"en":"I heard the heavy clump of feet on the stairs.","cn":"我听到楼梯上沉重的脚步声。"}},{"en":"to put your feet down noisily and heavily as you walk","cn":"以沉重的脚步行走","g":"[intransitive]","lab":"especially British English","ex":{"en":"The children clumped down the stairs.","cn":"孩子们脚步嗵嗵地走下了楼梯。"},"pos":"verb"},{"en":"to come together to form a tight group; to be brought together to form a tight group","cn":"聚集；被聚集成群","g":"[intransitive, transitive]","ex":{"en":"Galaxies tend to clump together in clusters.","cn":"星系往往聚集形成星团。"},"pos":"verb"}]}},"climax":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(通常临近结尾的)高潮，最精彩处","en":"The climax of something is the most exciting or important moment in it, usually near the end.","ex":{"en":"For Pritchard, reaching an Olympics was the climax of her career","cn":"对普里查德来说，参加奥运会是她事业上的巅峰。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)接近高潮;(使)达到顶点","en":"The event that climaxes a sequence of events is an exciting or important event that comes at the end. You can also say that a sequence of events climaxes with a particular event.","ex":{"en":"The demonstration climaxed two weeks of strikes","cn":"游行示威将持续了两周的罢工推向了高潮。"}},{"pos":"N-VAR 可变名词","cn":"性高潮","en":"A climax is an orgasm ."},{"pos":"VERB 动词","cn":"达到性高潮","en":"When someone climaxes, they have an orgasm.","ex":{"en":"Often, a man can enjoy making love but may not be sufficiently aroused to climax.","cn":"通常情况下，男人可能会享受鱼水之欢，但未必能完全达到高潮。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the most exciting or important part of a story or event, usually near the end","cn":""},{"en":"the most exciting, enjoyable, or important moment of an event or activity, especially one that continues for a long time","cn":""},{"en":"the part of an event or activity such as a holiday or a game that is the most exciting or enjoyable, and that you remember most clearly","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"When something — like a movie or piece of music — reaches its most important or exciting part, that's the climax . A climax is a high point."}]},"collocations":{"phrases":["ADJ. big, dramatic, exciting, grand, great, powerful, thrilling | fitting","VERB + CLIMAX come to, reach The crisis reached its climax in the 1970s. | approach, near, rise to, build up to, work up to The story gradua","CLIMAX + VERB come The climax came at the end of the second act of the play.","PREP. at the ~ The hero dies at the climax of the opera. | in a/the ~ In a dramatic climax, our team lost the match by one goal. | ~ to His ","ADJ. sexual","VERB + CLIMAX achieve, reach She found it hard to achieve a/reach climax."]},"media":{"uk":"media/ldoce/hwd/bre/a/climax_n0205.mp3","us":"media/ldoce/hwd/ame/5/climax1.mp3"},"examples":[{"en":"( especially NAmE ) The sensational verdict climaxed a six-month trial.","cn":"那项引起轰动的裁决使长达六个月的审判达到了高潮。"},{"en":"The festival will climax on Sunday with a gala concert.","cn":"星期天的音乐盛会将把这个节日推向高潮。"}],"oxford":{"phon":"ˈklaɪmæks","pos":"noun","senses":[{"en":"the most exciting or important event or point in time","cn":"（重要事情或时刻的）高潮，极点，顶点","ex":{"en":"to come to/reach a climax","cn":"达到极点"}},{"en":"the most exciting part of a play, piece of music, etc. that usually happens near the end","cn":"（戏剧、音乐等通常接近结束时出现的）高潮","ex":{"en":"The book’s powerful climax is the murder of Nancy by her lover Bill Sikes.","cn":"这本书的高潮是南希被她的情人比尔·赛克斯谋杀。"}},{"en":"the highest point of sexual pleasure","cn":"性高潮","ex":{"en":"She found it hard to achieve a/reach climax.","cn":"她感觉很难达到性高潮。"}},{"en":"to come to or form the best, most exciting, or most important point in something","cn":"达成（或形成）极点（或顶点、高潮）","g":"[intransitive, transitive]","lab":"especially North American English","ex":{"en":"The festival will climax on Sunday with a gala concert.","cn":"星期天的音乐盛会将把这次会演推向高潮。"},"pos":"verb"},{"en":"to have an orgasm","cn":"达到性高潮","g":"[intransitive]","pos":"verb"}]}},"claustrophobic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(地方等)引起幽闭恐惧的","en":"You describe a place or situation as claustrophobic when it makes you feel uncomfortable and unhappy because you are enclosed or restricted.","ex":{"en":"They lived in an unhealthily claustrophobic atmosphere","cn":"他们生活在一种令人感到幽闭恐惧的不健康氛围里。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"感觉幽闭恐惧的","en":"If you feel claustrophobic, you feel very uncomfortable or anxious when you are in a small, crowded, or enclosed place.","ex":{"en":"The churning, pressing crowds made her feel claustrophobic.","cn":"挤来挤去的密集人群使她感到一种透不过气的恐惧。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong fear of being in a small enclosed space or in a situation that limits what you can do","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Claustrophobic can be used to describe someone with a fear of small, enclosed spaces. If you're claustrophobic , there is almost nothing scarier than the prospect of being trapped in an elevator for a long time."}]},"collocations":{"phrases":["VERBS be, feel, seem I felt a bit claustrophobic in the tiny room. | become, get | make sb Crowds make me claustrophobic. | find sth I find ","ADV. intensely, very | a bit, rather, somewhat The atmosphere was somewhat claustrophobic."]},"media":{"uk":"media/ldoce/hwd/bre/c/claustrophobia0205.mp3","us":"media/ldoce/hwd/ame/7/claustrophobia.mp3"},"examples":[{"en":"the claustrophobic atmosphere of the room","cn":"房间里的幽闭恐怖气氛"},{"en":"to feel claustrophobic","cn":"感到幽闭恐怖"}],"oxford":{"phon":"ˌklɒstrəˈfəʊbɪk","pos":"adjective","senses":[{"en":"giving you claustrophobia; affected by claustrophobia","cn":"引起幽闭恐怖的；患幽闭恐怖症的","ex":{"en":"the claustrophobic atmosphere of the room","cn":"房间里的幽闭恐惧气氛"}},{"en":"a person who has claustrophobia","cn":"幽闭恐怖症患者","ex":{"en":"Crowded trains are a nightmare for many claustrophobics.","cn":"拥挤的火车对许多幽闭恐惧症患者来说是一场噩梦。"},"pos":"noun"}]}},"clarinet":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"单簧管;黑管","en":"A clarinet is a musical instrument in the shape of a pipe. You play the clarinet by blowing into it and covering and uncovering the holes with your fingers."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a musical instrument like a long black tube, that you play by blowing into it and pressing key s to change the notes","cn":"单簧管﹐黑管"}]},"media":{"img":["media/ldoce/img/clarinet.jpg","media/thumb/clarinet.jpg"],"uk":"media/ldoce/hwd/bre/5/clarinet0205.mp3","us":"media/ldoce/hwd/ame/2/clarinet.mp3"},"oxford":{"phon":"ˌklærəˈnet","pos":"noun","senses":[{"en":"a musical instrument of the woodwind group. It is like a pipe in shape and has a reed and a mouthpiece at the top that you blow into.","cn":"单簧管；黑管"}]}},"clang":{"collins":{"senses":[{"pos":"VERB 动词","cn":"发出嘡啷声(或叮当声);叮当作响","en":"When a large metal object clangs, it makes a loud noise.","ex":{"en":"A little later the church bell clanged","cn":"过了一小会儿，教堂的钟当当敲响了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something made of glass or metal clinks , it makes a short ringing sound as it hits another glass or metal object","cn":""},{"en":"if something heavy made of metal clanks , it makes a short, loud noise as it hits another metal object","cn":""},{"en":"if something metal clangs , it makes a loud, long ringing noise when it hits another metal object","cn":""}]},"collocations":{"phrases":["ADJ. loud | metallic","VERB + CLANG give, let out | hear","PREP. with a ~ The door shut with a loud clang. | ~ of","PHRASES the clang of metal • Note at SOUND"]},"media":{"uk":"media/ldoce/hwd/bre/3/clang0205.mp3","us":"media/ldoce/hwd/ame/8/clang.mp3"},"examples":[{"en":"He clanged a spoon against a glass.","cn":"他用勺子叮叮当当地敲玻璃杯。"},{"en":"The trams clanged their way along the streets.","cn":"有轨电车哐啷哐啷沿街驶过。"}],"oxford":{"phon":"klæŋ","pos":"verb","senses":[{"en":"to make a loud ringing sound like that of metal being hit; to cause something to make this sound","cn":"（使）叮当作响，铿锵作响","ex":{"en":"Bells were clanging in the tower.","cn":"塔楼上的钟当当地敲响了。"}},{"en":"a loud ringing sound like metal being hit","cn":"（使）叮当作响，铿锵作响","ex":{"en":"the clang of the school bell","cn":"校铃的叮当声。"},"pos":"noun"}]}},"clank":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(巨大金属物)发出咣当声，发出当啷声","en":"When large metal objects clank, they make a noise because they are hitting together or hitting against something hard.","ex":{"en":"A pan rattled and clanked","cn":"平底锅叮叮咣咣地响。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something made of glass or metal clinks , it makes a short ringing sound as it hits another glass or metal object","cn":""},{"en":"if something heavy made of metal clanks , it makes a short, loud noise as it hits another metal object","cn":""},{"en":"if something metal clangs , it makes a loud, long ringing noise when it hits another metal object","cn":""}]},"collocations":{"phrases":["ADJ. loud","PREP. with a ~ The door opened with a clank. | ~ of the clank and rattle of the trams","PHRASES the clank of machinery"]},"media":{"uk":"media/ldoce/hwd/bre/7/clank0205.mp3","us":"media/ldoce/hwd/ame/9/clank.mp3"},"examples":[{"en":"The guard clanked his heavy ring of keys.","cn":"看守把他的那串沉甸甸的钥匙弄得叮当响。"},{"en":"I heard a door clank shut.","cn":"我听见门咣地一声关上了。"}],"oxford":{"phon":"klæŋk","pos":"verb","senses":[{"en":"to make a loud sound like pieces of metal hitting each other; to cause something to make this sound","cn":"（使）发出叮当声，发出当啷声","ex":{"en":"clanking chains","cn":"叮当作响的镣铐"}},{"en":"a loud sound like pieces of metal hitting each other","cn":"（使）发出叮当声，发出当啷声","pos":"noun"}]}},"cleanse":{"collins":{"senses":[{"pos":"VERB 动词","cn":"清洗;清除;净化","en":"To cleanse a place, person, or organization of something dirty, unpleasant, or evil means to make them free from it.","ex":{"en":"Straight after your last cigarette your body will begin to cleanse itself of tobacco toxins","cn":"一旦停止抽烟，人体立刻就会开始清除体内的烟草毒素。"}},{"pos":"VERB 动词","cn":"清理，清洗(皮肤或伤口)","en":"If you cleanse your skin or a wound, you clean it.","ex":{"en":"Catherine demonstrated the proper way to cleanse the face.","cn":"凯瑟琳演示了洁面的正确方法。"}},{"pos":"VERB 动词","cn":"(军队)清洗，驱逐","en":"If armed forces cleanse an area, they use violent methods to force certain groups of people to leave it and go to live elsewhere. You can also say that people are cleansed from an area.","ex":{"en":"...a sustained and systematic effort to ethnically cleanse the entire province","cn":"在全省范围开展的持续性、有计划的种族清洗"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to remove dirt from something","cn":""},{"en":"to clean something with water and usually soap","cn":""},{"en":"to clean a surface with a cloth, often a wet cloth","cn":""}]},"collocations":{"phrases":["ADV. thoroughly | gently","PREP. of a treatment to cleanse the body of toxins"]},"media":{"uk":"media/ldoce/hwd/bre/e/cleanse0205.mp3","us":"media/ldoce/hwd/ame/2/cleanse.mp3"},"examples":[{"en":"a cleansing cream","cn":"洁肤霜"},{"en":"Use a piece of gauze to cleanse the cut.","cn":"用一块纱布清洗伤口。"}],"oxford":{"phon":"klenz","pos":"verb","senses":[{"en":"to clean your skin or a wound","cn":"清洁（皮肤）；清洗（伤口）","g":"[transitive, intransitive]","ex":{"en":"a cleansing cream","cn":"洁肤霜"}},{"en":"to take away somebody’s guilty feelings or sin","cn":"使免除（罪过）；使净化","g":"[transitive]","lab":"literary","ex":{"en":"She felt cleansed of her sins after confession.","cn":"她忏悔之后觉得自己的罪洗清了。"}}]}},"clasp":{"collins":{"senses":[{"pos":"VERB 动词","cn":"紧紧抓住;攥紧；抱紧","en":"If you clasp someone or something, you hold them tightly in your hands or arms.","ex":{"en":"She clasped the children to her","cn":"她把孩子们紧紧地搂进怀里。"}},{"pos":"N-COUNT 可数名词","cn":"扣环;搭扣","en":"A clasp is a small device that fastens something.","ex":{"en":"...the clasp of her handbag.","cn":"她手提包的搭扣"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to have something in your hand, hands, or arms","cn":""},{"en":"to hold something very tightly and not let it go","cn":""},{"en":"to hold something tightly, especially because you do not want to drop or lose it","cn":""}]},"vocab":{"pos":"1 v n 2 n v","senses":[{"en":"A bracelet is held together by a clasp . A girl who gets a nice one from her boyfriend might clasp her arms around him. A clasp is a fastener. To clasp is to hold tightly."}]},"collocations":{"phrases":["ADV. tightly She clasped her bag tightly as she walked through the crowd. | lightly, loosely | warmly He clasped my hand warmly in welcome. "]},"media":{"uk":"media/ldoce/hwd/bre/8/clasp_n0205.mp3","us":"media/ldoce/hwd/ame/a/clasp1.mp3"},"examples":[{"en":"He leaned forward, his hands clasped tightly together.","cn":"他俯身向前，双手十字交错地紧握着。"},{"en":"He took her hand in his firm warm clasp.","cn":"他用温暖结实的手紧紧握住她的手。"}],"oxford":{"phon":"klɑːsp","pos":"verb","senses":[{"en":"to hold something tightly in your hand","cn":"握紧；攥紧；抓紧","ex":{"en":"He leaned forward, his hands clasped tightly together.","cn":"他俯身向前，双手十字交错地紧握着。"}},{"en":"to hold somebody/something tightly with your arms around them","cn":"抱紧；紧紧拥抱","ex":{"en":"She clasped the children in her arms.","cn":"她把孩子紧紧地搂在怀里。"}},{"en":"to fasten something with a clasp","cn":"扣紧；扣住；扣牢","ex":{"en":"She clasped the bracelet around her wrist.","cn":"她把手镯戴上手腕扣牢。"}},{"en":"a device that fastens something, such as a bag or the ends of a belt or a piece of jewellery","cn":"（包、皮带或首饰的）搭扣，扣环","g":"[countable]","ex":{"en":"the clasp of a necklace/handbag","cn":"项链扣环；手提包扣"},"pos":"noun"},{"en":"a tight hold with your hand or in your arms","cn":"紧握；紧攥；紧抱","g":"[singular]","ex":{"en":"He took her hand in his firm warm clasp.","cn":"他用温暖的手紧紧握住她的手。"},"pos":"noun"}]}},"clearance":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"清除;清理","en":"Clearance is the removal of old buildings, trees, or other things that are not wanted from an area.","ex":{"en":"...a slum clearance operation in Nairobi","cn":"内罗毕拆除贫民窟的行动"}},{"pos":"N-VAR 可变名词","cn":"(官方的)批准，许可","en":"If you get clearance to do or have something, you get official approval or permission to do or have it.","ex":{"en":"Thai Airways said the plane had been given clearance to land","cn":"泰国航空公司说，该飞机已经得到降落许可。"}},{"pos":"N-VAR 可变名词","cn":"(路面、河面与上方桥梁之间的)净空，间隙，间距","en":"The clearance of a bridge is the distance between the lowest point of the bridge and the road or the water under the bridge.","ex":{"en":"The lowest fixed bridge has 12.8m clearance.","cn":"最低的固定桥下方通行高度为12.8米。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone officially allows you to do something","cn":""},{"en":"official permission to do something, especially written permission, from someone in a position of authority","cn":""},{"en":"formal permission you give for something important that will affect you, your family, or your property","cn":""}]},"collocations":{"phrases":["ADJ. forest, land, site, slum","CLEARANCE + NOUN work | sale (= in a shop when goods are sold cheaply to get rid of them quickly) 2 official permission","ADJ. official | customs, diplomatic, entry, security","VERB + CLEARANCE get, obtain, receive You'll need to get security clearance for this job. | apply for, seek | give sb, grant sb The pilot wa","ADJ. ground We need to increase the vehicle's ground clearance.","VERB + CLEARANCE allow (sb/sth), give sb/sth, leave Make sure you allow enough clearance on each side. Always give cyclists plenty of cleara","PREP. ~ above clearance above the light to prevent overheating | ~ between There wasn't enough clearance between the bus and the top of the "]},"media":{"uk":"media/ldoce/hwd/bre/e/clearance0205.mp3","us":"media/ldoce/hwd/ame/b/clearance.mp3"},"examples":[{"en":"All employees at the submarine base require security clearance.","cn":"所有潜水艇基地的雇员必须得到安全部门的审查许可方可录用。"},{"en":"There is not much clearance for vehicles passing under this bridge.","cn":"车辆在这座桥下通过时没有多少余隙。"}],"oxford":{"phon":"ˈklɪərəns","pos":"noun","senses":[{"en":"the process of removing things that are not wanted","cn":"清除；排除；清理","g":"[countable, uncountable]","ex":{"en":"forest clearances","cn":"伐空的林地"}},{"en":"the amount of space or distance that is needed between two objects so that they do not touch each other","cn":"净空；间距；间隙","g":"[uncountable, countable]","ex":{"en":"There is not much clearance for vehicles passing under this bridge.","cn":"车辆在这座桥下通过时没有多少余隙。"}},{"en":"official permission that is given to somebody before they can work somewhere, have particular information, or do something they want to do","cn":"（录用或准许接触机密以前的）审查许可，审核批准","g":"[uncountable, countable]","ex":{"en":"I'm waiting for clearance from headquarters.","cn":"我在等待总部的录用审查许可。"}},{"en":"official permission for a person, vehicle or goods to enter or leave an airport or a country","cn":"（人员、交通工具或货物进出机场或边境的）许可，准许","g":"[uncountable]","ex":{"en":"The pilot was waiting for clearance for take-off.","cn":"飞行员在等待起飞的许可。"}},{"en":"the process of a payment into a bank account being confirmed by the bank, so the money is available for you to use","cn":"（付款的）到账","g":"[uncountable, countable]","ex":{"en":"Clearance will take seven days.","cn":"到账需要 7 天。"}},{"en":"a clearance in football (soccer) and some other sports is when a player kicks or hits the ball away from the goal of his or her own team","cn":"（足球及其他一些体育运动中的）解围","g":"[countable]"}]}},"clutter":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指没用或不需要的)杂乱的东西","en":"Clutter is a lot of things in an untidy state, especially things that are not useful or necessary.","ex":{"en":"Caroline prefers her worktops to be clear of clutter.","cn":"卡罗琳喜欢把厨房台面收拾得整整齐齐。"}},{"pos":"VERB 动词","cn":"乱堆在;凌乱地塞满","en":"If things or people clutter a place, they fill it in an untidy way.","ex":{"en":"Empty soft-drink cans clutter the desks","cn":"空饮料罐胡乱地堆在桌上。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a place untidy or dirty","cn":""},{"en":"to make a place untidy or dirty","cn":""},{"en":"if a lot of things clutter a room, desk etc, they make it untidy, especially because there is not enough space for them","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"The word clutter can mean a messy jumble of objects. The unorganized clutter of shoes, hats, shirts, belts, jackets, and pants makes it impossible to find a thing in your closet!"}]},"collocations":{"phrases":["ADJ. personal | screen to get rid of screen clutter (= on a computer)","VERB + CLUTTER clear (up), get rid of","PREP. amid/amidst/among/amongst the ~ The cat managed to find a spot to sleep amidst all the clutter of my study. | in a/the ~ The garage is"]},"media":{"uk":"media/ldoce/hwd/bre/0/clutter_n0205.mp3","us":"media/ldoce/hwd/ame/c/clutter1.mp3"},"examples":[{"en":"I don't want all these files cluttering up my desk.","cn":"我不想看到所有这些文档乱堆在我的桌子上。"},{"en":"There's always so much clutter on your desk!","cn":"你桌子上总有那么多乱七八糟的东西！"}],"oxford":{"phon":"ˈklʌtə(r)","pos":"verb","senses":[{"en":"to fill a place or area with too many things, so that it is untidy","cn":"凌乱地塞满；乱堆放","lab":"figurative","ex":{"en":"Don't clutter the page with too many diagrams.","cn":"别用太多的图表来堆砌版面。"}},{"en":"a lot of things in an untidy state, especially things that are not necessary or are not being used; a lack of order","cn":"杂乱的东西（尤指不需要或无用的）；凌乱","ex":{"en":"There's always so much clutter on your desk!","cn":"你桌子上总有那么多乱七八糟的东西！"},"pos":"noun"}]}},"clothed":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"穿着…衣服的","en":"If you are clothed in a certain way, you are dressed in that way.","ex":{"en":"He lay down on the bed fully clothed","cn":"他合衣躺在床上。"}},{"pos":"ADJ 形容词","cn":"被…覆盖的;裹着…的","en":"If a place or thing is clothed in something, it is covered in that thing.","ex":{"en":"The south side of the gorge is now clothed in trees.","cn":"现在峡谷的南边已长满树木。"}}]},"collocations":{"phrases":["VERBS be","ADV. fully Jenny was fully clothed. | lightly, partially It was warm and she was lightly clothed. Her partially clothed body was found in wo","PREP. in clothed in white","PHRASES fed and clothed the problems of keeping the family fed and clothed"]},"examples":[{"en":"She jumped fully clothed into the water.","cn":"她没有脱衣服就跳进了水里。"},{"en":"( figurative ) The valley was clothed in trees and shrubs.","cn":"树林和灌木丛覆盖着山谷。"}],"oxford":{"phon":"kləʊðd","pos":"adjective","senses":[{"en":"dressed in a particular way","cn":"衣着…；穿…衣服","lab":"figurative","ex":{"en":"a man clothed in black","cn":"黑衣男子"}}]}},"clinical":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"临床的","en":"Clinical means involving or relating to the direct medical treatment or testing of patients.","ex":{"en":"The first clinical trials were expected to begin next year.","cn":"第一批临床实验有望明年开始。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（思想、行为）非常符合逻辑的，不带感情的","en":"You use clinical to describe thought or behaviour which is very logical and does not involve any emotion.","ex":{"en":"All this questioning is so analytical and clinical — it kills romance.","cn":"整个询问分析性和逻辑性太强，浪漫的气息荡然无存。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not showing your feelings","cn":""},{"en":"not showing any feelings and especially not showing friendliness, humour, or pleasure","cn":""},{"en":"not showing the feelings that people usually show in an upsetting situation, because you have to do a job or because you really have no feelings about the situation","cn":""}]},"collocations":{"phrases":["VERBS be, seem","ADV. purely She regarded her patients from a purely clinical standpoint. | almost He looked at the body with an almost clinical detachment.","PREP. about How can you be so cold and clinical about your son's accident?"]},"media":{"uk":"media/ldoce/hwd/bre/c/clinical0205.mp3","us":"media/ldoce/hwd/ame/8/clinical.mp3"},"examples":[{"en":"clinically dead (= judged to be dead from the condition of the body)","cn":"临床死亡的（从身体的状况判断为死亡的）"},{"en":"He watched her suffering with clinical detachment.","cn":"他无动于衷地看着她受苦。"}],"oxford":{"phon":"ˈklɪnɪkl","pos":"adjective","senses":[{"en":"relating to the examination and treatment of patients and their illnesses","cn":"临床的；临床诊断的","g":"[only before noun]","ex":{"en":"clinical research (= done on patients, not just considering theory)","cn":"临床研究"}},{"en":"cold and calm and without feeling or sympathy","cn":"冷淡的；无动于衷的；无同情心的","lab":"disapproving","ex":{"en":"He watched her suffering with clinical detachment.","cn":"他无动于衷地看着她受苦。"}},{"en":"very plain; without decoration","cn":"简陋的；无装饰的","lab":"disapproving","ex":{"en":"Everything in the nursery was white and clinical and there were no pictures on the walls.","cn":"托儿所里的一切都是白色的、临床的，墙上没有任何照片。"}}]}},"claustrophobia":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"幽闭恐惧症","en":"Someone who suffers from claustrophobia feels very uncomfortable or anxious when they are in small or enclosed places."},{"pos":"N-UNCOUNT 不可数名词","cn":"幽闭恐惧的感觉;受限制产生的不适感","en":"If you talk about the claustrophobia of a place or situation, you mean it makes you feel uncomfortable or unhappy because you are enclosed or restricted.","ex":{"en":"In the claustrophobia of her parents' house she had no stimulus for creativity.","cn":"在父母那所令人感到封闭恐惧的房子里，没有任何东西可以刺激她的创作。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong fear of being in a small enclosed space or in a situation that limits what you can do","cn":"幽闭恐惧症"}]},"vocab":{"pos":"n","senses":[{"en":"Claustrophobia is an irrational or abnormal fear of being in an enclosed space. If your heart races in an elevator, or you break out in a cold sweat in a walk-in closet, you might have claustrophobia ."}]},"collocations":{"phrases":["VERB + CLAUSTROPHOBIA get, suffer from | give sb I hate lifts?they give me claustrophobia.","PHRASES a feeling of claustrophobia"]},"media":{"uk":"media/ldoce/hwd/bre/c/claustrophobia0205.mp3","us":"media/ldoce/hwd/ame/7/claustrophobia.mp3"},"examples":[{"en":"She felt she had to escape from the claustrophobia of family life.","cn":"她感到她得摆脱家庭生活的那种幽闭感觉了。"},{"en":"to suffer from claustrophobia","cn":"患幽闭恐怖症"}],"oxford":{"phon":"ˌklɒstrəˈfəʊbiə","pos":"noun","senses":[{"en":"an extreme fear of being shut in a small place; the unpleasant feeling that a person gets in a situation that limits them","cn":"幽闭恐惧（症）；因受限制而产生的不适感","ex":{"en":"to suffer from/have/get claustrophobia","cn":"患有/患有/患有幽闭恐惧症"}}]}},"clamp":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"夹子;夹具;夹钳","en":"A clamp is a device that holds two things firmly together."},{"pos":"VERB 动词","cn":"(用夹具)夹紧，夹住，固定","en":"When you clamp one thing to another, you fasten the two things together with a clamp.","ex":{"en":"Somebody forgot to bring along the U-bolts to clamp the microphones to the pole.","cn":"有人忘了带把麦克风固定在支架上的U形螺栓。"}},{"pos":"VERB 动词","cn":"将…固定(在某处)；紧紧抓住","en":"To clamp something in a particular place means to put it or hold it there firmly and tightly.","ex":{"en":"Simon finished dialing and clamped the phone to his ear","cn":"西蒙拨完号，把听筒贴在耳边。"}},{"pos":"N-COUNT 可数名词","cn":"(将违章停放的车辆扣在原地的)夹钳，车轮固定夹","en":"A clamp is a large metal device which is fitted to the wheel of an illegally parked car or other vehicle in order to prevent it from being driven away. The driver has to pay to have the clamp removed."},{"pos":"VERB 动词","cn":"给(车辆)上夹钳","en":"To clamp a car means to fit a clamp to one of its wheels so that it cannot be driven away.","ex":{"en":"Courts in Scotland have ruled it illegal to clamp a car parked on private ground and then to demand a fine.","cn":"苏格兰法院裁定，将停在私人地界上的车辆上夹钳并索要罚款的行为是违法的。"}},{"pos":"","cn":"","en":"相关词组：clamp down"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to stop an activity, especially one that you consider to be harmful or unacceptable","cn":""},{"en":"to completely stop an illegal or harmful activity","cn":""},{"en":"to take severe action to stop an illegal activity","cn":""}]},"collocations":{"phrases":["ADV. firmly, tight/tightly | together Clamp the pieces of wood together while the glue sets.","PREP. around/round She clamped her arms around him. | on/onto He clamped his hand firmly onto Jack's shoulder. | over A large hand clamped o","PHRASES clamped between your teeth He had a large cigar clamped between his teeth. | clamp shut His mouth clamped shut. PHRASAL VERBS clamp ","ADV. hard","PREP. on to clamp down hard on bullying"]},"media":{"img":["media/ldoce/img/clamp.jpg"],"uk":"media/ldoce/hwd/bre/7/clamp_v0205.mp3","us":"media/ldoce/hwd/ame/4/clamp1.mp3"},"examples":[{"en":"Clamp the two halves together until the glue dries.","cn":"用夹具把两半物品紧夹在一起，待胶干后再松开。"},{"en":"Clamp one end of the plank to the edge of the table.","cn":"把厚木板的一端用夹具固定在桌子的边上。"}],"oxford":{"phon":"klæmp","pos":"verb","senses":[{"en":"to hold something tightly, or fasten two things together, with a clamp","cn":"（用夹具）夹紧，夹住，固定","g":"[transitive]","ex":{"en":"Clamp one end of the plank to the edge of the table.","cn":"把厚木板的一端用夹具固定在桌子的边上。"}},{"en":"to hold or fasten something very tightly so that it does not move; to be held tightly","cn":"紧紧抓住；紧夹住；被抓住；被夹紧","g":"[transitive, intransitive]","ex":{"en":"He had a cigar clamped between his teeth.","cn":"他嘴里叼着一根雪茄。"}},{"en":"to fix a clamp to a car’s wheel so that the car cannot be driven away","cn":"用车轮锁锁住","g":"[transitive, usually passive]","lab":"British English","ex":{"en":"Her car had been clamped.","cn":"她的车给上了车轮锁。"}},{"en":"a tool for holding things tightly together, usually by means of a screw","cn":"夹具；夹子；夹钳","pos":"noun"},{"en":"a device that is attached to the wheel of a car that has been parked illegally, so that it cannot be driven away","cn":"车轮锁（用于锁住违章停放的车辆）","lab":"both British English","pos":"noun"}]}},"clientele":{"collins":{"senses":[{"pos":"N-SING-COLL 单数集合名词","cn":"顾客；客户；主顾","en":"The clientele of a place or organization are its customers or clients.","ex":{"en":"This pub had a mixed clientele","cn":"这家酒吧什么样的客人都有。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who buys goods or services from a shop or company","cn":""},{"en":"someone who pays for a service from a professional person or company","cn":""},{"en":"someone who goes to the shops looking for things to buy","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Your customers are your clientele . If you own a pet food store, your clientele might be two-footed and four-pawed."}]},"collocations":{"phrases":["ADJ. large, small | broad, narrow | regular, usual | exclusive, fashionable, select | international","VERB + CLIENTELE attract, have The restaurant has a large regular clientele. | cater for/to, serve The boutique caters for a rather select c"]},"media":{"uk":"media/ldoce/hwd/bre/5/clientele0205.mp3","us":"media/ldoce/hwd/ame/9/clientele.mp3"},"examples":[{"en":"an international clientele","cn":"国际客户网"},{"en":"The restaurant attracts a young clientele.","cn":"这家餐馆吸引年轻顾客。"}],"oxford":{"phon":"ˌkliːənˈtel","pos":"noun","senses":[{"en":"all the customers or clients of a shop, restaurant, organization, etc.","cn":"（统称）顾客，主顾，客户","ex":{"en":"The facilities appeal to an international clientele.","cn":"这些设施对国际客户群具有吸引力。"}}]}},"cloudy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"多云的;阴天的;阴云密布的","en":"If it is cloudy, there are a lot of clouds in the sky.","ex":{"en":"...a windy, cloudy day.","cn":"多云的大风天"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(液体)浑浊的，不清澈的","en":"A cloudy liquid is less clear than it should be."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(想法、观点或问题)模糊不清的，含糊的","en":"Ideas, opinions, or issues that are cloudy are confused or uncertain.","ex":{"en":"...an absurdly cloudy political debate","cn":"极为含糊不清的政治辩论"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"with a lot of clouds","cn":""},{"en":"grey in colour, because there are dark clouds – used especially in written descriptions","cn":""},{"en":"dark and completely covered with clouds","cn":""}]},"collocations":{"phrases":["VERBS be | start England and Wales will start cloudy. | become Later it will become cloudy with rain in places. | remain, stay It stayed clo","ADV. very | rather, slightly a rather cloudy sky 2 not clear","VERBS be, look The beer looked cloudy. | become | make sth The warm water is made cloudy by adding some milk.","ADV. very | rather, slightly Sometimes the drinking water becomes rather cloudy."]},"media":{"uk":"media/ldoce/hwd/bre/8/cloudy0205.mp3","us":"media/ldoce/hwd/ame/7/cloudy.mp3"},"examples":[{"en":"a grey, cloudy day","cn":"灰暗多云的一天"},{"en":"a cloudy night with some light rain","cn":"伴有些许小雨的多云的夜晚"}],"oxford":{"phon":"ˈklaʊdi","pos":"adjective","senses":[{"en":"covered with clouds; with a lot of clouds","cn":"被云遮住的；阴云密布的；阴天的；多云的","ex":{"en":"a grey, cloudy day","cn":"灰暗多云的一天"}},{"en":"not clear or easy to see through","cn":"不清澈的；不透明的；混浊的","ex":{"en":"The water looked cloudy and not fit to drink.","cn":"水看上去很浑浊，不适合饮用。"}}]}},"classification":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"分类;归类;类别;种类","en":"A classification is a division or category in a system which divides things into groups or types.","ex":{"en":"Its tariffs cater for four basic classifications of customer.","cn":"它的价目表适合4个基本类别的顾客。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a process in which you put something into the group or class it belongs to","cn":"归类﹐分类﹐分级"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Classification is the process of putting something into a category. Classification of all your clothes by color may make it easier for you to put together an outfit, especially if you favor a monochrome look."}]},"collocations":{"phrases":["ADJ. broad | detailed | simple | higher, lower The rooms are of the standard expected from a hotel in a higher classification. | arbitrary |","VERB + CLASSIFICATION defy a style of dancing that defies classification","CLASSIFICATION + NOUN system","PREP. ~ into the broad classification of music into classical and pop","PHRASES a system of classification"]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41classification.mp3","us":"media/ldoce/hwd/ame/a/classification.mp3"},"examples":[{"en":"a style of music that defies classification (= is like no other)","cn":"独特的音乐风格"},{"en":"the classification of wines according to quality","cn":"葡萄酒按品质的分类"}],"oxford":{"phon":"ˌklæsɪfɪˈkeɪʃn","pos":"noun","senses":[{"en":"the act or process of putting people or things into a group or class (= of classifying them)","cn":"分类；归类；分级","g":"[uncountable]","ex":{"en":"a style of music that defies classification (= is like no other)","cn":"独特的音乐风格"}},{"en":"a group, class, division, etc. into which somebody or something is put","cn":"类别；等级；门类","g":"[countable]","ex":{"en":"a document with the security classification ‘confidential’","cn":"安全级别为“机密”的文件"}},{"en":"the act of putting animals, plants, etc. into groups, classes or divisions according to their characteristics","cn":"（动植物等的）分类","g":"[uncountable]","lab":"biology","ex":{"en":"The classification of bony fish is extremely complicated.","cn":"硬骨鱼的分类极其复杂。"}},{"en":"a system of arranging books, tapes, magazines, etc. in a library into groups according to their subject","cn":"（图书馆的书、磁带、杂志等的）分类系统，编目","g":"[countable]","lab":"specialist"}]}},"cleanliness":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"卫生;清洁;干净","en":"Cleanliness is the degree to which people keep themselves and their surroundings clean.","ex":{"en":"Many of Britain's beaches fail to meet minimum standards of cleanliness.","cn":"英国许多海滩连最起码的卫生标准都达不倒。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the practice of keeping yourself or the things around you clean","cn":"清洁﹔讲卫生"}]},"collocations":{"phrases":["ADJ. excessive | personal His mother gave him a lecture about personal cleanliness.","PHRASES a standard of cleanliness, a state of cleanliness The bathroom was in a good state of cleanliness."]},"media":{"uk":"media/ldoce/hwd/bre/9/cleanliness0205.mp3","us":"media/ldoce/hwd/ame/9/cleanliness.mp3"},"examples":[{"en":"Some people are obsessive about cleanliness.","cn":"有些人有洁癖。"},{"en":"a high standard of cleanliness","cn":"很高的卫生标准"}],"oxford":{"phon":"ˈklenlinəs","pos":"noun","senses":[{"en":"the state of being clean or the habit of keeping things clean","cn":"清洁；干净；爱干净的习惯","ex":{"en":"Some people are obsessive about cleanliness.","cn":"有些人有洁癖。"}}]}},"clot":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(血液的)凝块","en":"A clot is a sticky lump that forms when blood dries up or becomes thick.","ex":{"en":"He needed emergency surgery to remove a blood clot from his brain.","cn":"他需要进行紧急手术以清除脑部的一处血块。"}},{"pos":"VERB 动词","cn":"(血液)凝结成块","en":"When blood clots, it becomes thick and forms a lump.","ex":{"en":"The patient's blood refused to clot","cn":"病人的血液无法凝结。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a liquid thickens or you thicken it, it becomes more solid and does not flow very easily","cn":""},{"en":"if a liquid sets , for example some types of food or plastics, it becomes solid or almost solid after a period of time","cn":""},{"en":"if blood clots , it becomes thicker and more solid","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A clot is a mass of coagulated blood. It's your body's way of repairing itself, stopping blood from flowing and beginning to heal a wound."}]},"collocations":{"phrases":["ADJ. blood a blood clot on her brain","VERB + CLOT dissolve, remove","CLOT + VERB form"]},"media":{"uk":"media/ldoce/hwd/bre/1/c55new3.mp3","us":"media/ldoce/hwd/ame/7/clot1.mp3"},"examples":[{"en":"They removed a clot from his brain.","cn":"他们从他的大脑里取出了血块。"},{"en":"a drug that stops blood from clotting during operations","cn":"手术时防止血液凝结成块的药物"}],"oxford":{"phon":"klɒt","pos":"noun","senses":[{"en":"a thick, almost solid mass that is formed when blood dries or becomes thicker","cn":"血块；血凝块","ex":{"en":"They removed a clot from his brain.","cn":"他们从他的大脑里取出了一个血块。"}},{"en":"a stupid person","cn":"笨蛋；傻瓜","lab":"old-fashioned, British English, informal，，，，"},{"en":"when blood or cream clots or when something clots it, it forms thick, almost solid masses or clots","cn":"（使血或乳脂）凝结成块","ex":{"en":"a drug that stops blood from clotting during operations","cn":"手术时防止血液凝结成块的药物"},"pos":"verb"}]}},"cluster":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(人或物的)组，群，簇","en":"A cluster of people or things is a small group of them close together.","ex":{"en":"...clusters of men in formal clothes","cn":"一群群身着正装的男人"}},{"pos":"VERB 动词","cn":"(人)聚集","en":"If people cluster together, they gather together in a small group.","ex":{"en":"The passengers clustered together in small groups","cn":"乘客们三五成群聚在一起。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of things held or tied together, especially flowers or keys","cn":""},{"en":"several papers, clothes, or sticks held or tied together in an untidy pile","cn":""},{"en":"a group of things of the same kind that are close together in a place","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A cluster is a small group of people or things. When you and your friends huddle awkwardly around the snack table at a party, whispering and trying to muster enough nerve to hit the dance floor, you’ve formed a cluster ."}]},"collocations":{"phrases":["ADV. closely, tightly | together The group clustered together closely.","PREP. about/around/round The children clustered around their teacher."]},"media":{"uk":"media/ldoce/hwd/bre/3/cluster_n0205.mp3","us":"media/ldoce/hwd/ame/6/cluster1.mp3"},"examples":[{"en":"The children clustered together in the corner of the room.","cn":"孩子们聚集在房间的角落里。"},{"en":"The doctors clustered anxiously around his bed.","cn":"医生焦急地围在他的床边。"}],"oxford":{"phon":"ˈklʌstə(r)","pos":"noun","senses":[{"en":"a group of things of the same type that grow or appear close together","cn":"（同类物丛生或聚集的）簇，团，束，串","ex":{"en":"The telescope is focused on a dense cluster of stars at the edge of the galaxy.","cn":"那架望远镜聚焦在银河系边缘一个密集的星群。"}},{"en":"a group of people, animals or things close together","cn":"（人或动物的）群，团，组；（物品的）堆，批","ex":{"en":"a cluster of spectators","cn":"一群观众"}},{"en":"a group of consonants that come together in a word or phrase, for example /str/ at the beginning of string","cn":"辅音丛；辅音连缀","lab":"phonetics","ex":{"en":"a consonant cluster","cn":"辅音丛"}},{"en":"to come together in a small group or groups","cn":"群聚；聚集","ex":{"en":"The children clustered together in the corner of the room.","cn":"孩子们聚集在房间的角落里。"},"pos":"verb"}]}},"clinic":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"诊所","en":"A clinic is a building where people go to receive medical advice or treatment.","ex":{"en":"...a family planning clinic.","cn":"计划生育诊所"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large building where sick or injured people receive medical treatment","cn":""},{"en":"a large hospital, which often has many different departments, including areas for research","cn":""},{"en":"a place, often in a hospital, where medical treatment and advice is given to people who do not need to stay in a hospital","cn":""}]},"collocations":{"phrases":["ADJ. hospital | health | special | private | outpatient | abortion, antenatal, birth control, family planning, fertility/infertility, matern","VERB + CLINIC attend, go to | hold The surgery holds a baby clinic every Wednesday afternoon. | be treated at She is being treated at a spec","PREP. at a/the~ He was treated at the hospital's eye clinic. | in a/the~ She works in a birth control clinic. | ~ for a clinic for asthma su"]},"media":{"uk":"media/ldoce/hwd/bre/1/clinic0205.mp3","us":"media/ldoce/hwd/ame/a/clinic.mp3"},"examples":[{"en":"He is being treated at the London clinic.","cn":"他正在伦敦一家私人诊所接受治疗。"},{"en":"a coaching clinic for young tennis players","cn":"为年轻网球运动员举办的研习班"}],"oxford":{"phon":"ˈklɪnɪk","pos":"noun","senses":[{"en":"a building or part of a hospital where people can go for special medical treatment or advice","cn":"诊所；（医院的）门诊部","ex":{"en":"Your local family planning clinic can give you advice about birth control.","cn":"您所在地的计划生育门诊能为您提供节育咨询。"}},{"en":"a period of time during which doctors give special medical treatment or advice","cn":"门诊时间；会诊时间","lab":"especially British English","ex":{"en":"The antenatal clinic is on Wednesdays.","cn":"产前检查时间为星期三。"}},{"en":"a private hospital or one that treats health problems of a particular kind","cn":"私人诊所；专科医院","lab":"especially British English","ex":{"en":"He is being treated at the London clinic.","cn":"他正在伦敦一家私人诊所接受治疗。"}},{"en":"a building shared by a group of doctors who work together","cn":"门诊治疗部；医疗中心","lab":"North American English"},{"en":"an occasion in a hospital when medical students learn by watching a specialist examine and treat patients","cn":"临床实习；临床教学"},{"en":"an occasion at which a professional person, especially a sportsman or sportswoman gives advice and training","cn":"（尤指运动员举办的）讲习班，培训班，研习班","ex":{"en":"a coaching clinic for young tennis players","cn":"为年轻网球运动员举办的培训班"}}]}}});
